window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["LUK"]={"book":"LUK","editions":{"fin-biblia1776":[[1,1,"Että moni on ruvennut järjestänsä kirjoittamaan niistä asioista, joista meillä täydellinen tieto on,","Että moni on ruvennut järjestänsä kirjoittamaan niistä asioista, joista meillä täydellinen tieto on,"],[1,2,"Niinkuin ne meille sanoneet ovat, jotka sen alusta itse nähneet ja sananpalveliat olleet ovat:","Niinkuin ne meille sanoneet ovat, jotka sen alusta itse nähneet ja sananpalveliat olleet ovat:"],[1,3,"Näkyy myös minulle se hyväksi, sitte kuin minä alusta kaikki visusti tutkinut olen, että minä niitä järjestänsä sinulle kirjoittaisin, hyvä Teophilus:","Näkyy myös minulle se hyväksi, sitte kuin minä alusta kaikki visusti tutkinut olen, että minä niitä järjestänsä sinulle kirjoittaisin, hyvä Teophilus:"],[1,4,"Ettäs ymmärtäisit selkiästi niiden asiain vahvan totuuden, joista sinä opetettu olet.","Ettäs ymmärtäisit selkiästi niiden asiain vahvan totuuden, joista sinä opetettu olet."],[1,5,"Herodeksen, Juudean kuninkaan, aikana oli pappi, Sakarias nimeltä, Abian vuorosta; ja hänen emäntänsä Aaronin tyttäristä, ja hänen nimensä Elisabet.","Herodeksen, Juudean kuninkaan, aikana oli pappi, Sakarias nimeltä, Abian vuorosta; ja hänen emäntänsä Aaronin tyttäristä, ja hänen nimensä Elisabet."],[1,6,"Ja he olivat molemmat hurskaita Jumalan edessä, vaeltavaiset kaikissa Herran käskyissä ja säädyissä laittamattomasti,","Ja he olivat molemmat hurskaita Jumalan edessä, vaeltavaiset kaikissa Herran käskyissä ja säädyissä laittamattomasti,"],[1,7,"Ja heillä ei ollut lasta; sillä Elisabet oli hedelmätöin, ja he olivat jo molemmat ijälliset.","Ja heillä ei ollut lasta; sillä Elisabet oli hedelmätöin, ja he olivat jo molemmat ijälliset."],[1,8,"Ja tapahtui, kuin hän vuorollansa papin virkaa toimitti Jumalan edessä,","Ja tapahtui, kuin hän vuorollansa papin virkaa toimitti Jumalan edessä,"],[1,9,"Papin viran tavan jälkeen, lankesi arpa hänelle, että hänen piti suitsuttaman, sitte kuin hän oli mennyt sisälle Herran templiin.","Papin viran tavan jälkeen, lankesi arpa hänelle, että hänen piti suitsuttaman, sitte kuin hän oli mennyt sisälle Herran templiin."],[1,10,"Ja kaikki kansan paljous rukoili ulkona suitsutuksen aikana.","Ja kaikki kansan paljous rukoili ulkona suitsutuksen aikana."],[1,11,"Mutta hänelle ilmestyi Herran enkeli, seisoin suitsutusalttarin oikealla puolella.","Mutta hänelle ilmestyi Herran enkeli, seisoin suitsutusalttarin oikealla puolella."],[1,12,"Ja kuin Sakarias hänen näki, hämmästyi hän ja pelko lankesi hänen päällensä.","Ja kuin Sakarias hänen näki, hämmästyi hän ja pelko lankesi hänen päällensä."],[1,13,"Mutta enkeli sanoi hänelle: älä pelkää, Sakarias! sillä sinun rukoukses on kuultu ja sinun emäntäs Elisabet synnyttää sinulle pojan, ja sinun pitää kutsuman hänen nimensä Johannes.","Mutta enkeli sanoi hänelle: älä pelkää, Sakarias! sillä sinun rukoukses on kuultu ja sinun emäntäs Elisabet synnyttää sinulle pojan, ja sinun pitää kutsuman hänen nimensä Johannes."],[1,14,"Ja sinulle tulee ilo ja ihastus, ja monta iloitsevat hänen syntymisestänsä.","Ja sinulle tulee ilo ja ihastus, ja monta iloitsevat hänen syntymisestänsä."],[1,15,"Sillä hän tulee suureksi Herran edessä, ja viinaa ja väkevää juomaa ei hän juo, ja hän täytetään Pyhällä Hengellä jo äitinsä kohdusta.","Sillä hän tulee suureksi Herran edessä, ja viinaa ja väkevää juomaa ei hän juo, ja hän täytetään Pyhällä Hengellä jo äitinsä kohdusta."],[1,16,"ja hän kääntää monta Israelin lapsista Herran, heidän Jumalansa tykö.","ja hän kääntää monta Israelin lapsista Herran, heidän Jumalansa tykö."],[1,17,"Ja hän käy edellä hänen edessänsä Eliaan Hengellä ja voimalla, kääntäin isäin sydämet lasten tykö ja tottelemattomat hurskasten toimen tykö, toimittaakseen Herralle valmistetun kansan.","Ja hän käy edellä hänen edessänsä Eliaan Hengellä ja voimalla, kääntäin isäin sydämet lasten tykö ja tottelemattomat hurskasten toimen tykö, toimittaakseen Herralle valmistetun kansan."],[1,18,"Ja Sakarias sanoi enkelille: mistä minä sen ymmärrän? sillä minä olen vanha ja emäntäni on jo ijällinen.","Ja Sakarias sanoi enkelille: mistä minä sen ymmärrän? sillä minä olen vanha ja emäntäni on jo ijällinen."],[1,19,"Niin enkeli vastasi ja sanoi hänelle: minä olen Gabriel, joka seison Jumalan edessä, ja olen lähetetty puhumaan sinulle ja saattamaan näitä iloisia sanomia sinulle.","Niin enkeli vastasi ja sanoi hänelle: minä olen Gabriel, joka seison Jumalan edessä, ja olen lähetetty puhumaan sinulle ja saattamaan näitä iloisia sanomia sinulle."],[1,20,"Ja katso, sinä tulet kielettömäksi ja et saa puhua hamaan siihen päivään asti, jona nämä tapahtuvat, ettet uskonut sanojani, jotka ajallansa täytetään.","Ja katso, sinä tulet kielettömäksi ja et saa puhua hamaan siihen päivään asti, jona nämä tapahtuvat, ettet uskonut sanojani, jotka ajallansa täytetään."],[1,21,"Mutta kansa odotti Sakariasta, ja ihmettelivät, että hän niin templissä viipyi.","Mutta kansa odotti Sakariasta, ja ihmettelivät, että hän niin templissä viipyi."],[1,22,"Vaan kuin hän tuli ulos, niin ei hän saanut puhua heille. Ja he ymmärsivät, että hän oli näyn templissä nähnyt. Ja hän viittasi heille, ja jäi mykäksi.","Vaan kuin hän tuli ulos, niin ei hän saanut puhua heille. Ja he ymmärsivät, että hän oli näyn templissä nähnyt. Ja hän viittasi heille, ja jäi mykäksi."],[1,23,"Ja tapahtui, että hänen virkansa päivät olivat täytetyt, niin hän meni kotiansa.","Ja tapahtui, että hänen virkansa päivät olivat täytetyt, niin hän meni kotiansa."],[1,24,"Mutta niiden päiväin jälkeen tuli hänen emäntänsä Elisabet raskaaksi ja salasi itsensä viisi kuukautta, sanoen:","Mutta niiden päiväin jälkeen tuli hänen emäntänsä Elisabet raskaaksi ja salasi itsensä viisi kuukautta, sanoen:"],[1,25,"Ja näin on Herra minulle tehnyt niinä päivinä, kuin hän minun puoleeni katsoi, että hän ottais pois minun ylönkatseeni ihmisten seassa.","Ja näin on Herra minulle tehnyt niinä päivinä, kuin hän minun puoleeni katsoi, että hän ottais pois minun ylönkatseeni ihmisten seassa."],[1,26,"Mutta kuudentena kuukautena lähetettiin enkeli Gabriel Jumalalta Galilean kaupunkiin, jonka nimi oli Nasaret,","Mutta kuudentena kuukautena lähetettiin enkeli Gabriel Jumalalta Galilean kaupunkiin, jonka nimi oli Nasaret,"],[1,27,"Neitseen tykö, joka oli kihlattu miehelle, jonka nimi oli Joseph, Davidin huoneesta; ja neitseen nimi oli Maria.","Neitseen tykö, joka oli kihlattu miehelle, jonka nimi oli Joseph, Davidin huoneesta; ja neitseen nimi oli Maria."],[1,28,"Ja enkeli tuli sisälle hänen tykönsä ja sanoi: terve, armoitettu! Herra on sinun kanssas: siunattu sinä vaimoin seassa!","Ja enkeli tuli sisälle hänen tykönsä ja sanoi: terve, armoitettu! Herra on sinun kanssas: siunattu sinä vaimoin seassa!"],[1,29,"Mutta kuin hän näki hänen, hämmästyi hän hänen puheestansa ja ajatteli, millainen se tervehdys oli.","Mutta kuin hän näki hänen, hämmästyi hän hänen puheestansa ja ajatteli, millainen se tervehdys oli."],[1,30,"Ja enkeli sanoi hänelle: älä pelkää, Maria! sillä sinä löysit armon Jumalan tykönä.","Ja enkeli sanoi hänelle: älä pelkää, Maria! sillä sinä löysit armon Jumalan tykönä."],[1,31,"Ja katso, sinä siität kohdussas ja synnytät Pojan, ja sinun pitää kutsua hänen nimensä Jesus.","Ja katso, sinä siität kohdussas ja synnytät Pojan, ja sinun pitää kutsua hänen nimensä Jesus."],[1,32,"Sen pitää oleman suuren ja pitää kutsuttaman Ylimmäisen Pojaksi. Ja Herra Jumala antaa hänelle Davidin hänen isänsä istuimen,","Sen pitää oleman suuren ja pitää kutsuttaman Ylimmäisen Pojaksi. Ja Herra Jumala antaa hänelle Davidin hänen isänsä istuimen,"],[1,33,"Ja hänen pitää Jakobin huoneen kuningas ijankaikkisesti oleman ja hänen valtakunnallansa ei pidä loppua oleman.","Ja hänen pitää Jakobin huoneen kuningas ijankaikkisesti oleman ja hänen valtakunnallansa ei pidä loppua oleman."],[1,34,"Niin sanoi Maria enkelille: kuinka tämä tulee, sillä en minä miehestä mitään tiedä?","Niin sanoi Maria enkelille: kuinka tämä tulee, sillä en minä miehestä mitään tiedä?"],[1,35,"Ja enkeli vastasi ja sanoi hänelle: Pyhä Henki tulee sinun päälles ja Ylimmäisen voima varjoo sinun: sentähden myös se pyhä, joka sinusta syntyy, pitää kutsuttaman Jumalan Pojaksi.","Ja enkeli vastasi ja sanoi hänelle: Pyhä Henki tulee sinun päälles ja Ylimmäisen voima varjoo sinun: sentähden myös se pyhä, joka sinusta syntyy, pitää kutsuttaman Jumalan Pojaksi."],[1,36,"Ja katso, Elisabet sinun lankos siitti myös pojan vanhalla ijällänsä, ja tämä on kuudes kuukausi hänelle, joka kutsuttiin hedelmättömäksi.","Ja katso, Elisabet sinun lankos siitti myös pojan vanhalla ijällänsä, ja tämä on kuudes kuukausi hänelle, joka kutsuttiin hedelmättömäksi."],[1,37,"Sillä ei Jumalan edessä ole yhtään asiaa mahdotointa.","Sillä ei Jumalan edessä ole yhtään asiaa mahdotointa."],[1,38,"Niin sanoi Maria: katso, Herran piika! tapahtukoon minulle sinun sanas jälkeen! Ja enkeli läksi hänen tyköänsä.","Niin sanoi Maria: katso, Herran piika! tapahtukoon minulle sinun sanas jälkeen! Ja enkeli läksi hänen tyköänsä."],[1,39,"Mutta Maria nousi niinä päivinä ja meni kiiruusti ylös mäkikyliin Juudan kaupunkiin.","Mutta Maria nousi niinä päivinä ja meni kiiruusti ylös mäkikyliin Juudan kaupunkiin."],[1,40,"Ja tuli Sakariaan huoneeseen ja tervehti Elisabetia.","Ja tuli Sakariaan huoneeseen ja tervehti Elisabetia."],[1,41,"Ja tapahtui, kuin Elisabet kuuli Marian tervehdyksen, hyppäsi lapsi hänen kohdussansa. Ja Elisabet täytettiin Pyhällä Hengellä,","Ja tapahtui, kuin Elisabet kuuli Marian tervehdyksen, hyppäsi lapsi hänen kohdussansa. Ja Elisabet täytettiin Pyhällä Hengellä,"],[1,42,"Ja hän huusi suurella äänellä ja sanoi: siunattu olet sinä vaimoin seassa, ja siunattu on sinun kohtus hedelmä!","Ja hän huusi suurella äänellä ja sanoi: siunattu olet sinä vaimoin seassa, ja siunattu on sinun kohtus hedelmä!"],[1,43,"Ja kusta se minulle tulee, että minun Herrani äiti tulee minun tyköni?","Ja kusta se minulle tulee, että minun Herrani äiti tulee minun tyköni?"],[1,44,"Sillä katso, kuin sinun tervehdykses ääni tuli minun korviini, hyppäsi lapsi ilosta minun kohdussani.","Sillä katso, kuin sinun tervehdykses ääni tuli minun korviini, hyppäsi lapsi ilosta minun kohdussani."],[1,45,"Ja autuas sinä, joka uskoit; sillä ne täytetään, mitkä sinulle ovat sanotut Herralta.","Ja autuas sinä, joka uskoit; sillä ne täytetään, mitkä sinulle ovat sanotut Herralta."],[1,46,"Ja Maria sanoi: Minun sieluni suuresti ylistää Herraa,","Ja Maria sanoi: Minun sieluni suuresti ylistää Herraa,"],[1,47,"Ja minun henkeni iloitsee Jumalassa, minun vapahtajassani,","Ja minun henkeni iloitsee Jumalassa, minun vapahtajassani,"],[1,48,"Että hän katsoi piikansa nöyryyttä; sillä katso, tästedes pitää kaikkein sukukuntain minua autuaaksi kutsuttaman:","Että hän katsoi piikansa nöyryyttä; sillä katso, tästedes pitää kaikkein sukukuntain minua autuaaksi kutsuttaman:"],[1,49,"Sillä Voimallinen on suuria ihmeitä tehnyt minun kohtaani, ja hänen nimensä on pyhä,","Sillä Voimallinen on suuria ihmeitä tehnyt minun kohtaani, ja hänen nimensä on pyhä,"],[1,50,"Ja hänen laupiutensa pysyy suvusta sukuun niille, jotka häntä pelkäävät.","Ja hänen laupiutensa pysyy suvusta sukuun niille, jotka häntä pelkäävät."],[1,51,"Hän osoitti voiman käsivarrellansa ja hajotti koriat heidän sydämensä mielestä.","Hän osoitti voiman käsivarrellansa ja hajotti koriat heidän sydämensä mielestä."],[1,52,"Voimalliset on hän kukistanut istuimelta ja korotti nöyrät.","Voimalliset on hän kukistanut istuimelta ja korotti nöyrät."],[1,53,"Isoovat täytti hän hyvyydellä ja jätti rikkaat tyhjäksi.","Isoovat täytti hän hyvyydellä ja jätti rikkaat tyhjäksi."],[1,54,"Hän korjasi palvelijansa Israelin, muistain omaa laupiuttansa,","Hän korjasi palvelijansa Israelin, muistain omaa laupiuttansa,"],[1,55,"(Niinkuin hän on puhunut meidän isillemme, Abrahamille ja hänen siemenellensä) ijankaikkisesti.","(Niinkuin hän on puhunut meidän isillemme, Abrahamille ja hänen siemenellensä) ijankaikkisesti."],[1,56,"Ja Maria oli hänen tykönänsä lähes kolme kuukautta ja palasi kotiansa.","Ja Maria oli hänen tykönänsä lähes kolme kuukautta ja palasi kotiansa."],[1,57,"Mutta Elisabetin synnyttämisen aika täytettiin, ja hän synnytti pojan.","Mutta Elisabetin synnyttämisen aika täytettiin, ja hän synnytti pojan."],[1,58,"Ja hänen kylällisensä ja lankonsa kuulivat, että Herra oli tehnyt suuren laupiuden hänen kanssansa, ja he iloitsivat hänen kanssansa.","Ja hänen kylällisensä ja lankonsa kuulivat, että Herra oli tehnyt suuren laupiuden hänen kanssansa, ja he iloitsivat hänen kanssansa."],[1,59,"Ja tapahtui kahdeksantena päivänä, että he tulivat lasta ympärileikkaamaan, ja kutsuivat hänen isänsä nimeltä Sakarias.","Ja tapahtui kahdeksantena päivänä, että he tulivat lasta ympärileikkaamaan, ja kutsuivat hänen isänsä nimeltä Sakarias."],[1,60,"Niin vastasi hänen äitinsä ja sanoi: ei suinkaan; vaan hän pitää kutsuttaman Johannes.","Niin vastasi hänen äitinsä ja sanoi: ei suinkaan; vaan hän pitää kutsuttaman Johannes."],[1,61,"Ja he sanoivat hänelle: ei ole ketään sinun sukukunnassas, joka kutsutaan sillä nimellä.","Ja he sanoivat hänelle: ei ole ketään sinun sukukunnassas, joka kutsutaan sillä nimellä."],[1,62,"Niin he viittasivat hänen isällensä, miksi hän tahtoi hänen nimittää.","Niin he viittasivat hänen isällensä, miksi hän tahtoi hänen nimittää."],[1,63,"Ja hän anoi taulua ja kirjoitti: Johannes on hänen nimensä. Ja kaikki ihmettelivät.","Ja hän anoi taulua ja kirjoitti: Johannes on hänen nimensä. Ja kaikki ihmettelivät."],[1,64,"Niin kohta aukeni hänen suunsa ja hänen kielensä, ja puhui kiittäin Jumalaa.","Niin kohta aukeni hänen suunsa ja hänen kielensä, ja puhui kiittäin Jumalaa."],[1,65,"Ja pelko tuli kaikkein heidän kylällistensä päälle, ja kaikissa Juudean mäkikylissä ilmoitettiin kaikki nämä sanat.","Ja pelko tuli kaikkein heidän kylällistensä päälle, ja kaikissa Juudean mäkikylissä ilmoitettiin kaikki nämä sanat."],[1,66,"Ja kaikki, jotka tämän kuulivat, panivat sydämiinsä, sanoen: minkäs luulet tästä lapsesta tulevan? Sillä Herran käsi oli hänen kanssaan.","Ja kaikki, jotka tämän kuulivat, panivat sydämiinsä, sanoen: minkäs luulet tästä lapsesta tulevan? Sillä Herran käsi oli hänen kanssaan."],[1,67,"Ja Sakarias ja hänen isänsä täytettiin Pyhällä Hengellä ja ennusti, sanoen:","Ja Sakarias ja hänen isänsä täytettiin Pyhällä Hengellä ja ennusti, sanoen:"],[1,68,"Kiitetty olkoon Herra, Israelin Jumala! sillä hän on etsinyt ja lunastanut kansansa,","Kiitetty olkoon Herra, Israelin Jumala! sillä hän on etsinyt ja lunastanut kansansa,"],[1,69,"Ja on meille korottanut autuuden sarven, Davidin palveliansa huoneessa,","Ja on meille korottanut autuuden sarven, Davidin palveliansa huoneessa,"],[1,70,"Niinkuin hän on muinen puhunut pyhäin prophetainsa suun kautta,","Niinkuin hän on muinen puhunut pyhäin prophetainsa suun kautta,"],[1,71,"Vapahtaaksensa meitä meidän vihollisiltamme ja kaikkein kädestä, jotka meitä vihaavat:","Vapahtaaksensa meitä meidän vihollisiltamme ja kaikkein kädestä, jotka meitä vihaavat:"],[1,72,"Osoittaaksensa laupiutta meidän isillemme ja muistaaksensa pyhää liittoansa,","Osoittaaksensa laupiutta meidän isillemme ja muistaaksensa pyhää liittoansa,"],[1,73,"Ja sitä valaa, jonka hän vannoi Abrahamille, meidän isällemme, meille antaaksensa:","Ja sitä valaa, jonka hän vannoi Abrahamille, meidän isällemme, meille antaaksensa:"],[1,74,"Että me, vapahdetut vihollistemme kädestä, häntä pelkäämättä palvelisimme,","Että me, vapahdetut vihollistemme kädestä, häntä pelkäämättä palvelisimme,"],[1,75,"Pyhyydessä ja hurskaudessa hänen edessänsä kaikkena meidän elinaikanamme.","Pyhyydessä ja hurskaudessa hänen edessänsä kaikkena meidän elinaikanamme."],[1,76,"Ja sinä poikainen pitää kutsuttaman Ylimmäisen prophetaksi; sillä sinun pitää käymän Herran kasvoin edessä, valmistamaan hänen teitänsä,","Ja sinä poikainen pitää kutsuttaman Ylimmäisen prophetaksi; sillä sinun pitää käymän Herran kasvoin edessä, valmistamaan hänen teitänsä,"],[1,77,"Ja antaman autuuden tunnon hänen kansallensa, heidäin synteinsä anteeksi saamiseksi,","Ja antaman autuuden tunnon hänen kansallensa, heidäin synteinsä anteeksi saamiseksi,"],[1,78,"Meidän Jumalan sydämellisen laupiuden kautta, jolla meitä on etsinyt koitto ylhäältä,","Meidän Jumalan sydämellisen laupiuden kautta, jolla meitä on etsinyt koitto ylhäältä,"],[1,79,"Valaisemaan niille, jotka pimeissä ja kuolon varjoissa istuvat, ja ojentamaan meidän jalkamme rauhan tielle.","Valaisemaan niille, jotka pimeissä ja kuolon varjoissa istuvat, ja ojentamaan meidän jalkamme rauhan tielle."],[1,80,"Mutta lapsi kasvoi ja vahvistui hengessä, ja oli korvessa siihen päivään asti, jona hänen piti Israelin kansan eteen tuleman.","Mutta lapsi kasvoi ja vahvistui hengessä, ja oli korvessa siihen päivään asti, jona hänen piti Israelin kansan eteen tuleman."],[2,1,"Mutta niinä päivinä tapahtui, että käsky kävi ulos keisarilta Augustukselta, että kaikki maailma piti verolliseksi laskettaman.","Mutta niinä päivinä tapahtui, että käsky kävi ulos keisarilta Augustukselta, että kaikki maailma piti verolliseksi laskettaman."],[2,2,"Ja tämä veron-laskemus oli ensimmäinen, joka tapahtui silloin, kun Kyrenius oli maaherra Syriassa.","Ja tämä veron-laskemus oli ensimmäinen, joka tapahtui silloin, kun Kyrenius oli maaherra Syriassa."],[2,3,"Ja kukin meni kaupunkiinsa antamaan itsiänsä arvattaa.","Ja kukin meni kaupunkiinsa antamaan itsiänsä arvattaa."],[2,4,"Niin myös Joseph Galileasta, Natsaretin kaupungista, meni ylös Juudeaan, Davidin kaupunkiin, joka kutsutaan Betlehem, (sillä hän oli Davidin huoneesta ja suvusta)","Niin myös Joseph Galileasta, Natsaretin kaupungista, meni ylös Juudeaan, Davidin kaupunkiin, joka kutsutaan Betlehem, (sillä hän oli Davidin huoneesta ja suvusta)"],[2,5,"Antamaan itsiänsä arvattaa, Marian, kihlatun emäntänsä kanssa, joka raskas oli.","Antamaan itsiänsä arvattaa, Marian, kihlatun emäntänsä kanssa, joka raskas oli."],[2,6,"Niin tapahtui heidän siellä ollessaan, että hänen synnyttämisensä päivät tulivat täytetyksi,","Niin tapahtui heidän siellä ollessaan, että hänen synnyttämisensä päivät tulivat täytetyksi,"],[2,7,"Ja hän synnytti pojan, esikoisensa, ja kapaloitsi hänen ja pani seimeen, ettei heillä ollut siaa majassa.","Ja hän synnytti pojan, esikoisensa, ja kapaloitsi hänen ja pani seimeen, ettei heillä ollut siaa majassa."],[2,8,"Ja paimenet valvoivat siinä paikkakunnassa ja vartioitsivat yöllä laumaansa.","Ja paimenet valvoivat siinä paikkakunnassa ja vartioitsivat yöllä laumaansa."],[2,9,"Ja katso, Herran enkeli seisoi heidän tykönänsä ja Herran kirkkaus ympäri valaisi heitä, ja he suuresti peljästyivät.","Ja katso, Herran enkeli seisoi heidän tykönänsä ja Herran kirkkaus ympäri valaisi heitä, ja he suuresti peljästyivät."],[2,10,"Ja enkeli sanoi heille: älkäät peljätkö! sillä katso, minä ilmoitan teille suuren ilon, joka on tuleva kaikelle kansalle:","Ja enkeli sanoi heille: älkäät peljätkö! sillä katso, minä ilmoitan teille suuren ilon, joka on tuleva kaikelle kansalle:"],[2,11,"Teille on tänäpäivänä syntynyt vapahtaja, joka on Kristus, Herra, Davidin kaupungissa.","Teille on tänäpäivänä syntynyt vapahtaja, joka on Kristus, Herra, Davidin kaupungissa."],[2,12,"Ja tämä on teille merkiksi: te löydätte lapsen kapaloituna makaavan seimessä.","Ja tämä on teille merkiksi: te löydätte lapsen kapaloituna makaavan seimessä."],[2,13,"Ja kohta oli enkelin kanssa suuri taivaallisen sotaväen joukko, jotka kiittivät Jumalaa ja sanoivat:","Ja kohta oli enkelin kanssa suuri taivaallisen sotaväen joukko, jotka kiittivät Jumalaa ja sanoivat:"],[2,14,"Kunnia olkoon Jumalalle korkeudessa, ja maassa rauha, ja ihmisille hyvä tahto!","Kunnia olkoon Jumalalle korkeudessa, ja maassa rauha, ja ihmisille hyvä tahto!"],[2,15,"Ja tapahtui, että enkelit menivät heidän tyköänsä taivaaseen, niin ne paimenet puhuivat keskenänsä: käykäämme Betlehemiin ja katsokaamme sitä mikä tapahtunut on, jonka Herra meille ilmoitti.","Ja tapahtui, että enkelit menivät heidän tyköänsä taivaaseen, niin ne paimenet puhuivat keskenänsä: käykäämme Betlehemiin ja katsokaamme sitä mikä tapahtunut on, jonka Herra meille ilmoitti."],[2,16,"Ja he tulivat kiiruhtain, ja löysivät Marian ja Josephin, niin myös lapsen, joka makasi seimessä.","Ja he tulivat kiiruhtain, ja löysivät Marian ja Josephin, niin myös lapsen, joka makasi seimessä."],[2,17,"Kuin he tämän nähneet olivat, julistivat he sen sanoman, joka heille tästä lapsesta sanottu oli,","Kuin he tämän nähneet olivat, julistivat he sen sanoman, joka heille tästä lapsesta sanottu oli,"],[2,18,"Ja kaikki, jotka sen kuulivat, ihmettelivät niitä, mitä heille paimenilta sanottu oli.","Ja kaikki, jotka sen kuulivat, ihmettelivät niitä, mitä heille paimenilta sanottu oli."],[2,19,"Mutta Maria kätki kaikki nämät sanat, tutkistellen sydämessänsä,","Mutta Maria kätki kaikki nämät sanat, tutkistellen sydämessänsä,"],[2,20,"Ja paimenet palasivat, ylistäin ja kunnioittain Jumalaa kaikista, mitä he kuulleet ja nähneet olivat, niinkuin heille sanottu oli.","Ja paimenet palasivat, ylistäin ja kunnioittain Jumalaa kaikista, mitä he kuulleet ja nähneet olivat, niinkuin heille sanottu oli."],[2,21,"Ja kuin kahdeksan päivää kulunut oli, että lapsi piti ympärileikattaman, kutsuttiin hänen nimensä Jesus, joka niin oli enkeliltä kutsuttu jo ennen kuin hän sikisi äitinsä kohdussa.","Ja kuin kahdeksan päivää kulunut oli, että lapsi piti ympärileikattaman, kutsuttiin hänen nimensä Jesus, joka niin oli enkeliltä kutsuttu jo ennen kuin hän sikisi äitinsä kohdussa."],[2,22,"Ja kuin heidän puhdistuspäivänsä olivat täytetyt Moseksen lain jälkeen, veivät he hänet Jerusalemiin, asettaaksensa häntä Herran eteen,","Ja kuin heidän puhdistuspäivänsä olivat täytetyt Moseksen lain jälkeen, veivät he hänet Jerusalemiin, asettaaksensa häntä Herran eteen,"],[2,23,"(Niinkuin kirjoitettu on Herran laissa: kaikki miehenpuoli, joka ensin avaa äitinsä kohdun, pitää kutsuttaman Herralle pyhäksi,)","(Niinkuin kirjoitettu on Herran laissa: kaikki miehenpuoli, joka ensin avaa äitinsä kohdun, pitää kutsuttaman Herralle pyhäksi,)"],[2,24,"Ja uhrataksensa, niinkuin sanottu on Herran laissa, pari mettistä eli kaksi kyhkyläisen poikaa.","Ja uhrataksensa, niinkuin sanottu on Herran laissa, pari mettistä eli kaksi kyhkyläisen poikaa."],[2,25,"Ja katso, mies oli Jerusalemissa, jonka nimi oli Simeon: tämä oli hurskas ja jumalinen mies, odottain Israelin lohdutusta, ja Pyhä Henki oli hänessä.","Ja katso, mies oli Jerusalemissa, jonka nimi oli Simeon: tämä oli hurskas ja jumalinen mies, odottain Israelin lohdutusta, ja Pyhä Henki oli hänessä."],[2,26,"Ja hänelle oli sanottu Pyhältä Hengeltä, ettei hänen pitänyt ennen kuolemaa näkemän, kuin hän näkis Herran Kristuksen.","Ja hänelle oli sanottu Pyhältä Hengeltä, ettei hänen pitänyt ennen kuolemaa näkemän, kuin hän näkis Herran Kristuksen."],[2,27,"Ja hän tuli Hengen kautta templiin. Ja kuin vanhemmat toivat lapsen Jesuksen sisälle, tehdäksensä hänen edestänsä lain tavan jälkeen,","Ja hän tuli Hengen kautta templiin. Ja kuin vanhemmat toivat lapsen Jesuksen sisälle, tehdäksensä hänen edestänsä lain tavan jälkeen,"],[2,28,"Niin hän otti hänen syliinsä, ja kiitti Jumalaa ja sanoi:","Niin hän otti hänen syliinsä, ja kiitti Jumalaa ja sanoi:"],[2,29,"Nyt sinä, Herra, lasket palvelias rauhaan menemään, sanas jälkeen;","Nyt sinä, Herra, lasket palvelias rauhaan menemään, sanas jälkeen;"],[2,30,"Sillä minun silmäni ovat nähneet sinun autuutes,","Sillä minun silmäni ovat nähneet sinun autuutes,"],[2,31,"Jonka sinä valmistit kaikkein kansain eteen,","Jonka sinä valmistit kaikkein kansain eteen,"],[2,32,"Valkeudeksi valistamaan pakanoita ja sinun kansas Israelin kunniaksi.","Valkeudeksi valistamaan pakanoita ja sinun kansas Israelin kunniaksi."],[2,33,"Ja Joseph ja hänen äitinsä ihmettelivät niitä, joita hänestä sanottiin.","Ja Joseph ja hänen äitinsä ihmettelivät niitä, joita hänestä sanottiin."],[2,34,"Simeon siunasi heitä ja sanoi Marialle, hänen äidillensä: katso, tämä on pantu lankeemiseksi ja nousemiseksi monelle Israelissa, ja merkiksi, jota vastaan sanotaan:","Simeon siunasi heitä ja sanoi Marialle, hänen äidillensä: katso, tämä on pantu lankeemiseksi ja nousemiseksi monelle Israelissa, ja merkiksi, jota vastaan sanotaan:"],[2,35,"(Ja sinunkin sielus lävitse pitää miekan käymän:) että monen sydämen ajatukset ilmoitettaisiin.","(Ja sinunkin sielus lävitse pitää miekan käymän:) että monen sydämen ajatukset ilmoitettaisiin."],[2,36,"Ja Anna prophetissa, Phanuelin tytär, Asserin suvusta, se oli joutunut pitkälle ijälle ja elänyt miehensä kanssa seitsemän ajastaikaa neitsyestänsä,","Ja Anna prophetissa, Phanuelin tytär, Asserin suvusta, se oli joutunut pitkälle ijälle ja elänyt miehensä kanssa seitsemän ajastaikaa neitsyestänsä,"],[2,37,"Ja oli leskenä lähes neljäyhdeksättäkymmentä ajastaikaa, ja ei lähtenyt templistä, palvelemasta Jumalaa paastoissa ja rukouksissa yötä ja päivää.","Ja oli leskenä lähes neljäyhdeksättäkymmentä ajastaikaa, ja ei lähtenyt templistä, palvelemasta Jumalaa paastoissa ja rukouksissa yötä ja päivää."],[2,38,"Ja tämä tuli sillä hetkellä siihen ja kunnioitti myös Herraa, ja puhui hänestä kaikille, jotka lunastusta Jerusalemissa odottivat.","Ja tämä tuli sillä hetkellä siihen ja kunnioitti myös Herraa, ja puhui hänestä kaikille, jotka lunastusta Jerusalemissa odottivat."],[2,39,"Ja sittekuin he olivat kaikki tehneet Herran lain jälkeen, palasivat he Galileaan, kaupunkiinsa Natsaretiin.","Ja sittekuin he olivat kaikki tehneet Herran lain jälkeen, palasivat he Galileaan, kaupunkiinsa Natsaretiin."],[2,40,"Mutta lapsi kasvoi ja vahvistui hengessä, ja täytettiin viisaudella, ja Jumalan armo oli hänen kanssansa.","Mutta lapsi kasvoi ja vahvistui hengessä, ja täytettiin viisaudella, ja Jumalan armo oli hänen kanssansa."],[2,41,"Ja hänen vanhempansa vaelsivat joka vuosi pääsiäisjuhlille Jerusalemiin.","Ja hänen vanhempansa vaelsivat joka vuosi pääsiäisjuhlille Jerusalemiin."],[2,42,"Ja kuin hän kahdentoistakymmenen ajastajan vanha oli, menivät he Jerusalemiin juhlapäivän tavan jälkeen.","Ja kuin hän kahdentoistakymmenen ajastajan vanha oli, menivät he Jerusalemiin juhlapäivän tavan jälkeen."],[2,43,"Ja kuin ne päivät olivat kuluneet, siinä kuin he palasivat, jäi poikainen Jesus Jerusalemiin: jota ei Joseph ja hänen äitinsä huomanneet,","Ja kuin ne päivät olivat kuluneet, siinä kuin he palasivat, jäi poikainen Jesus Jerusalemiin: jota ei Joseph ja hänen äitinsä huomanneet,"],[2,44,"Vaan luulivat hänen olevan seurassa. Ja he kävivät yhden päivän matkan, ja etsivät häntä lankoin ja tuttavien seassa.","Vaan luulivat hänen olevan seurassa. Ja he kävivät yhden päivän matkan, ja etsivät häntä lankoin ja tuttavien seassa."],[2,45,"Ja kuin ei he häntä löytäneet, palasivat he Jerusalemiin, etsien häntä.","Ja kuin ei he häntä löytäneet, palasivat he Jerusalemiin, etsien häntä."],[2,46,"Ja tapahtui kolmen päivän perästä, että he löysivät hänen templissä istuvan opettajain keskellä, kuultelevan heitä ja kysyvän heiltä.","Ja tapahtui kolmen päivän perästä, että he löysivät hänen templissä istuvan opettajain keskellä, kuultelevan heitä ja kysyvän heiltä."],[2,47,"Ja kaikki, jotka hänen kuulivat, hämmästyivät hänen ymmärrystänsä ja vastauksiansa.","Ja kaikki, jotka hänen kuulivat, hämmästyivät hänen ymmärrystänsä ja vastauksiansa."],[2,48,"Ja kuin he hänen näkivät, niin he hämmästyivät, ja hänen äitinsä sanoi hänelle: Poikani, miksis meille näin teit? katso, sinun isäs ja minä olemme murehtien etsineet sinua.","Ja kuin he hänen näkivät, niin he hämmästyivät, ja hänen äitinsä sanoi hänelle: Poikani, miksis meille näin teit? katso, sinun isäs ja minä olemme murehtien etsineet sinua."],[2,49,"Ja hän sanoi heille: mitäs te minua etsitte? ettekö tienneet, että minun pitää niissä oleman, jotka minun Isäni ovat?","Ja hän sanoi heille: mitäs te minua etsitte? ettekö tienneet, että minun pitää niissä oleman, jotka minun Isäni ovat?"],[2,50,"Ja ei he ymmärtäneet sitä sanaa, jonka hän heille sanoi.","Ja ei he ymmärtäneet sitä sanaa, jonka hän heille sanoi."],[2,51,"Ja hän meni alas heidän kanssansa ja tuli Natsaretiin, ja oli heille alamainen. Ja hänen äitinsä kätki kaikki nämät sanat sydämeensä.","Ja hän meni alas heidän kanssansa ja tuli Natsaretiin, ja oli heille alamainen. Ja hänen äitinsä kätki kaikki nämät sanat sydämeensä."],[2,52,"Ja Jesus menestyi viisaudessa ja ijässä ja armossa Jumalan ja ihmisten edessä.","Ja Jesus menestyi viisaudessa ja ijässä ja armossa Jumalan ja ihmisten edessä."],[3,1,"Mutta viidennellätoistakymmenellä keisari Tiberiuksen hallituksen vuodella, kuin Pontius Pilatus oli Juudean maaherra, ja Herodes tetrarka Galileassa, ja hänen veljensä Philippus tetrarka Itureassa ja Trakonitin maakunnassa, ja Lysanias oli tetrarka Abilenessä,","Mutta viidennellätoistakymmenellä keisari Tiberiuksen hallituksen vuodella, kuin Pontius Pilatus oli Juudean maaherra, ja Herodes tetrarka Galileassa, ja hänen veljensä Philippus tetrarka Itureassa ja Trakonitin maakunnassa, ja Lysanias oli tetrarka Abilenessä,"],[3,2,"Kuin Hannas ja Kaiphas ylimmäiset papit olivat: silloin tapahtui Jumalan sana Johannekselle Sakariaan pojalle korvessa,","Kuin Hannas ja Kaiphas ylimmäiset papit olivat: silloin tapahtui Jumalan sana Johannekselle Sakariaan pojalle korvessa,"],[3,3,"Ja hän tuli kaikkiin maan paikkoihin Jordanin ympäri ja saarnasi parannuksen kastetta syntein anteeksi antamiseksi,","Ja hän tuli kaikkiin maan paikkoihin Jordanin ympäri ja saarnasi parannuksen kastetta syntein anteeksi antamiseksi,"],[3,4,"Niinkuin kirjoitettu on Jesaias prophetan saarnaraamatussa, joka sanoo: huutavan ääni on korvessa: valmistakaat Herran tietä ja tehkäät hänen polkunsa oikiaksi.","Niinkuin kirjoitettu on Jesaias prophetan saarnaraamatussa, joka sanoo: huutavan ääni on korvessa: valmistakaat Herran tietä ja tehkäät hänen polkunsa oikiaksi."],[3,5,"Kaikki laaksot pitää täytettämän ja kaikki vuoret ja mäet alennettaman, väärät pitää ojennettaman, ja koliat tasaiseksi tieksi tehtämän,","Kaikki laaksot pitää täytettämän ja kaikki vuoret ja mäet alennettaman, väärät pitää ojennettaman, ja koliat tasaiseksi tieksi tehtämän,"],[3,6,"Ja kaikki liha pitää näkemän Jumalan autuuden.","Ja kaikki liha pitää näkemän Jumalan autuuden."],[3,7,"Niin hän sanoi kansalle, joka tuli antamaan itsiänsä kastaa häneltä: te kyykärmetten sikiät, kuka teitä neuvoi välttämään tulevaista vihaa?","Niin hän sanoi kansalle, joka tuli antamaan itsiänsä kastaa häneltä: te kyykärmetten sikiät, kuka teitä neuvoi välttämään tulevaista vihaa?"],[3,8,"Tehkäät siis soveliaat parannuksen hedelmät ja älkäät ruvetko sanomaan itsellänne: Abraham on meidän isämme; sillä minä sanon teille, että Jumala taitaa näistä kivistä herättää Abrahamille lapset.","Tehkäät siis soveliaat parannuksen hedelmät ja älkäät ruvetko sanomaan itsellänne: Abraham on meidän isämme; sillä minä sanon teille, että Jumala taitaa näistä kivistä herättää Abrahamille lapset."],[3,9,"Mutta jo on myös kirves pantu puiden juurelle; sentähden jokainen puu, joka ei tee hyvää hedelmää, hakataan pois ja tuleen heitetään.","Mutta jo on myös kirves pantu puiden juurelle; sentähden jokainen puu, joka ei tee hyvää hedelmää, hakataan pois ja tuleen heitetään."],[3,10,"Ja kansa kysyi häneltä, sanoen: mitä meidän pitää tekemän?","Ja kansa kysyi häneltä, sanoen: mitä meidän pitää tekemän?"],[3,11,"Niin hän vastaten sanoi heille: jolla on kaksi hametta, antakaan sille, jolla ei yhtään ole, ja jolla on ruokaa, hän tehkään myös niin.","Niin hän vastaten sanoi heille: jolla on kaksi hametta, antakaan sille, jolla ei yhtään ole, ja jolla on ruokaa, hän tehkään myös niin."],[3,12,"Mutta Publikanit tulivat myös antamaan heitänsä kastaa ja sanoivat hänelle: Mestari, mitä meidän pitää tekemän?","Mutta Publikanit tulivat myös antamaan heitänsä kastaa ja sanoivat hänelle: Mestari, mitä meidän pitää tekemän?"],[3,13,"Vaan hän sanoi heille: älkäät enempää vaatiko kuin teille säätty on.","Vaan hän sanoi heille: älkäät enempää vaatiko kuin teille säätty on."],[3,14,"Niin kysyivät myös häneltä sotamiehet, sanoen: mitä myös meidän pitää tekemän? Ja hän sanoi heille: älkäät kenellekään väkivaltaa taikka vääryyttä tehkö, ja tyytykäät palkkaanne.","Niin kysyivät myös häneltä sotamiehet, sanoen: mitä myös meidän pitää tekemän? Ja hän sanoi heille: älkäät kenellekään väkivaltaa taikka vääryyttä tehkö, ja tyytykäät palkkaanne."],[3,15,"Mutta kuin kansa odotti, ja kaikki ajattelivat sydämessänsä Johanneksesta: lieneekö hän Kristus?","Mutta kuin kansa odotti, ja kaikki ajattelivat sydämessänsä Johanneksesta: lieneekö hän Kristus?"],[3,16,"Vastasi Johannes, sanoen kaikille: minä tosin kastan teitä vedellä; mutta minua väkevämpi tulee, jonka kengän nauhoja en minä ole kelvollinen päästämään: hän kastaa teitä Pyhällä Hengellä ja tulella.","Vastasi Johannes, sanoen kaikille: minä tosin kastan teitä vedellä; mutta minua väkevämpi tulee, jonka kengän nauhoja en minä ole kelvollinen päästämään: hän kastaa teitä Pyhällä Hengellä ja tulella."],[3,17,"Jonka viskin on hänen kädessänsä, ja hän perkaa riihensä ja kokoo nisunsa aittaansa, mutta ruumenet polttaa hän sammumattomalla tulella.","Jonka viskin on hänen kädessänsä, ja hän perkaa riihensä ja kokoo nisunsa aittaansa, mutta ruumenet polttaa hän sammumattomalla tulella."],[3,18,"Monta tosin myös muuta hän neuvoi ja saarnasi kansalle.","Monta tosin myös muuta hän neuvoi ja saarnasi kansalle."],[3,19,"Mutta kun Herodes tetrarka nuhdeltiin häneltä, Herodiaksen veljensä Philippuksen emännän tähden ja kaikesta pahuudesta, jota Herodes teki,","Mutta kun Herodes tetrarka nuhdeltiin häneltä, Herodiaksen veljensä Philippuksen emännän tähden ja kaikesta pahuudesta, jota Herodes teki,"],[3,20,"Niin hän ylitse kaikkein teki myös sen, että hän salpasi Johanneksen vankiuteen.","Niin hän ylitse kaikkein teki myös sen, että hän salpasi Johanneksen vankiuteen."],[3,21,"Ja tapahtui, kuin kaikki kansa kastettiin, ja Jesus myös oli kastettu, ja hän rukoili, niin taivas aukeni,","Ja tapahtui, kuin kaikki kansa kastettiin, ja Jesus myös oli kastettu, ja hän rukoili, niin taivas aukeni,"],[3,22,"Ja Pyhä Henki tuli alas ruumiillisella muodolla hänen päällensä niinkuin kyyhkynen, ja ääni tuli taivaasta, joka sanoi: sinä olet minun rakas Poikani, sinuun minä mielistyin.","Ja Pyhä Henki tuli alas ruumiillisella muodolla hänen päällensä niinkuin kyyhkynen, ja ääni tuli taivaasta, joka sanoi: sinä olet minun rakas Poikani, sinuun minä mielistyin."],[3,23,"Ja Jesus oli lähes kolmenkymmenen vuotinen, joka oli (niinkuin luultiin) Josephin poika, Elin pojan,","Ja Jesus oli lähes kolmenkymmenen vuotinen, joka oli (niinkuin luultiin) Josephin poika, Elin pojan,"],[3,24,"Joka oli Mattatin poika, joka oli Levin poika, joka oli Melkin poika, joka oli Jannan poika, joka oli Josephin poika,","Joka oli Mattatin poika, joka oli Levin poika, joka oli Melkin poika, joka oli Jannan poika, joka oli Josephin poika,"],[3,25,"Joka oli Mattatian poika, joka oli Amoksen poika, joka oli Naumin poika, joka oli Eslin poika, joka oli Naggain poika,","Joka oli Mattatian poika, joka oli Amoksen poika, joka oli Naumin poika, joka oli Eslin poika, joka oli Naggain poika,"],[3,26,"Joka oli Maatin poika, joka oli Mattatian poika, joka oli Semein poika, joka oli Josephin poika, joka oli Juudan poika,","Joka oli Maatin poika, joka oli Mattatian poika, joka oli Semein poika, joka oli Josephin poika, joka oli Juudan poika,"],[3,27,"Joka oli Joannan poika, joka oli Resan poika, joka oli Zorobabelin poika, joka oli Salatielin poika, joka oli Nerin poika,","Joka oli Joannan poika, joka oli Resan poika, joka oli Zorobabelin poika, joka oli Salatielin poika, joka oli Nerin poika,"],[3,28,"Joka oli Melkin poika, joka oli Addin poika, joka oli Kosamin poika, joka oli Elmodamin poika, joka oli Eerin poika,","Joka oli Melkin poika, joka oli Addin poika, joka oli Kosamin poika, joka oli Elmodamin poika, joka oli Eerin poika,"],[3,29,"Joka oli Josen poika, joka oli Elieserin poika, joka oli Jorimin poika, joka oli Mattatin poika, joka oli Levin poika,","Joka oli Josen poika, joka oli Elieserin poika, joka oli Jorimin poika, joka oli Mattatin poika, joka oli Levin poika,"],[3,30,"Joka oli Simeonin poika, joka oli Juudan poika, joka oli Josephin poika, joka oli Jonain poika, joka oli Eliakimin poika,","Joka oli Simeonin poika, joka oli Juudan poika, joka oli Josephin poika, joka oli Jonain poika, joka oli Eliakimin poika,"],[3,31,"Joka oli Melean poika, joka oli Mainanin poika, joka oli Mattatan poika, joka oli Natanin poika, joka oli Davidin poika,","Joka oli Melean poika, joka oli Mainanin poika, joka oli Mattatan poika, joka oli Natanin poika, joka oli Davidin poika,"],[3,32,"Joka oli Jessen poika, joka oli Obedin poika, joka oli Bootsin poika, joka oli Salmonin poika, joka oli Naassonin poika,","Joka oli Jessen poika, joka oli Obedin poika, joka oli Bootsin poika, joka oli Salmonin poika, joka oli Naassonin poika,"],[3,33,"Joka oli Aminadabin poika, joka oli Aramin poika, joka oli Esromin poika, joka oli Phareksen poika, joka oli Juudan poika,","Joka oli Aminadabin poika, joka oli Aramin poika, joka oli Esromin poika, joka oli Phareksen poika, joka oli Juudan poika,"],[3,34,"Joka oli Jakobin poika, joka oli Isaakin poika, joka oli Abrahamin poika, joka oli Taran poika, joka oli Nahorin poika,","Joka oli Jakobin poika, joka oli Isaakin poika, joka oli Abrahamin poika, joka oli Taran poika, joka oli Nahorin poika,"],[3,35,"Joka oli Sarukin poika, joka oli Ragaun poika, joka oli Phalekin poika, joka oli Eberin poika, joka oli Salan poika,","Joka oli Sarukin poika, joka oli Ragaun poika, joka oli Phalekin poika, joka oli Eberin poika, joka oli Salan poika,"],[3,36,"Joka oli Kainanin poika, joka oli Arphaksadin poika, joka oli Semin poika, joka oli Noan poika, joka oli Lamekin poika,","Joka oli Kainanin poika, joka oli Arphaksadin poika, joka oli Semin poika, joka oli Noan poika, joka oli Lamekin poika,"],[3,37,"Joka oli Matusalan poika, joka oli joka oli Enokin poika, joka oli Jaredin poika, joka oli Maleleelin poika, joka oli Kainanin poika,","Joka oli Matusalan poika, joka oli joka oli Enokin poika, joka oli Jaredin poika, joka oli Maleleelin poika, joka oli Kainanin poika,"],[3,38,"Joka oli Enoksen poika, joka oli Setin poika, joka oli Adamin poika, joka oli Jumalan.","Joka oli Enoksen poika, joka oli Setin poika, joka oli Adamin poika, joka oli Jumalan."],[4,1,"Niin Jesus täynnänsä Pyhää Henkeä palasi Jordanista ja vietiin Hengeltä korpeen,","Niin Jesus täynnänsä Pyhää Henkeä palasi Jordanista ja vietiin Hengeltä korpeen,"],[4,2,"Ja kiusattiin neljäkymmentä päivää perkeleeltä, eikä syönyt mitään niinä päivinä; mutta kuin ne kuluneet olivat, sitte hän isosi.","Ja kiusattiin neljäkymmentä päivää perkeleeltä, eikä syönyt mitään niinä päivinä; mutta kuin ne kuluneet olivat, sitte hän isosi."],[4,3,"Niin perkele sanoi hänelle: jos sinä olet Jumalan Poika, niin sanos tälle kivelle, että se leiväksi tulis.","Niin perkele sanoi hänelle: jos sinä olet Jumalan Poika, niin sanos tälle kivelle, että se leiväksi tulis."],[4,4,"Ja Jesus vastasi, sanoen hänelle: kirjoitettu on: ei ihminen elä ainoasti leivästä, vaan jokaisesta Jumalan sanasta.","Ja Jesus vastasi, sanoen hänelle: kirjoitettu on: ei ihminen elä ainoasti leivästä, vaan jokaisesta Jumalan sanasta."],[4,5,"Ja perkele vei hänen korkialle vuorelle ja osoitti hänelle kaikki maan piirin valtakunnat silmänräpäyksellä,","Ja perkele vei hänen korkialle vuorelle ja osoitti hänelle kaikki maan piirin valtakunnat silmänräpäyksellä,"],[4,6,"Ja perkele sanoi hänelle: kaiken tämän vallan ja heidän kunniansa minä annan sinulle; sillä minun haltuuni ovat ne annetut, ja minä annan ne kenelle minä tahdon.","Ja perkele sanoi hänelle: kaiken tämän vallan ja heidän kunniansa minä annan sinulle; sillä minun haltuuni ovat ne annetut, ja minä annan ne kenelle minä tahdon."],[4,7,"Jos sinä siis kumarrat ja rukoilet minua, ne kaikki pitää sinun omas oleman.","Jos sinä siis kumarrat ja rukoilet minua, ne kaikki pitää sinun omas oleman."],[4,8,"Ja Jesus vastaten sanoi hänelle: mene matkaas minun tyköäni, saatana! sillä kirjoitettu on: Herraa sinun Jumalaas pitää sinun kumartaman ja häntä ainoaa palveleman.","Ja Jesus vastaten sanoi hänelle: mene matkaas minun tyköäni, saatana! sillä kirjoitettu on: Herraa sinun Jumalaas pitää sinun kumartaman ja häntä ainoaa palveleman."],[4,9,"Ja hän vei hänen Jerusalemiin ja asetti hänen templin harjalle, ja sanoi hänelle: jos sinä olet Jumalan Poika, niin laske tästä itses alas;","Ja hän vei hänen Jerusalemiin ja asetti hänen templin harjalle, ja sanoi hänelle: jos sinä olet Jumalan Poika, niin laske tästä itses alas;"],[4,10,"Sillä kirjoitettu on: hän antaa käskyn enkeleillensä sinusta varjelemaan sinua,","Sillä kirjoitettu on: hän antaa käskyn enkeleillensä sinusta varjelemaan sinua,"],[4,11,"Ja että he käsissä kantavat sinua, ettet joskus jalkaas kiveen loukkaa.","Ja että he käsissä kantavat sinua, ettet joskus jalkaas kiveen loukkaa."],[4,12,"Ja Jesus vastaten sanoi hänelle: sanottu on: ei sinun pidä kiusaaman Herraa sinun Jumalaas.","Ja Jesus vastaten sanoi hänelle: sanottu on: ei sinun pidä kiusaaman Herraa sinun Jumalaas."],[4,13,"Ja kuin kaikki kiusaus oli päätetty, meni perkele pois hetkeksi hänen tyköänsä.","Ja kuin kaikki kiusaus oli päätetty, meni perkele pois hetkeksi hänen tyköänsä."],[4,14,"Ja Jesus palasi Hengen väessä taas Galileaan, ja sanoma kuului hänestä ympäri kaiken lähimaakunnan.","Ja Jesus palasi Hengen väessä taas Galileaan, ja sanoma kuului hänestä ympäri kaiken lähimaakunnan."],[4,15,"Ja hän opetti heidän synagogissansa, ja kunnioitettiin kaikkialta,","Ja hän opetti heidän synagogissansa, ja kunnioitettiin kaikkialta,"],[4,16,"Ja tuli Natsaretiin, kussa hän kasvatettu oli, ja meni tapansa jälkeen sabbatin päivänä synagogaan, ja nousi lukemaan.","Ja tuli Natsaretiin, kussa hän kasvatettu oli, ja meni tapansa jälkeen sabbatin päivänä synagogaan, ja nousi lukemaan."],[4,17,"Ja hänelle annettiin Jesaias prophetan Raamattu. Ja kuin hän Raamatun avasi, löysi hän sen paikan, kussa kirjoitettu on:","Ja hänelle annettiin Jesaias prophetan Raamattu. Ja kuin hän Raamatun avasi, löysi hän sen paikan, kussa kirjoitettu on:"],[4,18,"Herran Henki on minun päälläni, sentähden on hän minut voidellut ja lähettänyt minun saarnaamaan köyhille hyvää sanomaa, parantamaan särjetyitä sydämiä, saarnaamaan vangeille lunastusta ja sokeille näkönsä jälleen saamista, särjetyitä vapauteen saattamaan,","Herran Henki on minun päälläni, sentähden on hän minut voidellut ja lähettänyt minun saarnaamaan köyhille hyvää sanomaa, parantamaan särjetyitä sydämiä, saarnaamaan vangeille lunastusta ja sokeille näkönsä jälleen saamista, särjetyitä vapauteen saattamaan,"],[4,19,"Saarnaamaan Herran otollista vuotta.","Saarnaamaan Herran otollista vuotta."],[4,20,"Ja kun hän pani Raamatun kiinni, antoi hän sen palvelialle ja istui, ja kaikkein silmät, jotka synagogassa olivat, katselivat hänen päällensä.","Ja kun hän pani Raamatun kiinni, antoi hän sen palvelialle ja istui, ja kaikkein silmät, jotka synagogassa olivat, katselivat hänen päällensä."],[4,21,"Ja hän rupesi heille sanomaan: tänäpänä on tämä kirjoitus täytetty, jonka te nyt kuulette.","Ja hän rupesi heille sanomaan: tänäpänä on tämä kirjoitus täytetty, jonka te nyt kuulette."],[4,22,"Ja kaikki antoivat hänelle todistuksen ja ihmettelivät niitä armon sanoja, jotka hänen suustansa läksivät ulos, ja he sanoivat: eikö tämä ole Josephin poika?","Ja kaikki antoivat hänelle todistuksen ja ihmettelivät niitä armon sanoja, jotka hänen suustansa läksivät ulos, ja he sanoivat: eikö tämä ole Josephin poika?"],[4,23,"Ja hän sanoi heille: sanokaat kaiketi minulle tämä sananlasku: parantaja, paranna itses; ne mitkä me kuulimme tapahtuneen Kapernaumissa, tee myös tässä isäs maalla!","Ja hän sanoi heille: sanokaat kaiketi minulle tämä sananlasku: parantaja, paranna itses; ne mitkä me kuulimme tapahtuneen Kapernaumissa, tee myös tässä isäs maalla!"],[4,24,"Mutta hän sanoi: totisesti sanon minä teille: ei yksikään propheta ole isänsä maalla otollinen.","Mutta hän sanoi: totisesti sanon minä teille: ei yksikään propheta ole isänsä maalla otollinen."],[4,25,"Vaan minä sanon teille totuudessa: monta leskeä oli Israelissa Eliaan ajalla, kuin taivas oli suljettu kolme vuotta ja kuusi kuukautta, niin että suuri nälkä tapahtui kaikessa maakunnassa,","Vaan minä sanon teille totuudessa: monta leskeä oli Israelissa Eliaan ajalla, kuin taivas oli suljettu kolme vuotta ja kuusi kuukautta, niin että suuri nälkä tapahtui kaikessa maakunnassa,"],[4,26,"Ja ei Elias lähetetty yhdenkään heidän tykönsä, vaan leskivaimon tykö Sidonin Sareptaan.","Ja ei Elias lähetetty yhdenkään heidän tykönsä, vaan leskivaimon tykö Sidonin Sareptaan."],[4,27,"Ja monta spitalista oli Israelissa Elisa prophetan ajalla, ja ei yksikään heistä puhdistettu, vaan Naeman Syrialainen.","Ja monta spitalista oli Israelissa Elisa prophetan ajalla, ja ei yksikään heistä puhdistettu, vaan Naeman Syrialainen."],[4,28,"Ja kaikki jotka synagogassa olivat, tulivat vihoja täyteen, kuin he nämät kuulivat,","Ja kaikki jotka synagogassa olivat, tulivat vihoja täyteen, kuin he nämät kuulivat,"],[4,29,"Ja he nousivat ylös ja ajoivat hänen ulos kaupungista, ja veivät hänen hamaan vuoren kukkulalle, jonka päälle heidän kaupunkinsa rakettu oli, syöstäksensä häntä alas.","Ja he nousivat ylös ja ajoivat hänen ulos kaupungista, ja veivät hänen hamaan vuoren kukkulalle, jonka päälle heidän kaupunkinsa rakettu oli, syöstäksensä häntä alas."],[4,30,"Mutta hän kävi ohitse heidän keskeltänsä ja meni pois,","Mutta hän kävi ohitse heidän keskeltänsä ja meni pois,"],[4,31,"Ja meni alas Kapernaumiin, Galilean kaupunkiin, ja opetti heitä siellä sabbatin päivinä.","Ja meni alas Kapernaumiin, Galilean kaupunkiin, ja opetti heitä siellä sabbatin päivinä."],[4,32,"Ja he hämmästyivät hänen opetustansa; sillä hänen puheensa oli voimallinen.","Ja he hämmästyivät hänen opetustansa; sillä hänen puheensa oli voimallinen."],[4,33,"Ja synagogassa oli ihminen, jolla oli riettaisen perkeleen henki, ja hän huusi suurella äänellä,","Ja synagogassa oli ihminen, jolla oli riettaisen perkeleen henki, ja hän huusi suurella äänellä,"],[4,34,"Sanoen: voi! mitä sinun on meidän kanssamme, Jesus Natsarealainen? tulitkos meitä hukuttamaan? minä tiedän, kukas olet, Jumalan pyhä.","Sanoen: voi! mitä sinun on meidän kanssamme, Jesus Natsarealainen? tulitkos meitä hukuttamaan? minä tiedän, kukas olet, Jumalan pyhä."],[4,35,"Ja Jesus nuhteli häntä, sanoen: vaikene ja mene ulos hänestä. Ja kuin perkele oli hänen heidän keskellänsä heittänyt, niin hän meni ulos hänestä ja ei häntä vahingoittanut mitään.","Ja Jesus nuhteli häntä, sanoen: vaikene ja mene ulos hänestä. Ja kuin perkele oli hänen heidän keskellänsä heittänyt, niin hän meni ulos hänestä ja ei häntä vahingoittanut mitään."],[4,36,"Ja pelko tuli kaikkein päälle, ja puhuivat keskenänsä, sanoen: mitä tämä lieneekään? sillä hän haastaa väellä ja voimalla riettaisia henkiä, ja lähtevät ulos.","Ja pelko tuli kaikkein päälle, ja puhuivat keskenänsä, sanoen: mitä tämä lieneekään? sillä hän haastaa väellä ja voimalla riettaisia henkiä, ja lähtevät ulos."],[4,37,"Ja sanoma hänestä kaikui ympäri kaikkiin sen maakunnan lähipaikkoihin.","Ja sanoma hänestä kaikui ympäri kaikkiin sen maakunnan lähipaikkoihin."],[4,38,"Mutta kuin hän läksi synagogasta, meni hän Simonin huoneeseen sisälle; mutta Simonin anoppi sairasti kovin vilutautia, ja he rukoilivat häntä hänen edestänsä.","Mutta kuin hän läksi synagogasta, meni hän Simonin huoneeseen sisälle; mutta Simonin anoppi sairasti kovin vilutautia, ja he rukoilivat häntä hänen edestänsä."],[4,39,"Ja hän seisoi hänen tykönänsä, ja nuhteli vilutautia, ja se luopui hänestä; ja hän nousi kohta ja palveli heitä.","Ja hän seisoi hänen tykönänsä, ja nuhteli vilutautia, ja se luopui hänestä; ja hän nousi kohta ja palveli heitä."],[4,40,"Mutta kuin aurinko laski, niin kaikki, joilla oli sairaita moninaisissa taudeissa, veivät ne hänen tykönsä. Ja hän pani jokaisen päälle kätensä ja paransi heidät.","Mutta kuin aurinko laski, niin kaikki, joilla oli sairaita moninaisissa taudeissa, veivät ne hänen tykönsä. Ja hän pani jokaisen päälle kätensä ja paransi heidät."],[4,41,"Ja monesta läksivät myös perkeleet, huutain ja sanoen: sinä olet Kristus, Jumalan Poika. Niin hän nuhteli niitä eikä sallinut heidän puhua, sillä he tiesivät hänen olevan Kristuksen.","Ja monesta läksivät myös perkeleet, huutain ja sanoen: sinä olet Kristus, Jumalan Poika. Niin hän nuhteli niitä eikä sallinut heidän puhua, sillä he tiesivät hänen olevan Kristuksen."],[4,42,"Mutta kuin päivä tuli, meni hän erämaahan, ja kansa etsi häntä, ja he menivät hänen tykönsä, ja pidättivät hänen, ettei hän heidän tyköänsä olisi mennyt pois.","Mutta kuin päivä tuli, meni hän erämaahan, ja kansa etsi häntä, ja he menivät hänen tykönsä, ja pidättivät hänen, ettei hän heidän tyköänsä olisi mennyt pois."],[4,43,"Vaan hän sanoi heille: minun pitää myös muillekin evankeliumia Jumalan valtakunnasta saarnaaman; sillä sitä varten minä olen lähetetty.","Vaan hän sanoi heille: minun pitää myös muillekin evankeliumia Jumalan valtakunnasta saarnaaman; sillä sitä varten minä olen lähetetty."],[4,44,"Ja hän saarnasi Galilean synagogissa.","Ja hän saarnasi Galilean synagogissa."],[5,1,"Niin tapahtui, kuin kansa tunki hänen tykönsä, kuulemaan Jumalan sanaa, että hän seisoi Genesaretin meren tykönä.","Niin tapahtui, kuin kansa tunki hänen tykönsä, kuulemaan Jumalan sanaa, että hän seisoi Genesaretin meren tykönä."],[5,2,"Ja näki kaksi venhettä olevan meren tykönä; mutta kalamiehet olivat niistä lähteneet ja pesivät verkkoja.","Ja näki kaksi venhettä olevan meren tykönä; mutta kalamiehet olivat niistä lähteneet ja pesivät verkkoja."],[5,3,"Niin hän meni yhteen venheeseen, joka oli Simonin, ja käski * hänen vähän maasta laskea ulos; ja hän istui ja opetti kansaa venheestä.","Niin hän meni yhteen venheeseen, joka oli Simonin, ja käski * hänen vähän maasta laskea ulos; ja hän istui ja opetti kansaa venheestä."],[5,4,"Mutta kuin hän lakkasi puhumasta, sanoi hän Simonille: vie syvälle, ja heittäkää verkkonne apajalle.","Mutta kuin hän lakkasi puhumasta, sanoi hän Simonille: vie syvälle, ja heittäkää verkkonne apajalle."],[5,5,"Ja Simon vastaten sanoi hänelle: Mestari! me olemme kaiken yön työtä tehneet ja emme mitään saaneet; mutta sinun käskystäs minä heitän ulos verkon.","Ja Simon vastaten sanoi hänelle: Mestari! me olemme kaiken yön työtä tehneet ja emme mitään saaneet; mutta sinun käskystäs minä heitän ulos verkon."],[5,6,"Ja kuin he sen tekivät, sulkivat he suuren kalain paljouden, ja heidän verkkonsa repesi.","Ja kuin he sen tekivät, sulkivat he suuren kalain paljouden, ja heidän verkkonsa repesi."],[5,7,"Ja he viittasivat kumppaneillensa, jotka olivat toisessa venheessä, tulemaan ja auttamaan heitä. Ja he tulivat ja täyttivät molemmat venheet, niin että he rupesivat vajoomaan.","Ja he viittasivat kumppaneillensa, jotka olivat toisessa venheessä, tulemaan ja auttamaan heitä. Ja he tulivat ja täyttivät molemmat venheet, niin että he rupesivat vajoomaan."],[5,8,"Kuin Simon Pietari sen näki, lankesi hän Jesuksen polvien tykö, sanoen: Herra, mene pois minun tyköäni, sillä minä olen syntinen ihminen.","Kuin Simon Pietari sen näki, lankesi hän Jesuksen polvien tykö, sanoen: Herra, mene pois minun tyköäni, sillä minä olen syntinen ihminen."],[5,9,"Sillä hämmästys oli hänen käsittänyt ja kaikki, jotka hänen kanssaan olivat, kalan saaliin tähden, jonka he saaneet olivat,","Sillä hämmästys oli hänen käsittänyt ja kaikki, jotka hänen kanssaan olivat, kalan saaliin tähden, jonka he saaneet olivat,"],[5,10,"Niin myös Jakobin ja Johanneksen, Zebedeuksen pojat, jotka olivat Simonin kumppanit. Ja Jesus sanoi Simonille: älä pelkää, tästedes sinä saat ihmisiä.","Niin myös Jakobin ja Johanneksen, Zebedeuksen pojat, jotka olivat Simonin kumppanit. Ja Jesus sanoi Simonille: älä pelkää, tästedes sinä saat ihmisiä."],[5,11,"Ja he vetivät venheet maalle ja antoivat ylön kaikki, ja seurasivat häntä.","Ja he vetivät venheet maalle ja antoivat ylön kaikki, ja seurasivat häntä."],[5,12,"Ja tapahtui, kuin hän oli yhdessä kaupungissa, katso, niin siinä oli mies spitalia täynnä; ja kuin hän näki Jesuksen, lankesi hän kasvoillensa, rukoili häntä, sanoen: Herra, jos sinä tahdot, niin sinä voit minut puhdistaa.","Ja tapahtui, kuin hän oli yhdessä kaupungissa, katso, niin siinä oli mies spitalia täynnä; ja kuin hän näki Jesuksen, lankesi hän kasvoillensa, rukoili häntä, sanoen: Herra, jos sinä tahdot, niin sinä voit minut puhdistaa."],[5,13,"Ja hän ojensi kätensä ja rupesi häneen, sanoen: minä tahdon, ole puhdas! Ja kohta spitali läksi hänestä.","Ja hän ojensi kätensä ja rupesi häneen, sanoen: minä tahdon, ole puhdas! Ja kohta spitali läksi hänestä."],[5,14,"Ja hän kielsi hänen kellenkään sanomasta: vaan mene, (sanoi hän) ja osoita itses papille, ja uhraa sinun puhditukses edestä, niin kuin Moses käski, heille todistukseksi.","Ja hän kielsi hänen kellenkään sanomasta: vaan mene, (sanoi hän) ja osoita itses papille, ja uhraa sinun puhditukses edestä, niin kuin Moses käski, heille todistukseksi."],[5,15,"Niin sanoma levisi enemmin hänestä, ja paljo kansaa kokoontui kuulemaan ja että he parannettaisiin häneltä taudeistansa.","Niin sanoma levisi enemmin hänestä, ja paljo kansaa kokoontui kuulemaan ja että he parannettaisiin häneltä taudeistansa."],[5,16,"Mutta hän meni korpeen, ja rukoili.","Mutta hän meni korpeen, ja rukoili."],[5,17,"Ja tapahtui yhtenä päivänä, kuin hän opetti, ja Pharisealaiset myös istuivat ja lainopettajat, jotka tulleet olivat jokaisesta Galilean ja Juudean kylästä ja Jerusalemista: ja Herran voima oli parantamassa heitä;","Ja tapahtui yhtenä päivänä, kuin hän opetti, ja Pharisealaiset myös istuivat ja lainopettajat, jotka tulleet olivat jokaisesta Galilean ja Juudean kylästä ja Jerusalemista: ja Herran voima oli parantamassa heitä;"],[5,18,"Ja katso, miehet kantoivat vuoteessa ihmisen, joka oli halvattu, ja he pyysivät häntä viedä sisähälle ja panna hänen eteensä.","Ja katso, miehet kantoivat vuoteessa ihmisen, joka oli halvattu, ja he pyysivät häntä viedä sisähälle ja panna hänen eteensä."],[5,19,"Ja kuin ei he löytäneet kansan tähden, kusta puolesta he olisivat hänen saaneet sisälle, astuivat he katon päälle ja laskivat hänen lävitse katon vuoteinensa juuri Jeesuksen eteen.","Ja kuin ei he löytäneet kansan tähden, kusta puolesta he olisivat hänen saaneet sisälle, astuivat he katon päälle ja laskivat hänen lävitse katon vuoteinensa juuri Jeesuksen eteen."],[5,20,"Ja kuin hän näki heidän uskonsa, sanoi hän sille: ihminen, sinun syntis anteeksi annetaan sinulle.","Ja kuin hän näki heidän uskonsa, sanoi hän sille: ihminen, sinun syntis anteeksi annetaan sinulle."],[5,21,"Ja kirjanoppineet ja Pharisealaiset rupesivat ajattelemaan, sanoen: kuka tämä on, joka pilkkasanoja puhuu? kuka voi synnit antaa anteeksi, paitsi ainoastaan Jumala?","Ja kirjanoppineet ja Pharisealaiset rupesivat ajattelemaan, sanoen: kuka tämä on, joka pilkkasanoja puhuu? kuka voi synnit antaa anteeksi, paitsi ainoastaan Jumala?"],[5,22,"Mutta kuin Jesus tunsi heidän ajatuksensa, vastasi hän ja sanoi heille: mitä te ajattelette sydämessänne?","Mutta kuin Jesus tunsi heidän ajatuksensa, vastasi hän ja sanoi heille: mitä te ajattelette sydämessänne?"],[5,23,"Kumpi on keveämpi? sanoa: sinun syntis anteeksi annetaan sinulle! taikka sanoa: nouse ja käy!","Kumpi on keveämpi? sanoa: sinun syntis anteeksi annetaan sinulle! taikka sanoa: nouse ja käy!"],[5,24,"Vaan että te tietäisitte Ihmisen Pojalla olevan vallan maan päällä synnit anteeksi antaa (sanoi hän halvatulle:) minä sanon sinulle: nouse ja ota vuotees, ja mene kotias!","Vaan että te tietäisitte Ihmisen Pojalla olevan vallan maan päällä synnit anteeksi antaa (sanoi hän halvatulle:) minä sanon sinulle: nouse ja ota vuotees, ja mene kotias!"],[5,25,"Ja hän nousi kohta heidän nähtensä ja korjasi vuotehensa, jossa hän maannut oli, ja meni kotiansa, kunnioittain Jumalaa.","Ja hän nousi kohta heidän nähtensä ja korjasi vuotehensa, jossa hän maannut oli, ja meni kotiansa, kunnioittain Jumalaa."],[5,26,"Ja suuri hämmästys tuli kaikkiin ja kunnioittivat Jumalaa, ja he täytettiin pelvolla, sanoen: me näimme tänäpänä kamalia.","Ja suuri hämmästys tuli kaikkiin ja kunnioittivat Jumalaa, ja he täytettiin pelvolla, sanoen: me näimme tänäpänä kamalia."],[5,27,"Sitte läksi hän ulos ja näki Publikanin nimeltä Levin, istuvan tullihuoneessa, ja sanoi hänelle: seuraa minua!","Sitte läksi hän ulos ja näki Publikanin nimeltä Levin, istuvan tullihuoneessa, ja sanoi hänelle: seuraa minua!"],[5,28,"Ja hän antoi ylön kaikki, nousi ja seurasi häntä.","Ja hän antoi ylön kaikki, nousi ja seurasi häntä."],[5,29,"Ja Levi teki hänelle kotonansa suuren pidon, ja paljo Publikaneja ja muita atrioitsivat heidän kanssansa.","Ja Levi teki hänelle kotonansa suuren pidon, ja paljo Publikaneja ja muita atrioitsivat heidän kanssansa."],[5,30,"Ja heidän kirjanoppineensa ja Pharisealaiset napisivat hänen opetuslapsiansa, sanoen: miksi te Publikanien ja syntisten kanssa syötte ja juotte?","Ja heidän kirjanoppineensa ja Pharisealaiset napisivat hänen opetuslapsiansa, sanoen: miksi te Publikanien ja syntisten kanssa syötte ja juotte?"],[5,31,"Ja Jesus vastaten sanoi heille: ei terveet tarvitse parantajaa, vaan sairaat.","Ja Jesus vastaten sanoi heille: ei terveet tarvitse parantajaa, vaan sairaat."],[5,32,"En ole minä tullut vanhurskaita kutsumaan, vaan syntisiä parannukseen.","En ole minä tullut vanhurskaita kutsumaan, vaan syntisiä parannukseen."],[5,33,"Niin he sanoivat hänelle: miksi Johanneksen opetuslapset usein paastoavat ja rukouksia pitävät, niin myös Pharisealaisten (opetuslapset), mutta sinun syövät ja juovat?","Niin he sanoivat hänelle: miksi Johanneksen opetuslapset usein paastoavat ja rukouksia pitävät, niin myös Pharisealaisten (opetuslapset), mutta sinun syövät ja juovat?"],[5,34,"Mutta hän sanoi heille: ette voi hääjoukkoa niinkauvan paastoomaan vaatia, kuin ylkä on heidän kanssansa.","Mutta hän sanoi heille: ette voi hääjoukkoa niinkauvan paastoomaan vaatia, kuin ylkä on heidän kanssansa."],[5,35,"Mutta päivät tulevat, että ylkä otetaan heiltä pois, silloin pitää heidän paastooman niinä päivinä.","Mutta päivät tulevat, että ylkä otetaan heiltä pois, silloin pitää heidän paastooman niinä päivinä."],[5,36,"Mutta hän sanoi myös heille vertauksen: ei paikkaa kenkään uuden veran tilalla vanhaa vaatetta: muutoin myös se uusi repäisee, ja uusi paikka ei sovi vanhaan.","Mutta hän sanoi myös heille vertauksen: ei paikkaa kenkään uuden veran tilalla vanhaa vaatetta: muutoin myös se uusi repäisee, ja uusi paikka ei sovi vanhaan."],[5,37,"ja ei pane kenkään nuorta viinaa vanhoihin leileihin: muutoin nuori viina rikkoo leilit, ja se vuotaa ulos, ja leilit turmellaan.","ja ei pane kenkään nuorta viinaa vanhoihin leileihin: muutoin nuori viina rikkoo leilit, ja se vuotaa ulos, ja leilit turmellaan."],[5,38,"Mutta nuorta viinaa pitää pantaman uusiin leileihin: niin ne molemmat tallella ovat.","Mutta nuorta viinaa pitää pantaman uusiin leileihin: niin ne molemmat tallella ovat."],[5,39,"Ja ei tahdo kenkään, joka juo vanhaa viinaa, kohta nuorta juoda; sillä hän sanoo: vanha on parempi.","Ja ei tahdo kenkään, joka juo vanhaa viinaa, kohta nuorta juoda; sillä hän sanoo: vanha on parempi."],[6,1,"Ja tapahtui jälkisabbattina, että hän kävi laihon lävitse, ja hänen opetuslapsensa katkoivat tähkäpäitä ja hiersivät käsillänsä, ja söivät.","Ja tapahtui jälkisabbattina, että hän kävi laihon lävitse, ja hänen opetuslapsensa katkoivat tähkäpäitä ja hiersivät käsillänsä, ja söivät."],[6,2,"Niin muutamat Pharisealaiset sanoivat heille: miksi te teette, jota ei sovi sabbatina tehdä?","Niin muutamat Pharisealaiset sanoivat heille: miksi te teette, jota ei sovi sabbatina tehdä?"],[6,3,"Ja Jesus vastaten sanoi heille: ettekö te ole lukeneet, mitä David teki, kuin hän isosi, ja ne, jotka hänen kanssaan olivat?","Ja Jesus vastaten sanoi heille: ettekö te ole lukeneet, mitä David teki, kuin hän isosi, ja ne, jotka hänen kanssaan olivat?"],[6,4,"Kuinka hän meni Jumalan huoneeseen, ja otti näkyleivät, ja söi, ja antoi myös niille, jotka hänen kanssaan olivat; joita ei muiden kuin pappein syödä sopinut.","Kuinka hän meni Jumalan huoneeseen, ja otti näkyleivät, ja söi, ja antoi myös niille, jotka hänen kanssaan olivat; joita ei muiden kuin pappein syödä sopinut."],[6,5,"Ja hän sanoi heille: Ihmisen Poika on myös sabbatin Herra.","Ja hän sanoi heille: Ihmisen Poika on myös sabbatin Herra."],[6,6,"Niin tapahtui myös toisena sabbatina, että hän meni synagogaan sisälle ja opetti; ja siellä oli ihminen, jonka oikea käsi oli kuivettunut.","Niin tapahtui myös toisena sabbatina, että hän meni synagogaan sisälle ja opetti; ja siellä oli ihminen, jonka oikea käsi oli kuivettunut."],[6,7,"Niin kirjanoppineet ja Pharisealaiset vartiotsivat häntä, josko hän sabbatina parantais, että he olisivat löytäneet kanteen häntä vastaan.","Niin kirjanoppineet ja Pharisealaiset vartiotsivat häntä, josko hän sabbatina parantais, että he olisivat löytäneet kanteen häntä vastaan."],[6,8,"Mutta hän tiesi heidän ajatuksensa ja sanoi sille ihmiselle, jolla kuivettunut käsi oli: nouse ja tule edes! Niin hän nousi ja seisoi.","Mutta hän tiesi heidän ajatuksensa ja sanoi sille ihmiselle, jolla kuivettunut käsi oli: nouse ja tule edes! Niin hän nousi ja seisoi."],[6,9,"Niin Jesus sanoi hänelle: minä kysyn teiltä: mitä sabbatina sopii, hyvää tehdä, taikka pahaa tehdä? henkeä vapahtaa eli kadottaa?","Niin Jesus sanoi hänelle: minä kysyn teiltä: mitä sabbatina sopii, hyvää tehdä, taikka pahaa tehdä? henkeä vapahtaa eli kadottaa?"],[6,10,"Ja kuin hän katsahti ympäri heidän kaikkein päällensä, sanoi hän sille ihmiselle: ojenna kätes! ja se teki niin, ja hänen kätensä tuli terveeksi niinkuin toinenkin.","Ja kuin hän katsahti ympäri heidän kaikkein päällensä, sanoi hän sille ihmiselle: ojenna kätes! ja se teki niin, ja hänen kätensä tuli terveeksi niinkuin toinenkin."],[6,11,"Mutta he tulivat tyhmyyttä täyteen ja puhuivat keskenänsä, mitä heidän pitäis Jesukselle tekemän.","Mutta he tulivat tyhmyyttä täyteen ja puhuivat keskenänsä, mitä heidän pitäis Jesukselle tekemän."],[6,12,"Mutta niinä päivinä tapahtui, että hän meni vuorelle rukoilemaan, ja hän oli yli yötä Jumalan tykö rukouksessa.","Mutta niinä päivinä tapahtui, että hän meni vuorelle rukoilemaan, ja hän oli yli yötä Jumalan tykö rukouksessa."],[6,13,"Ja kuin päivä tuli, kutsui hän opetuslapsensa ja valitsi heistä kaksitoistakymmentä, jotka hän myös apostoleiksi nimitti:","Ja kuin päivä tuli, kutsui hän opetuslapsensa ja valitsi heistä kaksitoistakymmentä, jotka hän myös apostoleiksi nimitti:"],[6,14,"Simonin, jonka hän myös Pietariksi kutsui, ja Andreaksen, hänen veljensä, Jakobin ja Johanneksen, Philippuksen ja Bartolomeuksen,","Simonin, jonka hän myös Pietariksi kutsui, ja Andreaksen, hänen veljensä, Jakobin ja Johanneksen, Philippuksen ja Bartolomeuksen,"],[6,15,"Matteuksen ja Toomaan, Jakobin Alphein pojan, ja Simonin, joka kutsutaan Zelotes,","Matteuksen ja Toomaan, Jakobin Alphein pojan, ja Simonin, joka kutsutaan Zelotes,"],[6,16,"Juudaan Jakobin pojan, ja Juudas Iskariotin, joka myös oli pettäjä.","Juudaan Jakobin pojan, ja Juudas Iskariotin, joka myös oli pettäjä."],[6,17,"Ja kuin hän meni alas heidän kanssansa, seisoi hän lakialla paikalla, ja hänen opetuslastensa joukko, ja suuri kansan paljous kaikesta Juudeasta ja Jerusalemista, ja rantalaiset Tyrosta ja Sidonista, jotka olivat tulleet häntä kuulemaan, ja että he parannettaisiin taudeistansa,","Ja kuin hän meni alas heidän kanssansa, seisoi hän lakialla paikalla, ja hänen opetuslastensa joukko, ja suuri kansan paljous kaikesta Juudeasta ja Jerusalemista, ja rantalaiset Tyrosta ja Sidonista, jotka olivat tulleet häntä kuulemaan, ja että he parannettaisiin taudeistansa,"],[6,18,"Ja jotka vaivattiin riettasilta hengiltä; ja he paranivat.","Ja jotka vaivattiin riettasilta hengiltä; ja he paranivat."],[6,19,"Ja kaikki kansa pyysi häneen ruveta; sillä voima läksi hänestä ja paransi kaikki.","Ja kaikki kansa pyysi häneen ruveta; sillä voima läksi hänestä ja paransi kaikki."],[6,20,"Ja hän nosti silmänsä opetuslastensa puoleen, ja sanoi: autuaat te vaivaiset; sillä teidän on Jumalan valtakunta.","Ja hän nosti silmänsä opetuslastensa puoleen, ja sanoi: autuaat te vaivaiset; sillä teidän on Jumalan valtakunta."],[6,21,"Autuaat, jotka nyt isootte; sillä teidät ravitaan. Autuaat, jotka nyt itkette; sillä teidän pitää nauraman.","Autuaat, jotka nyt isootte; sillä teidät ravitaan. Autuaat, jotka nyt itkette; sillä teidän pitää nauraman."],[6,22,"Autuaat olette te, kuin ihmiset vihaavat teitä, ja eroittavat teidät, ja pilkkaavat teitä, ja hylkäävät teidän nimenne niinkuin kelvottoman, Ihmisen Pojan tähden.","Autuaat olette te, kuin ihmiset vihaavat teitä, ja eroittavat teidät, ja pilkkaavat teitä, ja hylkäävät teidän nimenne niinkuin kelvottoman, Ihmisen Pojan tähden."],[6,23,"Iloitkaat sinä päivänä ja riemuitkaat, sillä katso, teidän palkkanne on suuri taivaassa; niin tekivät myös heidän isänsä prophetaille.","Iloitkaat sinä päivänä ja riemuitkaat, sillä katso, teidän palkkanne on suuri taivaassa; niin tekivät myös heidän isänsä prophetaille."],[6,24,"Mutta voi teitä rikkaita! sillä teillä on teidän lohdutuksenne.","Mutta voi teitä rikkaita! sillä teillä on teidän lohdutuksenne."],[6,25,"Voi teitä, jotka ravitut olette! sillä teidän pitää isooman. Voi teitä, jotka nyt nauratte! sillä teidän pitää murehtiman ja itkemän.","Voi teitä, jotka ravitut olette! sillä teidän pitää isooman. Voi teitä, jotka nyt nauratte! sillä teidän pitää murehtiman ja itkemän."],[6,26,"Voi teitä, kuin kaikki ihmiset teitä kiittävät! sillä niin tekivät myös heidän isänsä väärille prophetoille.","Voi teitä, kuin kaikki ihmiset teitä kiittävät! sillä niin tekivät myös heidän isänsä väärille prophetoille."],[6,27,"Mutta minä sanon teille, jotka kuulette: rakastakaa vihollisianne: tehkäät hyvää niille, jotka teitä vihaavat:","Mutta minä sanon teille, jotka kuulette: rakastakaa vihollisianne: tehkäät hyvää niille, jotka teitä vihaavat:"],[6,28,"Siunatkaat niitä, jotka teitä kiroilevat: rukoilkaat niiden edestä, jotka teitä vahingoittavat.","Siunatkaat niitä, jotka teitä kiroilevat: rukoilkaat niiden edestä, jotka teitä vahingoittavat."],[6,29,"Ja joka sinua lyö poskelle, taritse myös hänelle toinen, ja joka sinulta vie kaapun, älä myös häneltä kiellä hametta.","Ja joka sinua lyö poskelle, taritse myös hänelle toinen, ja joka sinulta vie kaapun, älä myös häneltä kiellä hametta."],[6,30,"Vaan anna jokaiselle, joka sinulta anoo, ja siltä, joka sinun omas ottaa, älä jälleen ano.","Vaan anna jokaiselle, joka sinulta anoo, ja siltä, joka sinun omas ottaa, älä jälleen ano."],[6,31,"Ja niinkuin te tahdotte, että ihmisten pitää teille tekemän, niin tehkäät te heillekin.","Ja niinkuin te tahdotte, että ihmisten pitää teille tekemän, niin tehkäät te heillekin."],[6,32,"Ja jos te rakastatte niitä, jotka teitä rakastavat, mikä kiitos teille siitä on? sillä syntisetkin rakastavat niitä, joilta he rakastetaan.","Ja jos te rakastatte niitä, jotka teitä rakastavat, mikä kiitos teille siitä on? sillä syntisetkin rakastavat niitä, joilta he rakastetaan."],[6,33,"Ja jos te teette hyvää hyväntekijöillenne, mikä kiitos teillä siinä on? sillä syntiset sen myös tekevät.","Ja jos te teette hyvää hyväntekijöillenne, mikä kiitos teillä siinä on? sillä syntiset sen myös tekevät."],[6,34,"Ja jos te lainaatte niille, joilta te toivotte jälleen saavanne, mikä kiitos teillä siitä on? sillä syntisetkin lainaavat syntisille, että he tasan jälleen saisivat.","Ja jos te lainaatte niille, joilta te toivotte jälleen saavanne, mikä kiitos teillä siitä on? sillä syntisetkin lainaavat syntisille, että he tasan jälleen saisivat."],[6,35,"Kuitenkin rakastakaat teidän vihollisianne ja tehkäät hyvää, ja lainatkaat, ja älkäät mitään siitä toivoko: niin teidän palkkanne on suuri, ja teidän pitää oleman Ylimmäisen pojat; sillä hän on laupias kiittämättömiä ja pahoja kohtaan.","Kuitenkin rakastakaat teidän vihollisianne ja tehkäät hyvää, ja lainatkaat, ja älkäät mitään siitä toivoko: niin teidän palkkanne on suuri, ja teidän pitää oleman Ylimmäisen pojat; sillä hän on laupias kiittämättömiä ja pahoja kohtaan."],[6,36,"Olkaat sentähden laupiaat, niinkuin teidän Isännekin laupias on.","Olkaat sentähden laupiaat, niinkuin teidän Isännekin laupias on."],[6,37,"Älkäät tuomitko, ettei teitä tuomittaisi: älkäät sadatelko, ettei teitä sadateltaisi: anteeksi antakaat, niin teille anteeksi annetaan.","Älkäät tuomitko, ettei teitä tuomittaisi: älkäät sadatelko, ettei teitä sadateltaisi: anteeksi antakaat, niin teille anteeksi annetaan."],[6,38,"Antakaat, ja teille annetaan: hyvän mitan, likistetyn ja sullotun, ja ylitsevuotavan he antavat teidän helmaanne; sillä juuri sillä mitalla, jolla te mittaatte, pitää teille jälleen mitattaman.","Antakaat, ja teille annetaan: hyvän mitan, likistetyn ja sullotun, ja ylitsevuotavan he antavat teidän helmaanne; sillä juuri sillä mitalla, jolla te mittaatte, pitää teille jälleen mitattaman."],[6,39,"Mutta hän sanoi heille vertauksen: taitaako sokia sokiaa taluttaa? eikö he molemmat hautaan lankee?","Mutta hän sanoi heille vertauksen: taitaako sokia sokiaa taluttaa? eikö he molemmat hautaan lankee?"],[6,40,"Ei ole opetuslapsi ylitse mestarinsa, mutta jokainen on täydellinen, kuin hän on niinkuin hänen mestarinsa.","Ei ole opetuslapsi ylitse mestarinsa, mutta jokainen on täydellinen, kuin hän on niinkuin hänen mestarinsa."],[6,41,"Mutta kuinkas näet raiskan, joka on veljes silmässä, vaan et havaitse malkaa, joka on omassa silmässäs?","Mutta kuinkas näet raiskan, joka on veljes silmässä, vaan et havaitse malkaa, joka on omassa silmässäs?"],[6,42,"Eli kuinkas taidat sanoa veljelles: veljeni, pidä, minä otan raiskan, joka on silmässäs, ja et itse näe malkaa, joka on omassa silmässäs? Sinä ulkokullattu, ota ensin malka omasta silmästäs, ja katso sitte, jos taidat ottaa raiskan, joka on veljes silmässä.","Eli kuinkas taidat sanoa veljelles: veljeni, pidä, minä otan raiskan, joka on silmässäs, ja et itse näe malkaa, joka on omassa silmässäs? Sinä ulkokullattu, ota ensin malka omasta silmästäs, ja katso sitte, jos taidat ottaa raiskan, joka on veljes silmässä."],[6,43,"Sillä ei ole se hyvä puu, joka tekee pahan hedelmän, eikä paha puu, joka tekee hyvän hedelmän.","Sillä ei ole se hyvä puu, joka tekee pahan hedelmän, eikä paha puu, joka tekee hyvän hedelmän."],[6,44,"Sillä jokainen puu tunnetaan hedelmästänsä; sillä ei orjantappuroista koota fikunia, eikä ohdakkeista haeta viinamarjoja.","Sillä jokainen puu tunnetaan hedelmästänsä; sillä ei orjantappuroista koota fikunia, eikä ohdakkeista haeta viinamarjoja."],[6,45,"Hyvä ihminen tuottaa edes sydämensä hyvästä tavarasta hyvää, ja paha ihminen sydämensä pahasta tavarasta tuottaa edes pahaa. Sillä sydämen kyllyydestä hänen suunsa puhuu.","Hyvä ihminen tuottaa edes sydämensä hyvästä tavarasta hyvää, ja paha ihminen sydämensä pahasta tavarasta tuottaa edes pahaa. Sillä sydämen kyllyydestä hänen suunsa puhuu."],[6,46,"Mitä te siis minua kutsutte Herra, Herra! ja ette tee, mitä minä sanon?","Mitä te siis minua kutsutte Herra, Herra! ja ette tee, mitä minä sanon?"],[6,47,"Kuka ikänä tulee minun tyköni, ja kuulee minun sanani, ja tekee ne, sen minä osoitan teille, kenen kaltainen hän on.","Kuka ikänä tulee minun tyköni, ja kuulee minun sanani, ja tekee ne, sen minä osoitan teille, kenen kaltainen hän on."],[6,48,"Hän on sen ihmisen kaltainen, joka huoneensa rakensi, ja kaivoi syvään, ja pani perustuksen kallion päälle. Kuin siis vuo tuli, sysäsi virta sitä huonetta, ja ei voinut häntä liikuttaa; sillä se oli perustettu kallion päälle.","Hän on sen ihmisen kaltainen, joka huoneensa rakensi, ja kaivoi syvään, ja pani perustuksen kallion päälle. Kuin siis vuo tuli, sysäsi virta sitä huonetta, ja ei voinut häntä liikuttaa; sillä se oli perustettu kallion päälle."],[6,49,"Mutta joka kuulee ja ei tee, se on sen ihmisen kaltainen, joka huoneensa rakensi maan päälle ilman perustusta, jota virta sysäsi, ja se kohta kukistui: jonka huoneen lankeemus oli suuri.","Mutta joka kuulee ja ei tee, se on sen ihmisen kaltainen, joka huoneensa rakensi maan päälle ilman perustusta, jota virta sysäsi, ja se kohta kukistui: jonka huoneen lankeemus oli suuri."],[7,1,"Mutta kuin hän kansan kuullen oli päättänyt kaikki sanansa, meni hän Kapernaumiin.","Mutta kuin hän kansan kuullen oli päättänyt kaikki sanansa, meni hän Kapernaumiin."],[7,2,"Ja yhden sadanpäämiehen palvelia sairasti kuolemallansa, josta hän paljon piti.","Ja yhden sadanpäämiehen palvelia sairasti kuolemallansa, josta hän paljon piti."],[7,3,"Kuin hän siis Jesuksesta kuuli, lähetti hän Juudalaisten vanhimmat hänen tykönsä rukoilemaan häntä, että hän tulis ja parantais hänen palveliansa.","Kuin hän siis Jesuksesta kuuli, lähetti hän Juudalaisten vanhimmat hänen tykönsä rukoilemaan häntä, että hän tulis ja parantais hänen palveliansa."],[7,4,"Kuin he tulivat Jesuksen tykö, rukoilivat he häntä hartaasti ja sanoivat: hän on mahdollinen, ettäs hänelle sen teet;","Kuin he tulivat Jesuksen tykö, rukoilivat he häntä hartaasti ja sanoivat: hän on mahdollinen, ettäs hänelle sen teet;"],[7,5,"Sillä hän rakastaa meidän kansaamme ja rakensi meille synagogan.","Sillä hän rakastaa meidän kansaamme ja rakensi meille synagogan."],[7,6,"Niin Jesus meni heidän kanssansa. Ja kuin ei hän silleen ollut kaukana huoneesta, lähetti sadanpäämies ystäviänsä hänen tykönsä, sanoen hänelle: Herra, älä vaivaa sinuas; sillä en ole minä mahdollinen, ettäs minun kattoni alle tulisit.","Niin Jesus meni heidän kanssansa. Ja kuin ei hän silleen ollut kaukana huoneesta, lähetti sadanpäämies ystäviänsä hänen tykönsä, sanoen hänelle: Herra, älä vaivaa sinuas; sillä en ole minä mahdollinen, ettäs minun kattoni alle tulisit."],[7,7,"Sentähden en minä myös itsiäni lukenut mahdolliseksi tuleman sinun tykös; mutta sano sanalla, niin minun palveliani paranee.","Sentähden en minä myös itsiäni lukenut mahdolliseksi tuleman sinun tykös; mutta sano sanalla, niin minun palveliani paranee."],[7,8,"Sillä minä olen myös ihminen vallan alle asetettu, ja minun allani on sotamiehiä, ja sanon tälle: mene! niin hän menee, ja toiselle: tule! ja hän tulee, ja minun palvelialleni: tee se! ja hän tekee.","Sillä minä olen myös ihminen vallan alle asetettu, ja minun allani on sotamiehiä, ja sanon tälle: mene! niin hän menee, ja toiselle: tule! ja hän tulee, ja minun palvelialleni: tee se! ja hän tekee."],[7,9,"Mutta kuin Jesus sen kuuli, ihmetteli hän häntä, kääntyi ja sanoi kansalle, joka häntä seurasi: minä sanon teille: en ole minä Israelissa senkaltaista uskoa löytänyt.","Mutta kuin Jesus sen kuuli, ihmetteli hän häntä, kääntyi ja sanoi kansalle, joka häntä seurasi: minä sanon teille: en ole minä Israelissa senkaltaista uskoa löytänyt."],[7,10,"Ja kuin ne, jotka lähetetyt olivat, kotia palasivat, löysivät he palvelian terveenä, joka sairastanut oli.","Ja kuin ne, jotka lähetetyt olivat, kotia palasivat, löysivät he palvelian terveenä, joka sairastanut oli."],[7,11,"Ja tapahtui sen jälkeen, että hän meni kaupunkiin, joka Nain kutsutaan, ja hänen kanssansa meni monta hänen opetuslastansa ja paljo väkeä.","Ja tapahtui sen jälkeen, että hän meni kaupunkiin, joka Nain kutsutaan, ja hänen kanssansa meni monta hänen opetuslastansa ja paljo väkeä."],[7,12,"Mutta kuin hän kaupungin porttia lähestyi, katso, kuollut kannettiin ulos, joka oli äitinsä ainoa poika, ja se oli leski. Ja paljo kaupungin kansasta kävi hänen kanssansa.","Mutta kuin hän kaupungin porttia lähestyi, katso, kuollut kannettiin ulos, joka oli äitinsä ainoa poika, ja se oli leski. Ja paljo kaupungin kansasta kävi hänen kanssansa."],[7,13,"Kuin Herra hänen näki, armahti hän hänen päällensä ja sanoi hänelle: älä itke!","Kuin Herra hänen näki, armahti hän hänen päällensä ja sanoi hänelle: älä itke!"],[7,14,"Ja meni ja rupesi paariin (ja kantajat seisahtivat,) ja hän sanoi: nuorukainen, minä sanon sinulle: nouse ylös!","Ja meni ja rupesi paariin (ja kantajat seisahtivat,) ja hän sanoi: nuorukainen, minä sanon sinulle: nouse ylös!"],[7,15,"Ja kuollut nousi istualle ja rupesi puhumaan. Ja hän antoi sen äidillensä.","Ja kuollut nousi istualle ja rupesi puhumaan. Ja hän antoi sen äidillensä."],[7,16,"Ja pelko tuli kaikille, ja kunnioittivat Jumalaa, sanoen: suuri propheta on noussut meidän sekaamme, ja Jumala on kansaansa etsinyt.","Ja pelko tuli kaikille, ja kunnioittivat Jumalaa, sanoen: suuri propheta on noussut meidän sekaamme, ja Jumala on kansaansa etsinyt."],[7,17,"Ja tämä sanoma kuului hänestä kaikkeen Juudeaan ja kaiken sen lähimaakunnan ympäri.","Ja tämä sanoma kuului hänestä kaikkeen Juudeaan ja kaiken sen lähimaakunnan ympäri."],[7,18,"Ja Johannekselle ilmoittivat hänen opetuslapsensa näistä kaikista. Ja Johannes kutsui tykönsä kaksi opetuslastansa,","Ja Johannekselle ilmoittivat hänen opetuslapsensa näistä kaikista. Ja Johannes kutsui tykönsä kaksi opetuslastansa,"],[7,19,"Ja lähetti Jesuksen tykö, sanoen: oletko se tuleva, eli pitääkö meidän toista odottaman?","Ja lähetti Jesuksen tykö, sanoen: oletko se tuleva, eli pitääkö meidän toista odottaman?"],[7,20,"Kuin nämät miehet tulivat hänen tykönsä, sanoivat he: Johannes Kastaja lähetti meidät sinun tykös, sanoen: oletkos sinä se tuleva, eli pitääkö meidän toista odottaman?","Kuin nämät miehet tulivat hänen tykönsä, sanoivat he: Johannes Kastaja lähetti meidät sinun tykös, sanoen: oletkos sinä se tuleva, eli pitääkö meidän toista odottaman?"],[7,21,"Sillä hetkellä paransi hän monta taudeista ja vitsauksista ja pahoista hengistä, ja antoi monelle sokialle näön.","Sillä hetkellä paransi hän monta taudeista ja vitsauksista ja pahoista hengistä, ja antoi monelle sokialle näön."],[7,22,"Ja Jesus vastasi ja sanoi heille: menkäät ja sanokaat jälleen Johannekselle, mitä te nähneet ja kuulleet olette: sokiat saavat näkönsä, ontuvat käyvät, spitaliset puhdistetaan, kuurot kuulevat, kuolleet herätetään, köyhille saarnataan evankeliumi,","Ja Jesus vastasi ja sanoi heille: menkäät ja sanokaat jälleen Johannekselle, mitä te nähneet ja kuulleet olette: sokiat saavat näkönsä, ontuvat käyvät, spitaliset puhdistetaan, kuurot kuulevat, kuolleet herätetään, köyhille saarnataan evankeliumi,"],[7,23,"Ja autuas on se, joka ei pahene minusta.","Ja autuas on se, joka ei pahene minusta."],[7,24,"Ja kuin Johanneksen sanansaattajat menivät pois, rupes hän sanomaan Johanneksesta kansalle: mitä te läksitte korpeen katsomaan? ruokoako, joka tuulelta häälytetään?","Ja kuin Johanneksen sanansaattajat menivät pois, rupes hän sanomaan Johanneksesta kansalle: mitä te läksitte korpeen katsomaan? ruokoako, joka tuulelta häälytetään?"],[7,25,"Eli mitä te läksitte katsomaan? ihmistäkö, pehmeisiin vaatteisiin puettua? Katso, ne jotka koreissa vaatteissa ovat ja herkullisesti elävät, ovat kuninkaallisissa kartanoissa.","Eli mitä te läksitte katsomaan? ihmistäkö, pehmeisiin vaatteisiin puettua? Katso, ne jotka koreissa vaatteissa ovat ja herkullisesti elävät, ovat kuninkaallisissa kartanoissa."],[7,26,"Taikka mitä te menitte katsomaan? prophetaako? minä sanon teille: ja enempi kuin propheta.","Taikka mitä te menitte katsomaan? prophetaako? minä sanon teille: ja enempi kuin propheta."],[7,27,"Tämä on se, josta kirjoitettu on: katso, minä lähetän minun enkelini sinun kasvois eteen, valmistamaan sinun tietäs sinun etees.","Tämä on se, josta kirjoitettu on: katso, minä lähetän minun enkelini sinun kasvois eteen, valmistamaan sinun tietäs sinun etees."],[7,28,"Sillä minä sanon teille: niiden seassa, jotka vaimoista syntyneet ovat, ei ole yhtään suurempaa prophetaa kuin Johannes Kastaja: kuitenkin se, joka vähempi on Jumalan valtakunnassa, on suurempi häntä.","Sillä minä sanon teille: niiden seassa, jotka vaimoista syntyneet ovat, ei ole yhtään suurempaa prophetaa kuin Johannes Kastaja: kuitenkin se, joka vähempi on Jumalan valtakunnassa, on suurempi häntä."],[7,29,"Ja kaikki kansa, joka hänen kuuli, ja Publikanit antoivat Jumalalle oikeuden ja kastettiin Johanneksen kasteella.","Ja kaikki kansa, joka hänen kuuli, ja Publikanit antoivat Jumalalle oikeuden ja kastettiin Johanneksen kasteella."],[7,30,"Mutta Pharisealaiset ja lainoppineet katsoivat ylön Jumalan neuvon itseänsä kohtaan, ja ei heitä kastettu häneltä.","Mutta Pharisealaiset ja lainoppineet katsoivat ylön Jumalan neuvon itseänsä kohtaan, ja ei heitä kastettu häneltä."],[7,31,"Niin Herra sanoi: keneen siis minä tämän sukukunnan ihmiset vertaan? Ja kenenkä kaltaiset he ovat?","Niin Herra sanoi: keneen siis minä tämän sukukunnan ihmiset vertaan? Ja kenenkä kaltaiset he ovat?"],[7,32,"Ne ovat niiden lasten kaltaiset, jotka turulla istuvat ja huutavat toinen toisellensa ja sanovat: me olemme huilua soittaneet teidän edessänne, ja ette hypänneet: me olemme teille veisanneet murhevirsiä, ja ette itkeneet.","Ne ovat niiden lasten kaltaiset, jotka turulla istuvat ja huutavat toinen toisellensa ja sanovat: me olemme huilua soittaneet teidän edessänne, ja ette hypänneet: me olemme teille veisanneet murhevirsiä, ja ette itkeneet."],[7,33,"Sillä Johannes Kastaja tuli, ja ei syönyt leipää eikä juonut viinaa, ja te sanotte: hänellä on perkele.","Sillä Johannes Kastaja tuli, ja ei syönyt leipää eikä juonut viinaa, ja te sanotte: hänellä on perkele."],[7,34,"Ihmisen Poika on tullut, syö ja juo, ja te sanotte: katso ihmistä, syömäriä ja viinan juomaria, Publikanien ja syntisten ystävää:","Ihmisen Poika on tullut, syö ja juo, ja te sanotte: katso ihmistä, syömäriä ja viinan juomaria, Publikanien ja syntisten ystävää:"],[7,35,"Ja viisaus on vanhurskautettu kaikilta hänen lapsiltansa.","Ja viisaus on vanhurskautettu kaikilta hänen lapsiltansa."],[7,36,"Niin yksi Pharisealaisista rukoili häntä ruualle kanssansa. Ja hän meni Phariseuksen huoneeseen ja aterioitsi.","Niin yksi Pharisealaisista rukoili häntä ruualle kanssansa. Ja hän meni Phariseuksen huoneeseen ja aterioitsi."],[7,37,"Ja katso, yksi vaimo oli kaupungissa, joka oli syntinen, ja kuin hän sai kuulla, että hän aterioitsi Pharisealaisen huoneessa, toi hän lasin kallista voidetta.","Ja katso, yksi vaimo oli kaupungissa, joka oli syntinen, ja kuin hän sai kuulla, että hän aterioitsi Pharisealaisen huoneessa, toi hän lasin kallista voidetta."],[7,38,"Ja seisoi takana hänen jalkainsa juuressa itkien, ja rupesi kyyneleillänsä kastamaan hänen jalkojansa, ja niitä päänsä hiuksilla kuivasi, ja suuta antoi hänen jalkainsa, ja voiteli ne voiteella.","Ja seisoi takana hänen jalkainsa juuressa itkien, ja rupesi kyyneleillänsä kastamaan hänen jalkojansa, ja niitä päänsä hiuksilla kuivasi, ja suuta antoi hänen jalkainsa, ja voiteli ne voiteella."],[7,39,"Mutta kuin Pharisealainen sen näki, joka hänen kutsunut oli, sanoi hän itsellensä: jos tämä olis propheta, niin hän tietäis, mikä ja millainen tämä vaimo on, joka häneen rupee, että hän on syntinen.","Mutta kuin Pharisealainen sen näki, joka hänen kutsunut oli, sanoi hän itsellensä: jos tämä olis propheta, niin hän tietäis, mikä ja millainen tämä vaimo on, joka häneen rupee, että hän on syntinen."],[7,40,"Ja Jesus vastaten sanoi hänelle: Simon, minulla on jotakin sinulle sanomista. Hän sanoi: Mestari, sanos.","Ja Jesus vastaten sanoi hänelle: Simon, minulla on jotakin sinulle sanomista. Hän sanoi: Mestari, sanos."],[7,41,"Kaksi velkamiestä oli yhdellä lainaajalla: yksi oli velkaa viisisataa penninkiä ja toinen viisikymmentä.","Kaksi velkamiestä oli yhdellä lainaajalla: yksi oli velkaa viisisataa penninkiä ja toinen viisikymmentä."],[7,42,"Koska ei heillä ollut varaa maksaa, antoi hän molempain anteeksi. Sano siis, kumpi näistä häntä enemmän rakastaman pitää?","Koska ei heillä ollut varaa maksaa, antoi hän molempain anteeksi. Sano siis, kumpi näistä häntä enemmän rakastaman pitää?"],[7,43,"Simon vastaten sanoi: minä luulen, että se, jolle hän enemmän anteeksi antoi; hän sanoi: oikein sinä tuomitsit.","Simon vastaten sanoi: minä luulen, että se, jolle hän enemmän anteeksi antoi; hän sanoi: oikein sinä tuomitsit."],[7,44,"Ja hän käänsi itsensä vaimoa päin, ja sanoi Simonille: näetkös tämän vaimon? minä tulin sinun huoneeses, etkä sinä antanut vettä minun jaloilleni; mutta tämä kyynelillä kasti minun jalkani ja ne hiuksillansa kuivasi.","Ja hän käänsi itsensä vaimoa päin, ja sanoi Simonille: näetkös tämän vaimon? minä tulin sinun huoneeses, etkä sinä antanut vettä minun jaloilleni; mutta tämä kyynelillä kasti minun jalkani ja ne hiuksillansa kuivasi."],[7,45,"Et sinä minun suuta antanut, mutta tämä, sittenkuin hän tähän tuli, ei ole lakannut minun jalkaini suuta antamasta.","Et sinä minun suuta antanut, mutta tämä, sittenkuin hän tähän tuli, ei ole lakannut minun jalkaini suuta antamasta."],[7,46,"Et sinä minun päätäni öljyllä voidellut; mutta tämä voiteella minun jalkani voiteli.","Et sinä minun päätäni öljyllä voidellut; mutta tämä voiteella minun jalkani voiteli."],[7,47,"Minä sanon sinulle: sentähden että hänelle paljo syntiä anteeksi annettiin, niin hän paljon rakasti; mutta jolle vähempi anteeksi annetaan, se vähemmän rakastaa.","Minä sanon sinulle: sentähden että hänelle paljo syntiä anteeksi annettiin, niin hän paljon rakasti; mutta jolle vähempi anteeksi annetaan, se vähemmän rakastaa."],[7,48,"Niin hän sanoi hänelle: sinun syntis ovat anteeksi annetut.","Niin hän sanoi hänelle: sinun syntis ovat anteeksi annetut."],[7,49,"Niin rupesivat ne, jotka myös aterioitsivat, sanomaan keskenänsä: kuka tämä on, joka synnitkin anteeksi antaa?","Niin rupesivat ne, jotka myös aterioitsivat, sanomaan keskenänsä: kuka tämä on, joka synnitkin anteeksi antaa?"],[7,50,"Niin hän sanoi vaimolle: sinun uskos on sinun vapaaksi tehnyt: mene rauhaan.","Niin hän sanoi vaimolle: sinun uskos on sinun vapaaksi tehnyt: mene rauhaan."],[8,1,"Ja sitte tapahtui, että hän vaelsi lävitse kaupungeita ja kyliä saarnaten ja ilmoittain evankeliumia Jumalan valtakunnasta, ja ne kaksitoistakymmentä hänen kanssansa,","Ja sitte tapahtui, että hän vaelsi lävitse kaupungeita ja kyliä saarnaten ja ilmoittain evankeliumia Jumalan valtakunnasta, ja ne kaksitoistakymmentä hänen kanssansa,"],[8,2,"Ja muutamat vaimot, jotka olivat parannetut pahoista hengistä ja taudeista, nimittäin: Maria, joka kutsuttiin Magdalena, josta seitsemän perkelettä oli lähtenyt ulos,","Ja muutamat vaimot, jotka olivat parannetut pahoista hengistä ja taudeista, nimittäin: Maria, joka kutsuttiin Magdalena, josta seitsemän perkelettä oli lähtenyt ulos,"],[8,3,"Ja Johanna, Kusaan, Herodeksen voudin emäntä, ja Susanna ja monta muuta, jotka tavarastansa häntä palvelivat.","Ja Johanna, Kusaan, Herodeksen voudin emäntä, ja Susanna ja monta muuta, jotka tavarastansa häntä palvelivat."],[8,4,"Mutta kuin paljo kansaa kokoontui, ja he riensivät jokaisesta kaupungista hänen tykönsä, sanoi hän vertauksella:","Mutta kuin paljo kansaa kokoontui, ja he riensivät jokaisesta kaupungista hänen tykönsä, sanoi hän vertauksella:"],[8,5,"Kylväjä meni ulos siementänsä kylvämään; ja kuin hän kylvi, lankesi muutama tien oheen, ja se tallattiin, ja taivaan linnut söivät sen.","Kylväjä meni ulos siementänsä kylvämään; ja kuin hän kylvi, lankesi muutama tien oheen, ja se tallattiin, ja taivaan linnut söivät sen."],[8,6,"Ja muutama lankesi kivistöön, ja kuin se tuli ylös, kuivettui se, ettei ollut märkyyttä.","Ja muutama lankesi kivistöön, ja kuin se tuli ylös, kuivettui se, ettei ollut märkyyttä."],[8,7,"Ja muutama lankesi orjantappuroihin, ja orjantappurat ynnä kävivät ylös ja tukahduttivat sen.","Ja muutama lankesi orjantappuroihin, ja orjantappurat ynnä kävivät ylös ja tukahduttivat sen."],[8,8,"Ja muutama lankesi hyvään maahan, ja kuin se kävi ylös, teki se satakertaisen hedelmän. Kuin hän tämän sanoi, huusi hän: jolla on korvat kuulla, se kuulkaan.","Ja muutama lankesi hyvään maahan, ja kuin se kävi ylös, teki se satakertaisen hedelmän. Kuin hän tämän sanoi, huusi hän: jolla on korvat kuulla, se kuulkaan."],[8,9,"Niin hänen opetuslapsensa kysyivät häneltä, sanoen: mikä olis tämä vertaus?","Niin hänen opetuslapsensa kysyivät häneltä, sanoen: mikä olis tämä vertaus?"],[8,10,"Niin hän sanoi: teille on annettu tuta Jumalan valtakunnan salaudet, mutta muille vertausten kautta, ettei heidän sitä pitäis näkemän, vaikka näkisivät, eikä ymmärtämän, vaikka he kuulisivat.","Niin hän sanoi: teille on annettu tuta Jumalan valtakunnan salaudet, mutta muille vertausten kautta, ettei heidän sitä pitäis näkemän, vaikka näkisivät, eikä ymmärtämän, vaikka he kuulisivat."],[8,11,"Mutta tämä on vertaus: siemen on Jumalan sana.","Mutta tämä on vertaus: siemen on Jumalan sana."],[8,12,"Mutta jotka tien oheen, ovat ne, jotka kuulevat; sitte tulee perkele ja ottaa sanan heidän sydämestänsä, ettei he uskoisi ja vapaaksi tulisi.","Mutta jotka tien oheen, ovat ne, jotka kuulevat; sitte tulee perkele ja ottaa sanan heidän sydämestänsä, ettei he uskoisi ja vapaaksi tulisi."],[8,13,"Mutta jotka kivistöön, ovat ne, kuin he kuulevat, ottavat he sanan ilolla vastaan; ja ei heillä ole juurta, hetkeksi he uskovat, ja kiusauksen ajalla lankeevat pois.","Mutta jotka kivistöön, ovat ne, kuin he kuulevat, ottavat he sanan ilolla vastaan; ja ei heillä ole juurta, hetkeksi he uskovat, ja kiusauksen ajalla lankeevat pois."],[8,14,"Mutta se mikä orjantappuroihin lankesi, ovat ne, jotka kuulevat, ja menevät pois, ja tukahutetaan surusta, rikkaudesta ja elämän hekumasta, eikä kanna hedelmää.","Mutta se mikä orjantappuroihin lankesi, ovat ne, jotka kuulevat, ja menevät pois, ja tukahutetaan surusta, rikkaudesta ja elämän hekumasta, eikä kanna hedelmää."],[8,15,"Mutta jotka hyvään maahan, ovat ne, jotka sanan kuulevat ja kätkevät hyvällä ja toimellisella sydämellä, ja saattavat hedelmän kärsivällisyydessä.","Mutta jotka hyvään maahan, ovat ne, jotka sanan kuulevat ja kätkevät hyvällä ja toimellisella sydämellä, ja saattavat hedelmän kärsivällisyydessä."],[8,16,"Niin ei kenkään, joka kynttilän sytyttää, peitä sitä astialla eli pane pöydän alle; mutta panee sen kynttilänjalkaan, että sisälle tulevaiset näkisivät valkeuden.","Niin ei kenkään, joka kynttilän sytyttää, peitä sitä astialla eli pane pöydän alle; mutta panee sen kynttilänjalkaan, että sisälle tulevaiset näkisivät valkeuden."],[8,17,"Sillä ei ole mitään salattu, joka ei ilmi tule, eikä peitetty, joka ei tiettäväksi ja julki tule.","Sillä ei ole mitään salattu, joka ei ilmi tule, eikä peitetty, joka ei tiettäväksi ja julki tule."],[8,18,"Katsokaat siis, kuinka te kuulette; sillä jolla on, hänelle pitää annettaman: jolla taas ei ole, sekin kuin hänellä näkyy olevan, otetaan häneltä pois.","Katsokaat siis, kuinka te kuulette; sillä jolla on, hänelle pitää annettaman: jolla taas ei ole, sekin kuin hänellä näkyy olevan, otetaan häneltä pois."],[8,19,"Niin tulivat hänen äitinsä ja veljensä hänen tykönsä, eikä saaneet häntä puhutella kansalta.","Niin tulivat hänen äitinsä ja veljensä hänen tykönsä, eikä saaneet häntä puhutella kansalta."],[8,20,"Ja se ilmoitettiin hänelle, sanoen: sinun äitis ja veljes seisovat ulkona ja tahtovat sinua nähdä.","Ja se ilmoitettiin hänelle, sanoen: sinun äitis ja veljes seisovat ulkona ja tahtovat sinua nähdä."],[8,21,"Niin hän vastasi ja sanoi heille: minun äitini ja veljeni ovat ne, jotka Jumalan sanan kuulevat ja tekevät sen.","Niin hän vastasi ja sanoi heille: minun äitini ja veljeni ovat ne, jotka Jumalan sanan kuulevat ja tekevät sen."],[8,22,"Ja yhtenä päivänä tapahtui, että hän haahteen astui ja hänen opetuslapsensa, ja sanoi heille: menkäämme ylitse toiselle rannalle, ja he menivät.","Ja yhtenä päivänä tapahtui, että hän haahteen astui ja hänen opetuslapsensa, ja sanoi heille: menkäämme ylitse toiselle rannalle, ja he menivät."],[8,23,"Mutta kuin he purjehtivat, niin hän nukkui, ja tuulispää nosti aallon meressä; ja he laineilta täytettiin, ja olivat suuressa hädässä.","Mutta kuin he purjehtivat, niin hän nukkui, ja tuulispää nosti aallon meressä; ja he laineilta täytettiin, ja olivat suuressa hädässä."],[8,24,"Niin he menivät ja herättivät häntä sanoen: Mestari, Mestari! me hukumme. Niin hän nousi ylös, nuhteli tuulta ja veden aaltoa; ja ne lakkasivat, ja tuli tyveneksi.","Niin he menivät ja herättivät häntä sanoen: Mestari, Mestari! me hukumme. Niin hän nousi ylös, nuhteli tuulta ja veden aaltoa; ja ne lakkasivat, ja tuli tyveneksi."],[8,25,"Niin hän sanoi heille: kussa teidän uskonne on? Mutta he peljästyivät ja ihmettelivät, sanoen keskenänsä: kuka siis tämä on? sillä hän käskee myös tuulta ja vettä, ja nekin ovat hänelle kuuliaiset.","Niin hän sanoi heille: kussa teidän uskonne on? Mutta he peljästyivät ja ihmettelivät, sanoen keskenänsä: kuka siis tämä on? sillä hän käskee myös tuulta ja vettä, ja nekin ovat hänelle kuuliaiset."],[8,26,"Ja he purjehtivat Gadaralaisten maan puoleen, ja joka on Galilean kohdalla.","Ja he purjehtivat Gadaralaisten maan puoleen, ja joka on Galilean kohdalla."],[8,27,"Ja kuin hän maalle meni, kohtasi hänen kaupungista mies, jolla olivat perkeleet jo kauvan aikaa olleet, ja joka ei pukenut vaatteita yllensä, eikä ollut huoneessa, vaan haudoissa.","Ja kuin hän maalle meni, kohtasi hänen kaupungista mies, jolla olivat perkeleet jo kauvan aikaa olleet, ja joka ei pukenut vaatteita yllensä, eikä ollut huoneessa, vaan haudoissa."],[8,28,"Mutta kuin hän näki Jesuksen, huusi hän ja lankesi hänen eteensä maahan, ja sanoi suurella äänellä: mitä minun on sinun kanssas, Jesus, ylimmäisen Jumalan Poika? Minä rukoilen sinua, älä minua vaivaa.","Mutta kuin hän näki Jesuksen, huusi hän ja lankesi hänen eteensä maahan, ja sanoi suurella äänellä: mitä minun on sinun kanssas, Jesus, ylimmäisen Jumalan Poika? Minä rukoilen sinua, älä minua vaivaa."],[8,29,"Sillä hän oli käskenyt riettaisen hengen ihmisestä mennä ulos, joka kauvan aikaa oli häntä vaivannut: ja hän oli kahleilla sidottu, ja jalkaraudoissa pidetty, ja rikkoi siteet, ja vietiin perkeleeltä korpeen.","Sillä hän oli käskenyt riettaisen hengen ihmisestä mennä ulos, joka kauvan aikaa oli häntä vaivannut: ja hän oli kahleilla sidottu, ja jalkaraudoissa pidetty, ja rikkoi siteet, ja vietiin perkeleeltä korpeen."],[8,30,"Mutta Jesus kysyi häneltä ja sanoi: mikä sinun nimes on? hän sanoi: legio; sillä monta perkelettä oli häneen mennyt sisälle.","Mutta Jesus kysyi häneltä ja sanoi: mikä sinun nimes on? hän sanoi: legio; sillä monta perkelettä oli häneen mennyt sisälle."],[8,31,"Ja he rukoilivat häntä, ettei hän käskisi heitä syvyyteen mennä.","Ja he rukoilivat häntä, ettei hän käskisi heitä syvyyteen mennä."],[8,32,"Niin siellä oli suuri lauma sikoja syömässä vuorella. Ja he rukoilivat häntä, että hän sallis heidän niihin mennä. Ja hän salli heidät.","Niin siellä oli suuri lauma sikoja syömässä vuorella. Ja he rukoilivat häntä, että hän sallis heidän niihin mennä. Ja hän salli heidät."],[8,33,"Niin perkeleet läksivät ulos ihmisestä ja menivät sikoihin, ja lauma syöksi itsensä äkisti jyrkältä mereen ja läkähtyi.","Niin perkeleet läksivät ulos ihmisestä ja menivät sikoihin, ja lauma syöksi itsensä äkisti jyrkältä mereen ja läkähtyi."],[8,34,"Mutta kuin paimenet näkivät, mitä tapahtui, pakenivat he, menivät pois ja ilmoittivat sen kaupungissa ja kylissä.","Mutta kuin paimenet näkivät, mitä tapahtui, pakenivat he, menivät pois ja ilmoittivat sen kaupungissa ja kylissä."],[8,35,"Niin he menivät ulos katsomaan sitä, mikä tapahtunut oli, ja tulivat Jesuksen tykö, ja löysivät sen ihmisen, josta perkeleet lähteneet olivat, istuvan vaatetettuna ja taidossansa Jesuksen jalkain juuressa; ja he pelkäsivät.","Niin he menivät ulos katsomaan sitä, mikä tapahtunut oli, ja tulivat Jesuksen tykö, ja löysivät sen ihmisen, josta perkeleet lähteneet olivat, istuvan vaatetettuna ja taidossansa Jesuksen jalkain juuressa; ja he pelkäsivät."],[8,36,"Mutta myös ne, jotka sen nähneet olivat, ilmoittivat heille, kuinka se perkeleeltä riivattu oli terveeksi tullut.","Mutta myös ne, jotka sen nähneet olivat, ilmoittivat heille, kuinka se perkeleeltä riivattu oli terveeksi tullut."],[8,37,"Ja kaikki Gadaralaiset lähimaakunnan joukko rukoili häntä menemään pois heidän tyköänsä; sillä heidän päällensä oli tullut suuri pelko. Niin hän meni haahteen ja tuli jälleen takaisin.","Ja kaikki Gadaralaiset lähimaakunnan joukko rukoili häntä menemään pois heidän tyköänsä; sillä heidän päällensä oli tullut suuri pelko. Niin hän meni haahteen ja tuli jälleen takaisin."],[8,38,"Mutta mies, josta perkeleet olivat lähteneet ulos, rukoili häntä, että hän sais olla hänen kanssansa. Mutta Jesus laski hänen pois, sanoen:","Mutta mies, josta perkeleet olivat lähteneet ulos, rukoili häntä, että hän sais olla hänen kanssansa. Mutta Jesus laski hänen pois, sanoen:"],[8,39,"Palaja kotias ja ilmoita, kuinka suuret työt Jumala sinulle teki. Ja hän meni pois ja saarnasi ympäri kaiken kaupungin, kuinka suuret työt Jesus hänelle teki.","Palaja kotias ja ilmoita, kuinka suuret työt Jumala sinulle teki. Ja hän meni pois ja saarnasi ympäri kaiken kaupungin, kuinka suuret työt Jesus hänelle teki."],[8,40,"Ja tapahtui, kuin Jesus palasi, otti kansa hänen vastaan; sillä kaikki odottivat häntä.","Ja tapahtui, kuin Jesus palasi, otti kansa hänen vastaan; sillä kaikki odottivat häntä."],[8,41,"Ja katso, mies tuli, jonka nimi oli Jairus, ja se oli synagogan päämies, ja lankesi Jesuksen jalkain juureen ja rukoili häntä tulemaan huoneesensa.","Ja katso, mies tuli, jonka nimi oli Jairus, ja se oli synagogan päämies, ja lankesi Jesuksen jalkain juureen ja rukoili häntä tulemaan huoneesensa."],[8,42,"Sillä hänellä oli ainoa tytär, lähes kahdentoistakymmenen vuotinen, ja se kuoli. Mutta hänen mennessänsä ahdisti kansa häntä.","Sillä hänellä oli ainoa tytär, lähes kahdentoistakymmenen vuotinen, ja se kuoli. Mutta hänen mennessänsä ahdisti kansa häntä."],[8,43,"Ja yksi vaimo, joka oli punaista tautia kaksitoistakymmentä vuotta sairastanut, ja oli kaiken saatunsa parantajille kuluttanut, ja ei voitu keltään parannettaa;","Ja yksi vaimo, joka oli punaista tautia kaksitoistakymmentä vuotta sairastanut, ja oli kaiken saatunsa parantajille kuluttanut, ja ei voitu keltään parannettaa;"],[8,44,"Mutta kuin hän kävi takana ja rupesi hänen vaatteensa palteesen, niin kohta hänen verensä juoksu asettui.","Mutta kuin hän kävi takana ja rupesi hänen vaatteensa palteesen, niin kohta hänen verensä juoksu asettui."],[8,45,"Ja Jesus sanoi: kuka on se, joka minuun rupesi? Mutta kuin he kaikki kielsivät, sanoi Pietari ja ne, jotka hänen kanssansa olivat: Mestari, kansa ahdistaa ja tunkee sinua, ja sinä sanot: kuka minuun rupesi?","Ja Jesus sanoi: kuka on se, joka minuun rupesi? Mutta kuin he kaikki kielsivät, sanoi Pietari ja ne, jotka hänen kanssansa olivat: Mestari, kansa ahdistaa ja tunkee sinua, ja sinä sanot: kuka minuun rupesi?"],[8,46,"Mutta Jesus sanoi: joku minuun rupesi, sillä minä tunsin voiman minusta lähteneen ulos.","Mutta Jesus sanoi: joku minuun rupesi, sillä minä tunsin voiman minusta lähteneen ulos."],[8,47,"Mutta kuin vaimo näki, ettei se salaa ollut, tuli hän vapisten, ja maahan lankesi hänen eteensä, ja julisti kaikelle kansalle, minkä syyn tähden hän oli häneen ruvennut, ja kuinka hän niin äkisti terveeksi tuli.","Mutta kuin vaimo näki, ettei se salaa ollut, tuli hän vapisten, ja maahan lankesi hänen eteensä, ja julisti kaikelle kansalle, minkä syyn tähden hän oli häneen ruvennut, ja kuinka hän niin äkisti terveeksi tuli."],[8,48,"Mutta hän sanoi hänelle: ole hyvässä turvassa, tyttäreni, sinun uskos on sinua auttanut: mene rauhaan!","Mutta hän sanoi hänelle: ole hyvässä turvassa, tyttäreni, sinun uskos on sinua auttanut: mene rauhaan!"],[8,49,"Kuin hän vielä puhui, tuli yksi synagogan päämiehiltä, sanoen hänelle: sinun tyttäres on kuollut: älä Mestaria vaivaa.","Kuin hän vielä puhui, tuli yksi synagogan päämiehiltä, sanoen hänelle: sinun tyttäres on kuollut: älä Mestaria vaivaa."],[8,50,"Vaan kuin Jesus sen kuuli, vastasi hän häntä, sanoen: älä pelkää: usko ainoastaan, niin hän paranee.","Vaan kuin Jesus sen kuuli, vastasi hän häntä, sanoen: älä pelkää: usko ainoastaan, niin hän paranee."],[8,51,"Mutta kuin hän huoneesen tuli sisälle; niin ei hän sallinut ketään tulla sisälle, vaan Pietarin ja Jakobin ja Johanneksen, ja sen lapsen isän ja äidin.","Mutta kuin hän huoneesen tuli sisälle; niin ei hän sallinut ketään tulla sisälle, vaan Pietarin ja Jakobin ja Johanneksen, ja sen lapsen isän ja äidin."],[8,52,"Ja he kaikki itkivät ja parkuivat häntä. Vaan hän sanoi: älkäät itkekö: ei hän ole kuollut, vaan makaa.","Ja he kaikki itkivät ja parkuivat häntä. Vaan hän sanoi: älkäät itkekö: ei hän ole kuollut, vaan makaa."],[8,53,"Ja he nauroivat häntä, tietäen, että se kuollut oli.","Ja he nauroivat häntä, tietäen, että se kuollut oli."],[8,54,"Niin hän ajoi kaikki ulos, rupesi hänen käteensä ja huusi, sanoen: piikainen, nouse ylös!","Niin hän ajoi kaikki ulos, rupesi hänen käteensä ja huusi, sanoen: piikainen, nouse ylös!"],[8,55,"Ja hänen henkensä palasi, ja hän kohta nousi ylös. Ja käski hänelle antaa ruokaa.","Ja hänen henkensä palasi, ja hän kohta nousi ylös. Ja käski hänelle antaa ruokaa."],[8,56,"Ja hänen vanhempansa hämmästyivät: mutta hän haastoi heitä kellekään sanomasta sitä mikä tapahtui.","Ja hänen vanhempansa hämmästyivät: mutta hän haastoi heitä kellekään sanomasta sitä mikä tapahtui."],[9,1,"Mutta hän kutsui kokoon kaksitoistakymmentä opetuslastansa, ja antoi heille voiman ja vallan kaikkein perkeleiden ylitse, ja taudit parantaa,","Mutta hän kutsui kokoon kaksitoistakymmentä opetuslastansa, ja antoi heille voiman ja vallan kaikkein perkeleiden ylitse, ja taudit parantaa,"],[9,2,"Ja lähetti heitä saarnaamaan Jumalan valtakuntaa ja parantamaan sairaita.","Ja lähetti heitä saarnaamaan Jumalan valtakuntaa ja parantamaan sairaita."],[9,3,"Ja sanoi heille: älkäät ottako mitään myötänne tielle, ei sauvoja, eikä myös säkkiä, eikä leipää, eikä rahaa: älkää myös kahta hametta pitäkö.","Ja sanoi heille: älkäät ottako mitään myötänne tielle, ei sauvoja, eikä myös säkkiä, eikä leipää, eikä rahaa: älkää myös kahta hametta pitäkö."],[9,4,"Ja johon huoneesen te tulette sisälle, siinä te olkaat ja siitä lähtekäät ulos.","Ja johon huoneesen te tulette sisälle, siinä te olkaat ja siitä lähtekäät ulos."],[9,5,"Ja kuka ikänä ei teitä ota vastaan, niin menkäät pois siitä kaupungista ja puhdistakaat tomu teidän jaloistanne, todistukseksi heitä vastaan.","Ja kuka ikänä ei teitä ota vastaan, niin menkäät pois siitä kaupungista ja puhdistakaat tomu teidän jaloistanne, todistukseksi heitä vastaan."],[9,6,"Ja he menivät ulos ja vaelsivat kylissä, saarnaten evankeliumia, ja paransivat joka paikassa.","Ja he menivät ulos ja vaelsivat kylissä, saarnaten evankeliumia, ja paransivat joka paikassa."],[9,7,"Mutta Herodes tetrarka kuuli kaikki, mitä häneltä tehty oli, ja hän epäili, että muutamat sanoivat Johanneksen nousseeksi kuolleista.","Mutta Herodes tetrarka kuuli kaikki, mitä häneltä tehty oli, ja hän epäili, että muutamat sanoivat Johanneksen nousseeksi kuolleista."],[9,8,"Muutamat taas Eliaan ilmaantuneen, ja muut, että joku prophetaista oli noussut ylös.","Muutamat taas Eliaan ilmaantuneen, ja muut, että joku prophetaista oli noussut ylös."],[9,9,"Ja Herodes sanoi: Johanneksen kaulan minä leikkasin; vaan kuka tämä lienee, josta minä senkaltaisia kuulen? Ja hän pyysi nähdä häntä.","Ja Herodes sanoi: Johanneksen kaulan minä leikkasin; vaan kuka tämä lienee, josta minä senkaltaisia kuulen? Ja hän pyysi nähdä häntä."],[9,10,"Ja apostolit palasivat, ja juttelivat hänelle kaikki, mitä he olivat tehneet. Ja hän otti heidät tykönsä ja meni erinänsä Betsaidan kaupungin erämaahan.","Ja apostolit palasivat, ja juttelivat hänelle kaikki, mitä he olivat tehneet. Ja hän otti heidät tykönsä ja meni erinänsä Betsaidan kaupungin erämaahan."],[9,11,"Kuin kansa sen ymmärsi, seurasivat he häntä, ja hän otti heitä vastaan, ja puhui heille Jumalan valtakunnasta, ja jotka parannusta tarvitsivat, teki hän terveeksi.","Kuin kansa sen ymmärsi, seurasivat he häntä, ja hän otti heitä vastaan, ja puhui heille Jumalan valtakunnasta, ja jotka parannusta tarvitsivat, teki hän terveeksi."],[9,12,"Mutta päivä rupesi jo laskemaan ja ne kaksitoistakymmentä tulivat ja sanoivat hänelle: päästä kansa menemään lähikyliin ja majoihin poikkeamaan, ruokaa saamaan; sillä me olemme täällä erämaassa.","Mutta päivä rupesi jo laskemaan ja ne kaksitoistakymmentä tulivat ja sanoivat hänelle: päästä kansa menemään lähikyliin ja majoihin poikkeamaan, ruokaa saamaan; sillä me olemme täällä erämaassa."],[9,13,"Niin hän sanoi heille: antakaat te heille syötävää; mutta he sanoivat: ei meillä enempi ole kuin viisi leipää ja kaksi kalaa, ellemme mene ja osta ruokaa kaikelle tälle kansalle;","Niin hän sanoi heille: antakaat te heille syötävää; mutta he sanoivat: ei meillä enempi ole kuin viisi leipää ja kaksi kalaa, ellemme mene ja osta ruokaa kaikelle tälle kansalle;"],[9,14,"Sillä heitä oli lähes viisituhatta miestä. Niin hän sanoi opetuslapsillensa: pankaat heitä istumaan kuhunkin joukkoon viisikymmentä.","Sillä heitä oli lähes viisituhatta miestä. Niin hän sanoi opetuslapsillensa: pankaat heitä istumaan kuhunkin joukkoon viisikymmentä."],[9,15,"Ja he tekivät niin ja asettivat heidät kaikki aterioitsemaan.","Ja he tekivät niin ja asettivat heidät kaikki aterioitsemaan."],[9,16,"Niin hän otti ne viisi leipää ja kaksi kalaa, ja katsoi taivaasen ja siunasi niitä, ja mursi ja antoi opetuslapsille panna kansan eteen.","Niin hän otti ne viisi leipää ja kaksi kalaa, ja katsoi taivaasen ja siunasi niitä, ja mursi ja antoi opetuslapsille panna kansan eteen."],[9,17,"Ja he söivät kaikki ja ravittiin; ja koottiin tähteitä, jotka jäi, kaksitoistakymmentä koria muruja.","Ja he söivät kaikki ja ravittiin; ja koottiin tähteitä, jotka jäi, kaksitoistakymmentä koria muruja."],[9,18,"Ja tapahtui, kuin hän yksinänsä rukoilemassa oli, olivat myös opetuslapset hänen kanssansa, ja hän kysyi heiltä, sanoen: kenenkä sanoo kansa minun olevan?","Ja tapahtui, kuin hän yksinänsä rukoilemassa oli, olivat myös opetuslapset hänen kanssansa, ja hän kysyi heiltä, sanoen: kenenkä sanoo kansa minun olevan?"],[9,19,"Mutta ha vastasivat ja sanoivat: Johannes Kastajan, ja muutamat Eliaan, muutamat taas jonkun vanhoista prophetaista nousseen ylös.","Mutta ha vastasivat ja sanoivat: Johannes Kastajan, ja muutamat Eliaan, muutamat taas jonkun vanhoista prophetaista nousseen ylös."],[9,20,"Niin hän sanoi heille: kenenkäs te sanotte minun olevan? Vastasi Pietari ja sanoi: sinä olet Jumalan Kristus.","Niin hän sanoi heille: kenenkäs te sanotte minun olevan? Vastasi Pietari ja sanoi: sinä olet Jumalan Kristus."],[9,21,"Ja hän haastoi heitä, ja kielsi heidät kellekään sitä sanomasta.","Ja hän haastoi heitä, ja kielsi heidät kellekään sitä sanomasta."],[9,22,"Ja sanoi: Ihmisen Pojan pitää paljo kärsimän, ja hyljättämän vanhimmita ja pappein päämiehiltä ja kirjanoppineilta, ja tapettaman, ja kolmantena päivänä hän on nouseva ylös.","Ja sanoi: Ihmisen Pojan pitää paljo kärsimän, ja hyljättämän vanhimmita ja pappein päämiehiltä ja kirjanoppineilta, ja tapettaman, ja kolmantena päivänä hän on nouseva ylös."],[9,23,"Niin hän sanoi kaikille: jos joku tahtoo minun perässäni tulla, hän kieltäkään itsensä, ja ottakaan ristinsä joka päivä, ja seuratkaan minua.","Niin hän sanoi kaikille: jos joku tahtoo minun perässäni tulla, hän kieltäkään itsensä, ja ottakaan ristinsä joka päivä, ja seuratkaan minua."],[9,24,"Sillä joka henkensä tähdellä pitää tahtoo, hänen pitää sen kadottaman; mutta joka henkensä kadottaa minun tähteni, hän pitää sen tallella.","Sillä joka henkensä tähdellä pitää tahtoo, hänen pitää sen kadottaman; mutta joka henkensä kadottaa minun tähteni, hän pitää sen tallella."],[9,25,"Sillä mitä se hyödyttää ihmistä, jos hän kaiken maailman voittais, ja itsensä kadottais, eli vahinkoon saattais?","Sillä mitä se hyödyttää ihmistä, jos hän kaiken maailman voittais, ja itsensä kadottais, eli vahinkoon saattais?"],[9,26,"Sillä kuka ikänä minua häpee ja minun sanojani, sitä Ihmisen Pojan pitää häpeemän, kuin hän ole tuleva hänen ja Isän ja pyhäin enkelien kunniassa.","Sillä kuka ikänä minua häpee ja minun sanojani, sitä Ihmisen Pojan pitää häpeemän, kuin hän ole tuleva hänen ja Isän ja pyhäin enkelien kunniassa."],[9,27,"Mutta minä totisesti sanon teille: muutamat ovat, jotka tässä seisovat, jotka ei maista kuolemaa, siihen asti kuin he näkevät Jumalan valtakunnan.","Mutta minä totisesti sanon teille: muutamat ovat, jotka tässä seisovat, jotka ei maista kuolemaa, siihen asti kuin he näkevät Jumalan valtakunnan."],[9,28,"Ja tapahtui kahdeksan päivän perästä näiden sanain jälkeen, että hän otti tykönsä Pietarin ja Johanneksen ja Jakobin, ja meni ylös vuorelle rukoilemaan.","Ja tapahtui kahdeksan päivän perästä näiden sanain jälkeen, että hän otti tykönsä Pietarin ja Johanneksen ja Jakobin, ja meni ylös vuorelle rukoilemaan."],[9,29,"Ja kuin hän rukoile, muuttui hänen kasvonsa ja hänen vaatteensa tulivat valkiaksi ja kiiltäväksi.","Ja kuin hän rukoile, muuttui hänen kasvonsa ja hänen vaatteensa tulivat valkiaksi ja kiiltäväksi."],[9,30,"Ja katso, kaksi miestä puhui hänen kanssansa, jotka olivat Moses ja Elias,","Ja katso, kaksi miestä puhui hänen kanssansa, jotka olivat Moses ja Elias,"],[9,31,"Jotka näkyivät kunniassa ja ja puhuivat hänen menostansa, jonka hän täyttävä oli Jerusalemissa.","Jotka näkyivät kunniassa ja ja puhuivat hänen menostansa, jonka hän täyttävä oli Jerusalemissa."],[9,32,"Mutta Pietari ja jotka hänen kanssansa olivat, olivat unesta raskautetut; mutta koska he heräsivät, näkivät he hänen kunniansa ja ne kaksi miestä, jotka seisoivat hänen tykönänsä.","Mutta Pietari ja jotka hänen kanssansa olivat, olivat unesta raskautetut; mutta koska he heräsivät, näkivät he hänen kunniansa ja ne kaksi miestä, jotka seisoivat hänen tykönänsä."],[9,33,"Ja tapahtui, kuin he läksivät hänen tyköänsä, sanoi Pietari Jesukselle: Mestari, hyvä on meidän tässä olla, tehkäämme tähän kolme majaa, sinulle yhden, Mosekselle yhden ja Eliaalle yhden; eikä tietänyt, mitä sanoi.","Ja tapahtui, kuin he läksivät hänen tyköänsä, sanoi Pietari Jesukselle: Mestari, hyvä on meidän tässä olla, tehkäämme tähän kolme majaa, sinulle yhden, Mosekselle yhden ja Eliaalle yhden; eikä tietänyt, mitä sanoi."],[9,34,"Ja hänen näitä puhuissansa, tuli pilvi ja varjosi ympäri heidät; mutta he peljästyivät, koska tulivat pilven sisälle.","Ja hänen näitä puhuissansa, tuli pilvi ja varjosi ympäri heidät; mutta he peljästyivät, koska tulivat pilven sisälle."],[9,35,"Ja ääni tuli pilvestä, sanoen: tämä on minun rakas Poikani, kuulkaat häntä.","Ja ääni tuli pilvestä, sanoen: tämä on minun rakas Poikani, kuulkaat häntä."],[9,36,"Ja kuin ääni parhaallansa kuului, löysivät he Jesuksen yksin. Ja he vaikenivat, eikä mitään kellenkään niinä päivinä jutelleet niistä, mitkä he nähneet olivat.","Ja kuin ääni parhaallansa kuului, löysivät he Jesuksen yksin. Ja he vaikenivat, eikä mitään kellenkään niinä päivinä jutelleet niistä, mitkä he nähneet olivat."],[9,37,"Mutta tapahtui toisena päivänä, kuin he menivät alas vuorelta, kohtasi heitä paljo väkeä.","Mutta tapahtui toisena päivänä, kuin he menivät alas vuorelta, kohtasi heitä paljo väkeä."],[9,38,"Ja katso, yksi mies huusi kansasta, sanoen: Mestari! minä rukoilen sinua, katso minun poikani puoleen; sillä hän on minulle ainokainen.","Ja katso, yksi mies huusi kansasta, sanoen: Mestari! minä rukoilen sinua, katso minun poikani puoleen; sillä hän on minulle ainokainen."],[9,39,"Ja katso, henki ottaa hänen, ja hän huutaa kohta, ja se repii häntä, niin että hän vaahtuu, ja se luopuu tuskalla hänestä, kuin hän häntä runtelee.","Ja katso, henki ottaa hänen, ja hän huutaa kohta, ja se repii häntä, niin että hän vaahtuu, ja se luopuu tuskalla hänestä, kuin hän häntä runtelee."],[9,40,"Ja minä rukoilin sinun opetuslapsias häntä ajamaan ulos, mutta ei he voineet.","Ja minä rukoilin sinun opetuslapsias häntä ajamaan ulos, mutta ei he voineet."],[9,41,"Niin Jesus vastasi ja sanoi: oi uskomatoin ja nurja sukukunta! kuinka kauvan minun pitää teidän tykönänne oleman ja teitä kärsimän? Tuo poikas tänne.","Niin Jesus vastasi ja sanoi: oi uskomatoin ja nurja sukukunta! kuinka kauvan minun pitää teidän tykönänne oleman ja teitä kärsimän? Tuo poikas tänne."],[9,42,"Ja kuin hän vielä tulossa oli, repeli häntä perkele ja muserteli; mutta Jesus nuhteli rietasta henkeä, ja paransi pojan, ja antoi hänen jälleen isällensä.","Ja kuin hän vielä tulossa oli, repeli häntä perkele ja muserteli; mutta Jesus nuhteli rietasta henkeä, ja paransi pojan, ja antoi hänen jälleen isällensä."],[9,43,"Niin he kaikki hämmästyivät Jumalan kunniallista voimaa. Mutta koska kaikki ihmettelivät kaikkia niitä, mitä Jesus teki, sanoi hän opetuslapsillensa:","Niin he kaikki hämmästyivät Jumalan kunniallista voimaa. Mutta koska kaikki ihmettelivät kaikkia niitä, mitä Jesus teki, sanoi hän opetuslapsillensa:"],[9,44,"Pankaat te nämät puheet korviinne; sillä tuleva on, että Ihmisen Poika annetaan ylön ihmisten käsiin.","Pankaat te nämät puheet korviinne; sillä tuleva on, että Ihmisen Poika annetaan ylön ihmisten käsiin."],[9,45,"Mutta ei he ymmärtäneet sitä sanaa, ja se oli heiltä peitetty, niin ettei he sitä ymmärtäneet; ja he pelkäsivät kysyä sitä sanaa häneltä.","Mutta ei he ymmärtäneet sitä sanaa, ja se oli heiltä peitetty, niin ettei he sitä ymmärtäneet; ja he pelkäsivät kysyä sitä sanaa häneltä."],[9,46,"Niin tuli myös kamppaus heidän keskenänsä, kuka heistä suurin olis.","Niin tuli myös kamppaus heidän keskenänsä, kuka heistä suurin olis."],[9,47,"Kuin Jesus näki heidän sydämensä ajatuksen, otti hän lapsen ja asetti tykönsä,","Kuin Jesus näki heidän sydämensä ajatuksen, otti hän lapsen ja asetti tykönsä,"],[9,48,"Ja sanoi heille: kuka ikänä tämän poikaisen ottaa vastaan minun nimeeni, hän ottaa vastaan minun; ja kuka ikänä minun ottaa vastaan, hän ottaa vastaan sen, joka minun lähetti. Sillä joka vähin on teidän keskenänne, se pitää oleman suurin.","Ja sanoi heille: kuka ikänä tämän poikaisen ottaa vastaan minun nimeeni, hän ottaa vastaan minun; ja kuka ikänä minun ottaa vastaan, hän ottaa vastaan sen, joka minun lähetti. Sillä joka vähin on teidän keskenänne, se pitää oleman suurin."],[9,49,"Niin Johannes vastasi ja sanoi: Mestari! me näimme yhden sinun nimes kautta perkeleitä ajavan ulos, ja me kielsimme häntä; sillä ei hän seuraa meitä.","Niin Johannes vastasi ja sanoi: Mestari! me näimme yhden sinun nimes kautta perkeleitä ajavan ulos, ja me kielsimme häntä; sillä ei hän seuraa meitä."],[9,50,"Ja Jesus sanoi hänelle: älkäät kieltäkö; sillä joka ei ole meitä vastaan, hän on meidän puolestamme.","Ja Jesus sanoi hänelle: älkäät kieltäkö; sillä joka ei ole meitä vastaan, hän on meidän puolestamme."],[9,51,"Mutta tapahtui, kuin aika täytetty oli, että hän piti täältä otettaman ylös, käänsi hän kasvonsa menemään Jerusalemin puoleen,","Mutta tapahtui, kuin aika täytetty oli, että hän piti täältä otettaman ylös, käänsi hän kasvonsa menemään Jerusalemin puoleen,"],[9,52,"Ja lähetti sanansaattajat edellänsä, ja he menivät yhteen Samarialaisten kylään, majaa hänelle valmistamaan.","Ja lähetti sanansaattajat edellänsä, ja he menivät yhteen Samarialaisten kylään, majaa hänelle valmistamaan."],[9,53,"Ja ei ne häntä ottaneet vastaan, että hänen kasvonsa oli käännetty menemään Jerusalemia päin.","Ja ei ne häntä ottaneet vastaan, että hänen kasvonsa oli käännetty menemään Jerusalemia päin."],[9,54,"Mutta kuin hänen opetuslapsensa Jakob ja Johannes sen näkivät, sanoivat he: Herra, tahdotkos, niin me sanomme, että tuli tulee taivaasta ja kadottaa heidät, niinkuin Eliaskin teki?","Mutta kuin hänen opetuslapsensa Jakob ja Johannes sen näkivät, sanoivat he: Herra, tahdotkos, niin me sanomme, että tuli tulee taivaasta ja kadottaa heidät, niinkuin Eliaskin teki?"],[9,55,"Mutta Jesus käänsi itsensä ja nuhteli heitä, sanoen: ette tiedä, minkäkaltaisen hengen te olette.","Mutta Jesus käänsi itsensä ja nuhteli heitä, sanoen: ette tiedä, minkäkaltaisen hengen te olette."],[9,56,"Sillä Ihmisen Poika ei ole tullut kadottamaan ihmisten sieluja, mutta vapahtamaan. Ja he menivät toiseen kylään.","Sillä Ihmisen Poika ei ole tullut kadottamaan ihmisten sieluja, mutta vapahtamaan. Ja he menivät toiseen kylään."],[9,57,"Ja tapahtui heidän vaeltaissansa, että yksi tiellä sanoi: minä seuraan sinua, kuhunkas ikänä menet, Herra.","Ja tapahtui heidän vaeltaissansa, että yksi tiellä sanoi: minä seuraan sinua, kuhunkas ikänä menet, Herra."],[9,58,"Ja Jesus sanoi hänelle: ketuilla ovat luolat ja taivaan linnuilla pesät; mutta ei ihmisen Pojalla ole, kuhunka hän päänsä kallistaa.","Ja Jesus sanoi hänelle: ketuilla ovat luolat ja taivaan linnuilla pesät; mutta ei ihmisen Pojalla ole, kuhunka hän päänsä kallistaa."],[9,59,"Mutta hän sanoi toiselle: seuraa minua! niin se sanoi: Herra, salli minun ensin mennä hautaamaan isääni.","Mutta hän sanoi toiselle: seuraa minua! niin se sanoi: Herra, salli minun ensin mennä hautaamaan isääni."],[9,60,"Niin Jesus sanoi hänelle: anna kuolleet haudata kuolleitansa; mutta mene sinä ja julista Jumalan valtakuntaa.","Niin Jesus sanoi hänelle: anna kuolleet haudata kuolleitansa; mutta mene sinä ja julista Jumalan valtakuntaa."],[9,61,"Ja toinen myös sanoi: Herra, minä seuraan sinua, mutta salli minun ensin mennä hyvästi jättämään niitä, jotka kotonani ovat.","Ja toinen myös sanoi: Herra, minä seuraan sinua, mutta salli minun ensin mennä hyvästi jättämään niitä, jotka kotonani ovat."],[9,62,"Mutta Jesus sanoi hänelle: kuka ikänä kätensä auraan laskee ja taaksensa katsoo, ei se ole sovelias Jumalan valtakuntaan.","Mutta Jesus sanoi hänelle: kuka ikänä kätensä auraan laskee ja taaksensa katsoo, ei se ole sovelias Jumalan valtakuntaan."],[10,1,"Niin asetti Herra toiset seitsemänkymmentä, ja lähetti heitä kaksin ja kaksin edellänsä joka kaupunkiin ja paikkaan, kuhunka hän itse oli tuleva.","Niin asetti Herra toiset seitsemänkymmentä, ja lähetti heitä kaksin ja kaksin edellänsä joka kaupunkiin ja paikkaan, kuhunka hän itse oli tuleva."],[10,2,"Niin hän sanoi heille: eloa tosin on paljo, vaan työväkeä on vähä: rukoilkaat siis elon Herraa, työväkeä lähettämään eloonsa.","Niin hän sanoi heille: eloa tosin on paljo, vaan työväkeä on vähä: rukoilkaat siis elon Herraa, työväkeä lähettämään eloonsa."],[10,3,"Menkäät: katso, minä lähetän teidät niinkuin karitsat sutten keskelle.","Menkäät: katso, minä lähetän teidät niinkuin karitsat sutten keskelle."],[10,4,"Älkäät ottako säkkiä, eikä kukkaroa, eikä kenkiä, ja älkäät ketään tervehtikö tiellä.","Älkäät ottako säkkiä, eikä kukkaroa, eikä kenkiä, ja älkäät ketään tervehtikö tiellä."],[10,5,"Mutta kuhunka huoneesen te menette sisälle, niin sanokaat ensisti: rauha olkoon tälle huoneelle!","Mutta kuhunka huoneesen te menette sisälle, niin sanokaat ensisti: rauha olkoon tälle huoneelle!"],[10,6,"Ja jos siellä on rauhan lapsi, niin teidän rauhanne jää hänen päällensä; mutta jos ei, niin se palajaa teille.","Ja jos siellä on rauhan lapsi, niin teidän rauhanne jää hänen päällensä; mutta jos ei, niin se palajaa teille."],[10,7,"Mutta siinä huoneessa viipykäät, syökäät ja juokaat sitä, mitä heillä on; sillä työmies on palkkansa ansiollinen. Älkäät huoneesta huoneeseen käykö.","Mutta siinä huoneessa viipykäät, syökäät ja juokaat sitä, mitä heillä on; sillä työmies on palkkansa ansiollinen. Älkäät huoneesta huoneeseen käykö."],[10,8,"Mutta kuhunka kaupunkiin te tulette sisälle, ja he teitä ottavat vastaan, niin syökäät mitä teidän eteenne pannaan,","Mutta kuhunka kaupunkiin te tulette sisälle, ja he teitä ottavat vastaan, niin syökäät mitä teidän eteenne pannaan,"],[10,9,"Ja parantakaat sairaita, joita siinä on, ja sanokaat heille: Jumalan valtakunta on teitä lähestynyt.","Ja parantakaat sairaita, joita siinä on, ja sanokaat heille: Jumalan valtakunta on teitä lähestynyt."],[10,10,"Mutta kuhunka kaupunkiin te tulette sisälle, ja ei he teitä ota vastaan, niin menkäät ulos sen kaduille, ja sanokaat:","Mutta kuhunka kaupunkiin te tulette sisälle, ja ei he teitä ota vastaan, niin menkäät ulos sen kaduille, ja sanokaat:"],[10,11,"Tomunkin, joka teidän kaupungistanne tarttui meihin, me pudistamme teille: kuitenkin se tietäkäät, että Jumalan valtakunta oli teitä lähestynyt.","Tomunkin, joka teidän kaupungistanne tarttui meihin, me pudistamme teille: kuitenkin se tietäkäät, että Jumalan valtakunta oli teitä lähestynyt."],[10,12,"Minä sanon teille: Sodomalle pitää sinä päivänä huokiampi oleman kuin sille kaupungille.","Minä sanon teille: Sodomalle pitää sinä päivänä huokiampi oleman kuin sille kaupungille."],[10,13,"Voi sinua Koratsin! voi sinua Betsaida! sillä jos Tyrossa ja Sidonissa olisivat senkaltaiset voimalliset työt tehdyt kuin teidän tykönänne ovat tehdyt, niin he olisivat jo aikaa säkissä ja tuhassa istuneet ja parannuksen tehneet.","Voi sinua Koratsin! voi sinua Betsaida! sillä jos Tyrossa ja Sidonissa olisivat senkaltaiset voimalliset työt tehdyt kuin teidän tykönänne ovat tehdyt, niin he olisivat jo aikaa säkissä ja tuhassa istuneet ja parannuksen tehneet."],[10,14,"Kuitenkin Tyrolle ja Sidonille pitää huokiampi tuomiolle oleman kuin teille.","Kuitenkin Tyrolle ja Sidonille pitää huokiampi tuomiolle oleman kuin teille."],[10,15,"Ja sinä Kapernaum, joka olet taivaasen asti korotettu, sinä pitää hamaan helvettiin alas sysättämän.","Ja sinä Kapernaum, joka olet taivaasen asti korotettu, sinä pitää hamaan helvettiin alas sysättämän."],[10,16,"Joka teitä kuulee, se minua kuulee, ja joka teidät katsoo ylön, se katsoo ylön minun; mutta joka minun katsoo ylön, hän katsoo ylön sen, joka minun lähetti.","Joka teitä kuulee, se minua kuulee, ja joka teidät katsoo ylön, se katsoo ylön minun; mutta joka minun katsoo ylön, hän katsoo ylön sen, joka minun lähetti."],[10,17,"Niin ne seitsemänkymmentä palasivat ilolla, sanoen: Herra, perkeleetkin ovat sinun nimes kautta meidän allemme annetut.","Niin ne seitsemänkymmentä palasivat ilolla, sanoen: Herra, perkeleetkin ovat sinun nimes kautta meidän allemme annetut."],[10,18,"Niin hän sanoi heille: minä näin saatanan taivaasta lankeevan niinkuin pitkäisen tulen.","Niin hän sanoi heille: minä näin saatanan taivaasta lankeevan niinkuin pitkäisen tulen."],[10,19,"Katso, minä annan teille vallan tallata käärmeitä ja skorpioneja ja kaikkea vihollisen voimaa, ja ei teitä mikään ole vahingoitseva,","Katso, minä annan teille vallan tallata käärmeitä ja skorpioneja ja kaikkea vihollisen voimaa, ja ei teitä mikään ole vahingoitseva,"],[10,20,"Kuitenkin älkäät siitä iloitko, että henget teidän allenne annetaan; vaan iloitkaat paremmin, että teidän nimenne ovat kirjoitetut taivaissa.","Kuitenkin älkäät siitä iloitko, että henget teidän allenne annetaan; vaan iloitkaat paremmin, että teidän nimenne ovat kirjoitetut taivaissa."],[10,21,"Sillä hetkellä riemuitsi Jesus hengessä ja sanoi: minä kiitän sinua, Isä, taivaan ja maan Herra, ettäs nämät salasit viisailta ja toimellisilta, ja olet ne ilmoittanut pienille: tosin, Isä, niin oli sinun hyvä tahtos.","Sillä hetkellä riemuitsi Jesus hengessä ja sanoi: minä kiitän sinua, Isä, taivaan ja maan Herra, ettäs nämät salasit viisailta ja toimellisilta, ja olet ne ilmoittanut pienille: tosin, Isä, niin oli sinun hyvä tahtos."],[10,22,"Kaikki ovat minulle annetut Isältäni: ja ei tiedä kenkään, kuka on Poika, vaan Isä: ja kuka on Isä, vaan Poika ja kelle Poika tahtoo ilmoittaa.","Kaikki ovat minulle annetut Isältäni: ja ei tiedä kenkään, kuka on Poika, vaan Isä: ja kuka on Isä, vaan Poika ja kelle Poika tahtoo ilmoittaa."],[10,23,"Ja hän kääntyi opetuslastensa puoleen erinänsä, ja sanoi: autuaat ovat ne silmät, jotka näkevät, joita te näette:","Ja hän kääntyi opetuslastensa puoleen erinänsä, ja sanoi: autuaat ovat ne silmät, jotka näkevät, joita te näette:"],[10,24,"Sillä minä sanon teille: monta prophetaa ja kuningasta tahtoivat nähdä, joita te näette, ja ei nähneet, ja kuulla, joita te kuulette, ja ei kuulleet.","Sillä minä sanon teille: monta prophetaa ja kuningasta tahtoivat nähdä, joita te näette, ja ei nähneet, ja kuulla, joita te kuulette, ja ei kuulleet."],[10,25,"Ja katso, yksi lainoppinut nousi ja kiusasi häntä, sanoen: Mestari, mitä minun pitää tekemän, että minä ijankaikkisen elämän perisin?","Ja katso, yksi lainoppinut nousi ja kiusasi häntä, sanoen: Mestari, mitä minun pitää tekemän, että minä ijankaikkisen elämän perisin?"],[10,26,"Mutta hän sanoi hänelle: mitä laissa on kirjoitettu? kuinkas luet?","Mutta hän sanoi hänelle: mitä laissa on kirjoitettu? kuinkas luet?"],[10,27,"Ja hän vastasi ja sanoi: sinun pitää rakastaman Herraa sinun Jumalaas kaikesta sinun sydämestäs, ja kaikesta sinun sielustas, ja kaikesta sinun voimastas, ja kaikesta sinun mieleltäs: ja sinun lähimmäistäs niinkuin itsiäs.","Ja hän vastasi ja sanoi: sinun pitää rakastaman Herraa sinun Jumalaas kaikesta sinun sydämestäs, ja kaikesta sinun sielustas, ja kaikesta sinun voimastas, ja kaikesta sinun mieleltäs: ja sinun lähimmäistäs niinkuin itsiäs."],[10,28,"Niin hän sanoi hänelle: oikein sinä vastasit; tee se, niin sinä saat elää.","Niin hän sanoi hänelle: oikein sinä vastasit; tee se, niin sinä saat elää."],[10,29,"Mutta hän tahtoi itsensä vanhurskaaksi tehdä ja sanoi Jesukselle: kukas minun lähimmäiseni on?","Mutta hän tahtoi itsensä vanhurskaaksi tehdä ja sanoi Jesukselle: kukas minun lähimmäiseni on?"],[10,30,"Jesus vastasi ja sanoi: yksi ihminen meni alas Jerusalemista Jerikoon, ja tuli ryövärien käsiin, jotka hänen alasti riisuivat ja haavoittivat, menivät pois ja jättivät hänen puolikuolleeksi.","Jesus vastasi ja sanoi: yksi ihminen meni alas Jerusalemista Jerikoon, ja tuli ryövärien käsiin, jotka hänen alasti riisuivat ja haavoittivat, menivät pois ja jättivät hänen puolikuolleeksi."],[10,31,"Niin tapahtui, että yksi pappi sitä tietä vaelsi, ja kuin hän hänen näki, meni hän ohitse.","Niin tapahtui, että yksi pappi sitä tietä vaelsi, ja kuin hän hänen näki, meni hän ohitse."],[10,32,"Niin myös Leviläinen, kuin hän tuli sille paikalle, ja näki hänen, ja meni ohitse.","Niin myös Leviläinen, kuin hän tuli sille paikalle, ja näki hänen, ja meni ohitse."],[10,33,"Mutta yksi Samarialainen vaelsi, ja tuli hänen tykönsä, ja kuin hän näki hänen, armahti hän häntä,","Mutta yksi Samarialainen vaelsi, ja tuli hänen tykönsä, ja kuin hän näki hänen, armahti hän häntä,"],[10,34,"Ja tuli ja sitoi hänen haavansa ja vuodatti siihen öljyä ja viinaa, ja pani juhtansa päälle, ja vei hänen majaan, ja korjasi häntä.","Ja tuli ja sitoi hänen haavansa ja vuodatti siihen öljyä ja viinaa, ja pani juhtansa päälle, ja vei hänen majaan, ja korjasi häntä."],[10,35,"Ja toisena päivänä matkusti hän, ja otti kaksi penninkiä ja antoi isännälle, ja sanoi hänelle: korjaa häntä, ja jos sinä enemmän kulutat, niin minä palatessani maksan sinulle.","Ja toisena päivänä matkusti hän, ja otti kaksi penninkiä ja antoi isännälle, ja sanoi hänelle: korjaa häntä, ja jos sinä enemmän kulutat, niin minä palatessani maksan sinulle."],[10,36,"Kuka siis näistä kolmesta oli sinun nähdäkses hänen lähimmäisensä, joka ryövärien käsiin oli tullut?","Kuka siis näistä kolmesta oli sinun nähdäkses hänen lähimmäisensä, joka ryövärien käsiin oli tullut?"],[10,37,"Niin hän sanoi: joka laupiuden teki hänen kohtaansa. Niin sanoi Jesus hänelle: mene ja tee sinä myös niin.","Niin hän sanoi: joka laupiuden teki hänen kohtaansa. Niin sanoi Jesus hänelle: mene ja tee sinä myös niin."],[10,38,"Niin tapahtui, kuin he vaelsivat, meni hän yhteen kylään, ja yksi vaimo, Martta nimeltä, otti hänen huoneesensa,","Niin tapahtui, kuin he vaelsivat, meni hän yhteen kylään, ja yksi vaimo, Martta nimeltä, otti hänen huoneesensa,"],[10,39,"Ja hänellä oli sisar, joka kutsuttiin Maria, joka myös istui Jesuksen jalkain juureen ja kuulteli hänen puhettansa.","Ja hänellä oli sisar, joka kutsuttiin Maria, joka myös istui Jesuksen jalkain juureen ja kuulteli hänen puhettansa."],[10,40,"Mutta Martta teki paljon askareita palvellen heitä; hän tuli ja sanoi: Herra, etkös tottele, että minun sisareni jätti minun yksin askaroitsemaan? Sano siis hänelle, että hän minua auttais.","Mutta Martta teki paljon askareita palvellen heitä; hän tuli ja sanoi: Herra, etkös tottele, että minun sisareni jätti minun yksin askaroitsemaan? Sano siis hänelle, että hän minua auttais."],[10,41,"Niin Jesus vastasi ja sanoi hänelle: Martta, Martta, paljon sinä suret ja pyrit.","Niin Jesus vastasi ja sanoi hänelle: Martta, Martta, paljon sinä suret ja pyrit."],[10,42,"Vaan yksi on tarpeellinen: Maria on hyvän osan valinnut, joka ei häneltä pidä otettaman pois.","Vaan yksi on tarpeellinen: Maria on hyvän osan valinnut, joka ei häneltä pidä otettaman pois."],[11,1,"Ja tapahtui, että hän rukoili yhdessä paikassa, ja kuin hän lakkasi, sanoi hänelle yksi hänen opetuslapsistansa: Herra, opeta meitä rukoilemaan, niinkuin Johanneskin opetti opetuslapsensa.","Ja tapahtui, että hän rukoili yhdessä paikassa, ja kuin hän lakkasi, sanoi hänelle yksi hänen opetuslapsistansa: Herra, opeta meitä rukoilemaan, niinkuin Johanneskin opetti opetuslapsensa."],[11,2,"Niin hän sanoi heille: kuin te rukoilette, niin sanokaat: Isä meidän, joka olet taivaissa. Pyhitetty olkoon sinun nimes. Lähestyköön sinun valtakuntas. Tapahtukoon sinun tahtos niin maassa, kuin taivaassa.","Niin hän sanoi heille: kuin te rukoilette, niin sanokaat: Isä meidän, joka olet taivaissa. Pyhitetty olkoon sinun nimes. Lähestyköön sinun valtakuntas. Tapahtukoon sinun tahtos niin maassa, kuin taivaassa."],[11,3,"Anna meille tänäpäivänä meidän jokapäiväinen leipämme.","Anna meille tänäpäivänä meidän jokapäiväinen leipämme."],[11,4,"Ja anna meille meidän syntimme anteeksi, sillä mekin kaikille meidän velvollisillemme anteeksi annamme. Ja älä johdata meitä kiusaukseen. Mutta päästä meitä pahasta.","Ja anna meille meidän syntimme anteeksi, sillä mekin kaikille meidän velvollisillemme anteeksi annamme. Ja älä johdata meitä kiusaukseen. Mutta päästä meitä pahasta."],[11,5,"Ja hän sanoi heille: kellä teistä on ystävä, ja menee puoliyöstä hänen tykönsä, ja sanoo hänelle: ystäväni, lainaas minulle kolme leipää;","Ja hän sanoi heille: kellä teistä on ystävä, ja menee puoliyöstä hänen tykönsä, ja sanoo hänelle: ystäväni, lainaas minulle kolme leipää;"],[11,6,"Sillä minun ystäväni tuli matkasta minun tyköni, ja ei minulla ole, mitä minä panen hänen eteensä.","Sillä minun ystäväni tuli matkasta minun tyköni, ja ei minulla ole, mitä minä panen hänen eteensä."],[11,7,"Ja hän vastaa huoneestansa ja sanoo: älä minua vaivaa! ovi on jo suljettu, ja minun lapseni minun kanssani ovat vuoteessa: en minä voi nousta sinulle antamaan.","Ja hän vastaa huoneestansa ja sanoo: älä minua vaivaa! ovi on jo suljettu, ja minun lapseni minun kanssani ovat vuoteessa: en minä voi nousta sinulle antamaan."],[11,8,"Minä sanon teille: ellei hän nouse ja anna hänelle, että hän on hänen ystävänsä, niin hän kuitenkin hänen ahkeruutensa tähden nousee ja antaa hänelle niin monta kuin hän tarvitsee.","Minä sanon teille: ellei hän nouse ja anna hänelle, että hän on hänen ystävänsä, niin hän kuitenkin hänen ahkeruutensa tähden nousee ja antaa hänelle niin monta kuin hän tarvitsee."],[11,9,"Ja minä myös sanon teille: anokaat, niin teille annetaan: etsikäät, niin te löydätte: kolkuttakaat niin teille avataan.","Ja minä myös sanon teille: anokaat, niin teille annetaan: etsikäät, niin te löydätte: kolkuttakaat niin teille avataan."],[11,10,"Sillä jokainen joka anoo, se saa, ja joka etsii, se löytää, ja joka kolkuttaa, sille avataan.","Sillä jokainen joka anoo, se saa, ja joka etsii, se löytää, ja joka kolkuttaa, sille avataan."],[11,11,"Kuka teistä on isä, jolta poika anoo leipää, antaako hän hänelle kiven? eli jos hän anoo kalaa, antaako hän kalan edestä hänelle kärmeen?","Kuka teistä on isä, jolta poika anoo leipää, antaako hän hänelle kiven? eli jos hän anoo kalaa, antaako hän kalan edestä hänelle kärmeen?"],[11,12,"Eli jos hän anoo munaa, antaako hän hänelle skorpionin?","Eli jos hän anoo munaa, antaako hän hänelle skorpionin?"],[11,13,"Jos siis te, jotka pahat olette, taidatte hyviä lahjoja antaa teidän lapsillenne, paljoa enemmin teidän taivaallinen Isänne antaa Pyhän Hengen sitä anovaisille.","Jos siis te, jotka pahat olette, taidatte hyviä lahjoja antaa teidän lapsillenne, paljoa enemmin teidän taivaallinen Isänne antaa Pyhän Hengen sitä anovaisille."],[11,14,"Ja hän ajoi ulos perkeleen, joka oli mykkä. Ja tapahtui, kuin perkele oli ajettu ulos, niin mykkä puhui ja kansa ihmetteli.","Ja hän ajoi ulos perkeleen, joka oli mykkä. Ja tapahtui, kuin perkele oli ajettu ulos, niin mykkä puhui ja kansa ihmetteli."],[11,15,"Mutta muutamat heistä sanoivat: hän ajaa ulos perkeleitä beelsebubin, perkeleiden päämiehen kautta.","Mutta muutamat heistä sanoivat: hän ajaa ulos perkeleitä beelsebubin, perkeleiden päämiehen kautta."],[11,16,"Mutta muut kiusasivat häntä ja anoivat häneltä tunnustähteä taivaasta.","Mutta muut kiusasivat häntä ja anoivat häneltä tunnustähteä taivaasta."],[11,17,"Mutta että hän tiesi heidän ajatuksensa, sanoi hän heille: jokainen valtakunta, joka erkanee itsiänsä vastaan, se tulee kylmille, ja huone lankee huoneen päälle.","Mutta että hän tiesi heidän ajatuksensa, sanoi hän heille: jokainen valtakunta, joka erkanee itsiänsä vastaan, se tulee kylmille, ja huone lankee huoneen päälle."],[11,18,"Jos myös saatana on erinnyt itsiänsä vastaan, kuinka hänen valtakuntansa on seisovainen? että te sanotte minun perkeleitä belsebubin kautta ajavan ulos.","Jos myös saatana on erinnyt itsiänsä vastaan, kuinka hänen valtakuntansa on seisovainen? että te sanotte minun perkeleitä belsebubin kautta ajavan ulos."],[11,19,"Mutta jos minä perkeleitä belsebubin kautta ajan ulos, kenenkä kautta teidän poikanne niitä ajavat ulos? Sentähden heidän pitää oleman teidän tuomarinne.","Mutta jos minä perkeleitä belsebubin kautta ajan ulos, kenenkä kautta teidän poikanne niitä ajavat ulos? Sentähden heidän pitää oleman teidän tuomarinne."],[11,20,"Mutta jos minä Jumalan sormella perkeleitä ajan ulos, niin tosin on Jumalan valtakunta teidän tykönne tullut.","Mutta jos minä Jumalan sormella perkeleitä ajan ulos, niin tosin on Jumalan valtakunta teidän tykönne tullut."],[11,21,"Kuin väkevä haarniskoitu kotonsa varjelee, niin hänen omansa ovat rauhassa.","Kuin väkevä haarniskoitu kotonsa varjelee, niin hänen omansa ovat rauhassa."],[11,22,"Mutta kuin häntä väkevämpi tulee ja voittaa hänen, niin hän ottaa pois kaikki hänen sota-aseensa, joihin hän turvasi, ja jakaa hänen saaliinsa,","Mutta kuin häntä väkevämpi tulee ja voittaa hänen, niin hän ottaa pois kaikki hänen sota-aseensa, joihin hän turvasi, ja jakaa hänen saaliinsa,"],[11,23,"Joka ei ole minun kanssani, se on minua vastaan, ja joka ei minun kanssani kokoo, hän hajoittaa.","Joka ei ole minun kanssani, se on minua vastaan, ja joka ei minun kanssani kokoo, hän hajoittaa."],[11,24,"Kuin rietas henki lähtee ihmisestä, niin hän vaeltaa karkeita paikkoja, ja etsii lepoa; ja kuin ei hän löydä, niin hän sanoo: minä palajan minun huoneeseni, josta minä läksin.","Kuin rietas henki lähtee ihmisestä, niin hän vaeltaa karkeita paikkoja, ja etsii lepoa; ja kuin ei hän löydä, niin hän sanoo: minä palajan minun huoneeseni, josta minä läksin."],[11,25,"Ja kuin hän tulee, löytää hän sen luudilla lakaistuksi ja kaunistetuksi.","Ja kuin hän tulee, löytää hän sen luudilla lakaistuksi ja kaunistetuksi."],[11,26,"Silloin hän menee ja ottaa kanssansa seitsemän muuta häntä pahempaa henkeä, ja kuin he sinne tulevat, asuvat he siellä: ja sen ihmisen viimeiset tulevat pahemmiksi kuin ensimmäiset.","Silloin hän menee ja ottaa kanssansa seitsemän muuta häntä pahempaa henkeä, ja kuin he sinne tulevat, asuvat he siellä: ja sen ihmisen viimeiset tulevat pahemmiksi kuin ensimmäiset."],[11,27,"Ja tapahtui, kuin hän näitä sanoi, korotti yksi vaimo kansan seasta äänensä ja sanoi: autuas on se kohtu, joka sinun kantanut on, ja ne nisät, joitas imit.","Ja tapahtui, kuin hän näitä sanoi, korotti yksi vaimo kansan seasta äänensä ja sanoi: autuas on se kohtu, joka sinun kantanut on, ja ne nisät, joitas imit."],[11,28,"Niin hän sanoi: ja tosin, autuaat ovat ne, jotka kuulevat Jumalan sanan ja kätkevät sen.","Niin hän sanoi: ja tosin, autuaat ovat ne, jotka kuulevat Jumalan sanan ja kätkevät sen."],[11,29,"Mutta kuin kansa kokoon tuli, rupesi hän sanomaan: tämä sukukunta on paha, etsii merkkiä, ja ei hänelle anneta merkkiä, vaan Jonan prophetan merkki.","Mutta kuin kansa kokoon tuli, rupesi hän sanomaan: tämä sukukunta on paha, etsii merkkiä, ja ei hänelle anneta merkkiä, vaan Jonan prophetan merkki."],[11,30,"Sillä niinkuin Jona oli Niniveläisille merkiksi, niin pitää myös Ihmisen Poika oleman tälle sukukunnalle.","Sillä niinkuin Jona oli Niniveläisille merkiksi, niin pitää myös Ihmisen Poika oleman tälle sukukunnalle."],[11,31,"Etelän kuningatar pitää nouseman tuomiolle tämän sukukunnan miesten kanssa, ja heitä tuomitseman: sillä hän oli maan ääristä kuuleman Salomonin viisautta, ja katso, tässä on enempi kuin Salomon.","Etelän kuningatar pitää nouseman tuomiolle tämän sukukunnan miesten kanssa, ja heitä tuomitseman: sillä hän oli maan ääristä kuuleman Salomonin viisautta, ja katso, tässä on enempi kuin Salomon."],[11,32,"Niniven miehet pitää tuleman tuomiolle tämän sukukunnan kanssa, ja sen kadottaman; sillä he tekivät parannuksen Jonan saarnasta, ja katso tässä on enempi kuin Jona.","Niniven miehet pitää tuleman tuomiolle tämän sukukunnan kanssa, ja sen kadottaman; sillä he tekivät parannuksen Jonan saarnasta, ja katso tässä on enempi kuin Jona."],[11,33,"Ei sytytä kenkään kynttilää ja pane kätköön eikä vakan alle, mutta kynttiläjalkaan, että sisälle tulevaiset valkeuden näkisivät.","Ei sytytä kenkään kynttilää ja pane kätköön eikä vakan alle, mutta kynttiläjalkaan, että sisälle tulevaiset valkeuden näkisivät."],[11,34,"Silmä on ruumiin valkeus: kuin siis sinun silmäs on yksinkertainen, niin myös koko sinun ruumiis on valaistu; mutta kuin se paha on, niin myös sinun ruumiis on pimiä.","Silmä on ruumiin valkeus: kuin siis sinun silmäs on yksinkertainen, niin myös koko sinun ruumiis on valaistu; mutta kuin se paha on, niin myös sinun ruumiis on pimiä."],[11,35,"Katso siis, ettei se valkeus, joka sinussa on, olisi pimeys.","Katso siis, ettei se valkeus, joka sinussa on, olisi pimeys."],[11,36,"Sentähden jos koko sinun ruumiis on valaistu, ja ei ole siinä yhtään pimiää paikkaa, niin se tulee kokonansa valaistuksi, koska valkeus niinkuin kirkkaalla leimauksella sinun valaisee.","Sentähden jos koko sinun ruumiis on valaistu, ja ei ole siinä yhtään pimiää paikkaa, niin se tulee kokonansa valaistuksi, koska valkeus niinkuin kirkkaalla leimauksella sinun valaisee."],[11,37,"Ja hänen puhuissansa rukoili häntä yksi Pharisealainen ruoalle kanssansa; niin hän meni ja atrioitsi.","Ja hänen puhuissansa rukoili häntä yksi Pharisealainen ruoalle kanssansa; niin hän meni ja atrioitsi."],[11,38,"Mutta kuin Pharisealainen näki, ihmetteli hän, ettei hän ensin itsiänsä pessyt ennen ruan aikaa.","Mutta kuin Pharisealainen näki, ihmetteli hän, ettei hän ensin itsiänsä pessyt ennen ruan aikaa."],[11,39,"Niin sanoi Herra hänelle: nyt te Pharisealaiset, ulkoa te maljan ja vadin puhdistatte, mutta sisälliset teissä ovat täynnä raatelusta ja pahuutta.","Niin sanoi Herra hänelle: nyt te Pharisealaiset, ulkoa te maljan ja vadin puhdistatte, mutta sisälliset teissä ovat täynnä raatelusta ja pahuutta."],[11,40,"Te hullut, eikö se, joka ulkoisen puolen teki, tehnyt myös sisälmäistä puolta?","Te hullut, eikö se, joka ulkoisen puolen teki, tehnyt myös sisälmäistä puolta?"],[11,41,"Kuitenkin antakaa almua niistä, mitä teillä on, ja katso, niin teille ovat kaikki puhtaat.","Kuitenkin antakaa almua niistä, mitä teillä on, ja katso, niin teille ovat kaikki puhtaat."],[11,42,"Mutta voi teitä, te Pharisealaiset! että te kymmenykset teette mintuista ja ruuasta, ja kaikkinaisista kaaleista, ja jätätte pois tuomion ja Jumalan rakkauden: näitä piti tehtämän, ja toisia ei jätettämän.","Mutta voi teitä, te Pharisealaiset! että te kymmenykset teette mintuista ja ruuasta, ja kaikkinaisista kaaleista, ja jätätte pois tuomion ja Jumalan rakkauden: näitä piti tehtämän, ja toisia ei jätettämän."],[11,43,"Voi teitä, te Pharisealaiset! jotka rakastatte ylimmäisiä istuimia synagogissa ja tervehdyksiä turulla.","Voi teitä, te Pharisealaiset! jotka rakastatte ylimmäisiä istuimia synagogissa ja tervehdyksiä turulla."],[11,44,"Voi teitä, te kirjanoppineet ja Pharisealaiset, te ulkokullatut! sillä te olette niinkuin peitetyt haudat, joiden päällä ihmiset tietämättä käyvät.","Voi teitä, te kirjanoppineet ja Pharisealaiset, te ulkokullatut! sillä te olette niinkuin peitetyt haudat, joiden päällä ihmiset tietämättä käyvät."],[11,45,"Niin vastasi yksi lainoppineista ja sanoi hänelle: Mestari, näillä sanoilla sinä myös meitä pilkkaat.","Niin vastasi yksi lainoppineista ja sanoi hänelle: Mestari, näillä sanoilla sinä myös meitä pilkkaat."],[11,46,"Niin hän sanoi: voi teitäkin, te lainoppineet! sillä te raskautatte ihmiset kuormilla, jotka ovat työläät kantaa, ja ette itse yhdellä sormellannekaan tahdo niihin kuormiin ruveta.","Niin hän sanoi: voi teitäkin, te lainoppineet! sillä te raskautatte ihmiset kuormilla, jotka ovat työläät kantaa, ja ette itse yhdellä sormellannekaan tahdo niihin kuormiin ruveta."],[11,47,"Voi teitä, että te rakennatte prophetain hautoja, mutta tiedän isänne tappoivat ne.","Voi teitä, että te rakennatte prophetain hautoja, mutta tiedän isänne tappoivat ne."],[11,48,"Niin te tosin todistatte ja suostutte teidän isäinne töihin; sillä he tappoivat ne, mutta te rakennatte niiden haudat.","Niin te tosin todistatte ja suostutte teidän isäinne töihin; sillä he tappoivat ne, mutta te rakennatte niiden haudat."],[11,49,"Sentähden myös Jumalan viisaus sanoi: minä lähetän heidän tykönsä prophetat ja apostolit, ja muutamat niistä he tappavat ja vainoovat:","Sentähden myös Jumalan viisaus sanoi: minä lähetän heidän tykönsä prophetat ja apostolit, ja muutamat niistä he tappavat ja vainoovat:"],[11,50,"Että tältä sukukunnalta pitää etsittämän kaikkein prophetain veri, joka on vuodatettu maailman alusta,","Että tältä sukukunnalta pitää etsittämän kaikkein prophetain veri, joka on vuodatettu maailman alusta,"],[11,51,"Abelin verestä hamaan Sakariaan vereen asti, joka hukattiin alttarin ja templin vaiheella; tosin minä sanon teille, se pitää etsittämän tältä sukukunnalta.","Abelin verestä hamaan Sakariaan vereen asti, joka hukattiin alttarin ja templin vaiheella; tosin minä sanon teille, se pitää etsittämän tältä sukukunnalta."],[11,52,"Voi teitä lainoppineet! sillä te olette ottaneet taidon avaimen: itse ette menneet sisälle, ja sisälle meneväisiä te kielsitte.","Voi teitä lainoppineet! sillä te olette ottaneet taidon avaimen: itse ette menneet sisälle, ja sisälle meneväisiä te kielsitte."],[11,53,"Mutta kuin hän oli nämät heille sanonut, rupesivat lainoppineet ja Pharisealaiset kovin häntä ahdistamaan ja viettelemään häntä puhumaan monesta,","Mutta kuin hän oli nämät heille sanonut, rupesivat lainoppineet ja Pharisealaiset kovin häntä ahdistamaan ja viettelemään häntä puhumaan monesta,"],[11,54,"Ja väijyivät häntä ja pyysivät jotakin onkia hänen suustansa, kantaaksensa hänen päällensä.","Ja väijyivät häntä ja pyysivät jotakin onkia hänen suustansa, kantaaksensa hänen päällensä."],[12,1,"Kuin monta tuhatta ihmistä kokoontuivat, niin että he toinen toistansa tallasivat, rupesi hän sanomaan opetuslapsillensa: kavahtakaat ensisti Pharisealaisten hapatusta, joka on ulkokullaisuus;","Kuin monta tuhatta ihmistä kokoontuivat, niin että he toinen toistansa tallasivat, rupesi hän sanomaan opetuslapsillensa: kavahtakaat ensisti Pharisealaisten hapatusta, joka on ulkokullaisuus;"],[12,2,"Sillä ei ole mitään peitetty, joka ei ilmi tule, eikä ole salattu, mikä ei tiettäväksi tule.","Sillä ei ole mitään peitetty, joka ei ilmi tule, eikä ole salattu, mikä ei tiettäväksi tule."],[12,3,"Sentähden ne, mitä te pimeydessä sanotte, pitää valkeudessa kuultaman, ja mitä te korvaan puhuneet olette kammioissa, se pitää saarnattaman kattoin päällä.","Sentähden ne, mitä te pimeydessä sanotte, pitää valkeudessa kuultaman, ja mitä te korvaan puhuneet olette kammioissa, se pitää saarnattaman kattoin päällä."],[12,4,"Mutta minä sanon teille, minun ystävilleni: älkäät niitä peljätkö, jotka ruumiin tappavat, ja ei ole heidän sitte enempää tekemistä.","Mutta minä sanon teille, minun ystävilleni: älkäät niitä peljätkö, jotka ruumiin tappavat, ja ei ole heidän sitte enempää tekemistä."],[12,5,"Mutta minä tahdon osoittaa teille, ketä teidän tulee peljätä: peljätkää sitä, jolla on valta, sittekuin hän tappanut on, myös helvettiin sysätä; totta minä sanon teille: sitä te peljätkäät.","Mutta minä tahdon osoittaa teille, ketä teidän tulee peljätä: peljätkää sitä, jolla on valta, sittekuin hän tappanut on, myös helvettiin sysätä; totta minä sanon teille: sitä te peljätkäät."],[12,6,"Eikö viisi varpusta myydä kahteen ropoon? ja ei yksikään heistä ole Jumalan edessä unohdettu.","Eikö viisi varpusta myydä kahteen ropoon? ja ei yksikään heistä ole Jumalan edessä unohdettu."],[12,7,"Ovat myös kaikki teidän päänne hiukset luetut. Älkäät siis peljätkö: te olette paremmat kuin monta varpusta.","Ovat myös kaikki teidän päänne hiukset luetut. Älkäät siis peljätkö: te olette paremmat kuin monta varpusta."],[12,8,"Mutta minä sanon teille: jokainen joka minun tunnustaa ihmisten edessä, sen myös Ihmisen Poika on tunnustava Jumalan enkelien edessä:","Mutta minä sanon teille: jokainen joka minun tunnustaa ihmisten edessä, sen myös Ihmisen Poika on tunnustava Jumalan enkelien edessä:"],[12,9,"Mutta joka minun kieltää ihmisten edessä, se pitää kiellettämän Jumalan enkelien edessä.","Mutta joka minun kieltää ihmisten edessä, se pitää kiellettämän Jumalan enkelien edessä."],[12,10,"Ja joka puhuu sanan Ihmisen Poikaa vastaan, se hänelle anteeksi annetaan; mutta joka Pyhää Henkeä pilkkaa, ei sitä anteeksi anneta.","Ja joka puhuu sanan Ihmisen Poikaa vastaan, se hänelle anteeksi annetaan; mutta joka Pyhää Henkeä pilkkaa, ei sitä anteeksi anneta."],[12,11,"Kuin he teitä vetävät synagogiin, esivallan ja valtamiesten eteen, niin älkäät murehtiko, kuinka taikka mitä teidän edestänne vastaaman pitää, eli mitä teidän pitää sanoman.","Kuin he teitä vetävät synagogiin, esivallan ja valtamiesten eteen, niin älkäät murehtiko, kuinka taikka mitä teidän edestänne vastaaman pitää, eli mitä teidän pitää sanoman."],[12,12,"Sillä Pyhä Henki opettaa teitä sillä hetkellä, mitä teidän tulee sanoa.","Sillä Pyhä Henki opettaa teitä sillä hetkellä, mitä teidän tulee sanoa."],[12,13,"Niin sanoi hänelle yksi kansasta: Mestari, sanos minun veljelleni, että hän jakais minun kanssani perinnön.","Niin sanoi hänelle yksi kansasta: Mestari, sanos minun veljelleni, että hän jakais minun kanssani perinnön."],[12,14,"Mutta hän sanoi hänelle: ihminen, kuka pani minun tuomariksi eli jakomieheksi teidän välillänne?","Mutta hän sanoi hänelle: ihminen, kuka pani minun tuomariksi eli jakomieheksi teidän välillänne?"],[12,15,"Ja hän sanoi heille: katsokaat ja kavahtakaat ahneutta; sillä ei jonkun elämä siinä seiso, että hänellä paljo kalua on.","Ja hän sanoi heille: katsokaat ja kavahtakaat ahneutta; sillä ei jonkun elämä siinä seiso, että hänellä paljo kalua on."],[12,16,"Niin hän sanoi heille vertauksen, sanoen: yhden rikkaan miehen maa kasvoi hyvin.","Niin hän sanoi heille vertauksen, sanoen: yhden rikkaan miehen maa kasvoi hyvin."],[12,17,"Ja hän ajatteli itsellänsä ja sanoi: mitä minä teen, ettei minulla ole, kuhunka minä kokoon eloni?","Ja hän ajatteli itsellänsä ja sanoi: mitä minä teen, ettei minulla ole, kuhunka minä kokoon eloni?"],[12,18,"Ja sanoi: sen minä teen: minä maahan jaotan aittani, ja rakennan suuremmat, ja kokoon sinne kaiken tuloni ja hyvyyteni,","Ja sanoi: sen minä teen: minä maahan jaotan aittani, ja rakennan suuremmat, ja kokoon sinne kaiken tuloni ja hyvyyteni,"],[12,19,"Ja sanon sielulleni: sielu, sinulla on pantu paljo hyvyyttä moneksi vuodeksi: lepää, syö, juo, riemuitse.","Ja sanon sielulleni: sielu, sinulla on pantu paljo hyvyyttä moneksi vuodeksi: lepää, syö, juo, riemuitse."],[12,20,"Mutta Jumala sanoi hänelle: sinä tyhmä! tänä yönä sinun sielus sinulta pois otetaan: kuka ne sitte saa, joita sinä valmistanut olet?","Mutta Jumala sanoi hänelle: sinä tyhmä! tänä yönä sinun sielus sinulta pois otetaan: kuka ne sitte saa, joita sinä valmistanut olet?"],[12,21,"Niin on myös se, joka itsellensä tavaraa kokoo, ja ei ole rikas Jumalassa.","Niin on myös se, joka itsellensä tavaraa kokoo, ja ei ole rikas Jumalassa."],[12,22,"Niin hän sanoi opetuslapsillensa: sentähden sanon minä teille: älkäät murehtiko elämästänne, mitä teidän pitä syömän, eikä ruumiistanne, millä te itseänne verhoitatte.","Niin hän sanoi opetuslapsillensa: sentähden sanon minä teille: älkäät murehtiko elämästänne, mitä teidän pitä syömän, eikä ruumiistanne, millä te itseänne verhoitatte."],[12,23,"Henki on enempi kuin ruoka, ja ruumis parempi kuin vaate.","Henki on enempi kuin ruoka, ja ruumis parempi kuin vaate."],[12,24,"Katselkaat kaarneita: ei he kylvä eikä niitä, ei heillä ole myös kellaria eikä aittaa, ja Jumala elättää heidät: kuinka paljoa paremmat te olette kuin linnut?","Katselkaat kaarneita: ei he kylvä eikä niitä, ei heillä ole myös kellaria eikä aittaa, ja Jumala elättää heidät: kuinka paljoa paremmat te olette kuin linnut?"],[12,25,"Mutta kuka teistä murheellansa voi lisätä varrellensa yhden kyynärän?","Mutta kuka teistä murheellansa voi lisätä varrellensa yhden kyynärän?"],[12,26,"Sentähden ellette siis voi sitä, mikä vähin on, miksi te muista murehditte?","Sentähden ellette siis voi sitä, mikä vähin on, miksi te muista murehditte?"],[12,27,"Katselkaat kukkasia, kuinka ne kasvavat: ei he työtä tee, eikä kehrää; ja minä sanon teille: ei Salomo kaikessa kunniassansa niin ollut vaatetettu kuin yksi heistä.","Katselkaat kukkasia, kuinka ne kasvavat: ei he työtä tee, eikä kehrää; ja minä sanon teille: ei Salomo kaikessa kunniassansa niin ollut vaatetettu kuin yksi heistä."],[12,28,"Jos siis ruohon, joka tänäpänä kedolla seisoo jo huomenna pätsiin heitetään, Jumala niin vaatettaa, eikö hän paljoa enemmin teidän sitä te, te vähäuskoiset?","Jos siis ruohon, joka tänäpänä kedolla seisoo jo huomenna pätsiin heitetään, Jumala niin vaatettaa, eikö hän paljoa enemmin teidän sitä te, te vähäuskoiset?"],[12,29,"Sentähden, älkäät etsikö, mitä teidän syömän eli juoman pitää, ja älkäät surulliset olko.","Sentähden, älkäät etsikö, mitä teidän syömän eli juoman pitää, ja älkäät surulliset olko."],[12,30,"Sillä näitä kaikkia pakanat maailmassa pyytävät; mutta teidän Isänne tietää, että te näitä tarvitsette.","Sillä näitä kaikkia pakanat maailmassa pyytävät; mutta teidän Isänne tietää, että te näitä tarvitsette."],[12,31,"Vaan paremmin etsikäät Jumalan valtakuntaa, niin nämät kaikki teille annetaan.","Vaan paremmin etsikäät Jumalan valtakuntaa, niin nämät kaikki teille annetaan."],[12,32,"Älä pelkää, piskuinen lauma; sillä teidän Isällänne on hyvä tahto antaa teille valtakunnan.","Älä pelkää, piskuinen lauma; sillä teidän Isällänne on hyvä tahto antaa teille valtakunnan."],[12,33,"Myykäät, mitä teillä on, ja antakaat almua. Tehkäät teillenne säkit, jotka ei vanhene, puuttumatoin tavara taivaissa, kuhunka ei varas ulotu, ja kussa ei koi raiskaa.","Myykäät, mitä teillä on, ja antakaat almua. Tehkäät teillenne säkit, jotka ei vanhene, puuttumatoin tavara taivaissa, kuhunka ei varas ulotu, ja kussa ei koi raiskaa."],[12,34,"Sillä kussa teidän tavaranne on, siellä on myös teidän sydämenne.","Sillä kussa teidän tavaranne on, siellä on myös teidän sydämenne."],[12,35,"Olkoon teidän kupeenne vyötetyt ja teidän kynttilänne sytytetyt.","Olkoon teidän kupeenne vyötetyt ja teidän kynttilänne sytytetyt."],[12,36,"Ja olkaat te niiden ihmisten kaltaiset, jotka odottavat Herraansa häistä palajavan: että kuin hän tulee ja kolkuttaa, niin he hänelle avaavat.","Ja olkaat te niiden ihmisten kaltaiset, jotka odottavat Herraansa häistä palajavan: että kuin hän tulee ja kolkuttaa, niin he hänelle avaavat."],[12,37,"Autuaat ovat ne palveliat, jotka Herra tultuansa löytää valvomasta. Totisesti sanon minä teille: hän sonnustaa itsensä ja asettaa heidät aterioitsemaan, ja tulee ja palvelee heitä.","Autuaat ovat ne palveliat, jotka Herra tultuansa löytää valvomasta. Totisesti sanon minä teille: hän sonnustaa itsensä ja asettaa heidät aterioitsemaan, ja tulee ja palvelee heitä."],[12,38,"Ja jos hän tulee toisessa vartiossa, eli kolmannessa vartiossa tulee, ja näin löytää, autuaat ovat ne palvelia.","Ja jos hän tulee toisessa vartiossa, eli kolmannessa vartiossa tulee, ja näin löytää, autuaat ovat ne palvelia."],[12,39,"Mutta se tietäkäät, että jos perheen-isäntä tietäis, millä hetkellä varas on tuleva, tosin hän valvois eikä sallisi huonettansa kaivettaa.","Mutta se tietäkäät, että jos perheen-isäntä tietäis, millä hetkellä varas on tuleva, tosin hän valvois eikä sallisi huonettansa kaivettaa."],[12,40,"Sentähden olkaat te myös valmiit: sillä, millä hetkellä ette luulekaan, tulee Ihmisen Poika.","Sentähden olkaat te myös valmiit: sillä, millä hetkellä ette luulekaan, tulee Ihmisen Poika."],[12,41,"Niin sanoi Pietari hänelle: Herra, sanotkos tämän vertauksen meille, eli myös kaikille?","Niin sanoi Pietari hänelle: Herra, sanotkos tämän vertauksen meille, eli myös kaikille?"],[12,42,"Mutta Herra sanoi: kuka on uskollinen ja toimellinen perheenhaltia, jonka Herra asettaa perheensä päälle, oikialla ajalla määrättyä osaa antamaan.","Mutta Herra sanoi: kuka on uskollinen ja toimellinen perheenhaltia, jonka Herra asettaa perheensä päälle, oikialla ajalla määrättyä osaa antamaan."],[12,43,"Autuas on se palvelia, jonka Herra tultuansa niin löytää tehneen.","Autuas on se palvelia, jonka Herra tultuansa niin löytää tehneen."],[12,44,"Totisesti sanon minä teille: hän asettaa hänen kaiken tavaransa päälle.","Totisesti sanon minä teille: hän asettaa hänen kaiken tavaransa päälle."],[12,45,"Mutta jos palvelia sanoo sydämessänsä: minun Herrani viipyy tulemasta, ja rupee palkollisia hosumaan, ja syömään ja juomaan ja juopumaan,","Mutta jos palvelia sanoo sydämessänsä: minun Herrani viipyy tulemasta, ja rupee palkollisia hosumaan, ja syömään ja juomaan ja juopumaan,"],[12,46,"Niin tulee palvelian herra sinä päivänä, jona ei hän luulekaan, ja sillä hetkellä, jota ei hän tiedä, ja eroittaa hänen, ja antaa hänelle osan uskottomain kanssa.","Niin tulee palvelian herra sinä päivänä, jona ei hän luulekaan, ja sillä hetkellä, jota ei hän tiedä, ja eroittaa hänen, ja antaa hänelle osan uskottomain kanssa."],[12,47,"Mutta sen palvelian, joka tiesi Herransa tahdon, ja ei itsiänsä valmistanut eikä tehnyt hänen tahtonsa jälkeen, täytyy paljon haavoja kärsiä.","Mutta sen palvelian, joka tiesi Herransa tahdon, ja ei itsiänsä valmistanut eikä tehnyt hänen tahtonsa jälkeen, täytyy paljon haavoja kärsiä."],[12,48,"Joka taas ei tietänyt, ja kuitenkin teki haavain ansion, sen pitää vähemmän haavoja kärsimän; sillä kenelle paljo annettu on, siltä paljon etsitään, ja jonka haltuun paljo on annettu, sitä enempi anotaan.","Joka taas ei tietänyt, ja kuitenkin teki haavain ansion, sen pitää vähemmän haavoja kärsimän; sillä kenelle paljo annettu on, siltä paljon etsitään, ja jonka haltuun paljo on annettu, sitä enempi anotaan."],[12,49,"Minä tuli sytyttämään tulta maan päälle, ja mitä minä tahdon, vaan että se jo palais?","Minä tuli sytyttämään tulta maan päälle, ja mitä minä tahdon, vaan että se jo palais?"],[12,50,"Mutta minun pitää kasteella kastettaman, ja kuinka minä ahdistetaan siihenasti että se täytetään?","Mutta minun pitää kasteella kastettaman, ja kuinka minä ahdistetaan siihenasti että se täytetään?"],[12,51,"Luuletteko, että minä tulin rauhaa lähettämään maan päälle? En, sanon minä teille, vaan eripuraisuutta.","Luuletteko, että minä tulin rauhaa lähettämään maan päälle? En, sanon minä teille, vaan eripuraisuutta."],[12,52,"Sillä tästedes pitää viisi oleman eroitetut yhdessä huoneessa, kolme kahta vastaan ja kaksi kolmea vastaan.","Sillä tästedes pitää viisi oleman eroitetut yhdessä huoneessa, kolme kahta vastaan ja kaksi kolmea vastaan."],[12,53,"Isä eroitetaan poikaansa vastaan ja poika isää vastaan, äiti tytärtä vastaan ja tytär äitiä vastaan, anoppi miniäänsä vastaan, miniä anoppiansa vastaan.","Isä eroitetaan poikaansa vastaan ja poika isää vastaan, äiti tytärtä vastaan ja tytär äitiä vastaan, anoppi miniäänsä vastaan, miniä anoppiansa vastaan."],[12,54,"Niin hän sanoi myös kansalle: kuin te näette pilven lännestä nousevan, niin te kohta sanotte: sade tulee; niin myös tuleekin.","Niin hän sanoi myös kansalle: kuin te näette pilven lännestä nousevan, niin te kohta sanotte: sade tulee; niin myös tuleekin."],[12,55,"Ja kuin te näette etelän tuulevan, niin te sanotte: helle tulee; niin myös tuleekin.","Ja kuin te näette etelän tuulevan, niin te sanotte: helle tulee; niin myös tuleekin."],[12,56,"Te ulkokullatut, maan ja taivaan muodon te taidatte koetella, miksi ette siis tätä aikaa koettele?","Te ulkokullatut, maan ja taivaan muodon te taidatte koetella, miksi ette siis tätä aikaa koettele?"],[12,57,"Minkätähden siis ette myös itsestänne tuomitse, mikä oikia on?","Minkätähden siis ette myös itsestänne tuomitse, mikä oikia on?"],[12,58,"Sillä kuin sinä menet riitaveljes kanssa esivallan eteen, niin pyydä tiellä hänestä päästä; ettei hän sinua tuomarin eteen vetäisi, ja tuomari antais sinua ylön pyövelille, ja pyöveli heittäis sinun torniin.","Sillä kuin sinä menet riitaveljes kanssa esivallan eteen, niin pyydä tiellä hänestä päästä; ettei hän sinua tuomarin eteen vetäisi, ja tuomari antais sinua ylön pyövelille, ja pyöveli heittäis sinun torniin."],[12,59,"Minä sanon sinulle: et sinä sieltä ennen pääse ulos, kuin sinä viimeisen rovon maksat.","Minä sanon sinulle: et sinä sieltä ennen pääse ulos, kuin sinä viimeisen rovon maksat."],[13,1,"Ja olivat muutamat sillä ajalla siinä, jotka ilmoittivat hänelle Galilealaisista, joiden veren Pilatus oli heidän uhriensa kanssa sekoittanut.","Ja olivat muutamat sillä ajalla siinä, jotka ilmoittivat hänelle Galilealaisista, joiden veren Pilatus oli heidän uhriensa kanssa sekoittanut."],[13,2,"Ja Jesus vastasi ja sanoi heille: luuletteko, että nämät Galilealaiset olivat syntiset kaikkein Galilealaisten suhteen, että heidän senkaltaista täytyi kärsiä?","Ja Jesus vastasi ja sanoi heille: luuletteko, että nämät Galilealaiset olivat syntiset kaikkein Galilealaisten suhteen, että heidän senkaltaista täytyi kärsiä?"],[13,3,"Ei suinkaan, sanon minä teille, vaan ellette paranna teitänne, niin te kaikki niin hukkaan tulette.","Ei suinkaan, sanon minä teille, vaan ellette paranna teitänne, niin te kaikki niin hukkaan tulette."],[13,4,"Taikka luuletteko, että ne kahdeksantoistakymmentä, joiden päälle Siloan torni lankesi ja tappoi heidät, olivat vialliset kaikkein ihmisten suhteen, jotka Jerusalemissa asuvat?","Taikka luuletteko, että ne kahdeksantoistakymmentä, joiden päälle Siloan torni lankesi ja tappoi heidät, olivat vialliset kaikkein ihmisten suhteen, jotka Jerusalemissa asuvat?"],[13,5,"Ei suinkaan, sanon minä teille, vaan ellette paranna teitänne, niin te kaikki niin hukkaan tulette.","Ei suinkaan, sanon minä teille, vaan ellette paranna teitänne, niin te kaikki niin hukkaan tulette."],[13,6,"Mutta hän sanoi tämän vertauksen: yhdellä oli fikunapuu, hänen viinamäessänsä istutettu, ja hän tuli etsein hedelmää hänestä ja ei löytänyt.","Mutta hän sanoi tämän vertauksen: yhdellä oli fikunapuu, hänen viinamäessänsä istutettu, ja hän tuli etsein hedelmää hänestä ja ei löytänyt."],[13,7,"Niin hän sanoi viinamäen rakentajalle: katso, minä olen kolme vuotta tullut ja etsinyt hedelmää tästä fikunapuusta, ja en löydä, hakkaa se pois: miksi se myös maata turmelee?","Niin hän sanoi viinamäen rakentajalle: katso, minä olen kolme vuotta tullut ja etsinyt hedelmää tästä fikunapuusta, ja en löydä, hakkaa se pois: miksi se myös maata turmelee?"],[13,8,"Mutta hän vastasi ja sanoi hänelle: herra, anna hänen vielä tämä vuosi olla, niin kauvan kuin minä kaivan hänen ympärinsä ja sonnitan:","Mutta hän vastasi ja sanoi hänelle: herra, anna hänen vielä tämä vuosi olla, niin kauvan kuin minä kaivan hänen ympärinsä ja sonnitan:"],[13,9,"Jos hän sittekin hedelmän tekis; jollei, niin hakkaa se sitte pois.","Jos hän sittekin hedelmän tekis; jollei, niin hakkaa se sitte pois."],[13,10,"Mutta hän opetti sabbatina yhdessä synagogassa,","Mutta hän opetti sabbatina yhdessä synagogassa,"],[13,11,"Ja katso, siellä oli vaimo, jolla oli sairauden henki kahdeksantoistakymmentä vuotta ollu, ja kävi kumarruksissa, eikä voinut ikänä itsiänsä ojentaa.","Ja katso, siellä oli vaimo, jolla oli sairauden henki kahdeksantoistakymmentä vuotta ollu, ja kävi kumarruksissa, eikä voinut ikänä itsiänsä ojentaa."],[13,12,"Mutta kuin Jesus sen näki, kutsui hän hänen tykönsä ja sanoi hänelle: vaimo, sinä olet päässyt taudistas.","Mutta kuin Jesus sen näki, kutsui hän hänen tykönsä ja sanoi hänelle: vaimo, sinä olet päässyt taudistas."],[13,13,"Ja hän pani kätensä hänen päällensä, ja kohta se ojensi ylös itsensä ja kiitti Jumalaa.","Ja hän pani kätensä hänen päällensä, ja kohta se ojensi ylös itsensä ja kiitti Jumalaa."],[13,14,"Niin vastasi synagogan päämies ja närkästyi, että Jesus paransi sabbatina, ja sanoi kansalle: kuusi päivää ovat, joina sopii työtä tehdä; niinä te tulkaat ja antakaat teitä parantaa, ja ei sabbatin päivänä.","Niin vastasi synagogan päämies ja närkästyi, että Jesus paransi sabbatina, ja sanoi kansalle: kuusi päivää ovat, joina sopii työtä tehdä; niinä te tulkaat ja antakaat teitä parantaa, ja ei sabbatin päivänä."],[13,15,"Niin vastasi häntä Herra ja sanoi: sinä ulkokullattu! eikö kukin teistä päästä nautaansa eli aasiansa sabbatina seimestä ja johdata juomaan?","Niin vastasi häntä Herra ja sanoi: sinä ulkokullattu! eikö kukin teistä päästä nautaansa eli aasiansa sabbatina seimestä ja johdata juomaan?"],[13,16,"Eikö myös tämä Abrahamin tytär pitäisi sabbatina päästettämän tästä siteestä, jonka, katso, saatana on kahdeksantoistakymmentä vuotta sitonut?","Eikö myös tämä Abrahamin tytär pitäisi sabbatina päästettämän tästä siteestä, jonka, katso, saatana on kahdeksantoistakymmentä vuotta sitonut?"],[13,17,"Ja kuin hän näitä sanoi, niin häpesivät kaikki, jotka häntä vastaan olivat. Ja kaikki kansa iloitsi kaikista kunniallisista töistä, joita häneltä tehtiin.","Ja kuin hän näitä sanoi, niin häpesivät kaikki, jotka häntä vastaan olivat. Ja kaikki kansa iloitsi kaikista kunniallisista töistä, joita häneltä tehtiin."],[13,18,"Niin hän sanoi: kenenkä vertainen on Jumalan valtakunta, ja kenenkä kaltaiseksi minä sen teen?","Niin hän sanoi: kenenkä vertainen on Jumalan valtakunta, ja kenenkä kaltaiseksi minä sen teen?"],[13,19,"Se on sinapin siemenen vertainen, jonka ihminen otti ja kylvi yrttitarhaansa; ja se kasvoi ja tuli suureksi puuksi ja taivaan linnut tekivät pesänsä sen oksille.","Se on sinapin siemenen vertainen, jonka ihminen otti ja kylvi yrttitarhaansa; ja se kasvoi ja tuli suureksi puuksi ja taivaan linnut tekivät pesänsä sen oksille."],[13,20,"Ja hän taas sanoi: kenenkä vertaiseksi minä Jumalan valtakunnan teen?","Ja hän taas sanoi: kenenkä vertaiseksi minä Jumalan valtakunnan teen?"],[13,21,"Se on hapatuksen kaltainen, jonka vaimo otti, ja pani sen kolmeen jauhovakkaan, siihenasti kuin se kaikki happani.","Se on hapatuksen kaltainen, jonka vaimo otti, ja pani sen kolmeen jauhovakkaan, siihenasti kuin se kaikki happani."],[13,22,"Ja hän vaelsi kaupunkien ja kyläin kautta opettain, ja matkusti Jerusalemia päin.","Ja hän vaelsi kaupunkien ja kyläin kautta opettain, ja matkusti Jerusalemia päin."],[13,23,"Niin sanoi yksi hänelle: Herra, vähäkö niitä on, jotka autuaaksi tulevat? Ja hän sanoi heille:","Niin sanoi yksi hänelle: Herra, vähäkö niitä on, jotka autuaaksi tulevat? Ja hän sanoi heille:"],[13,24,"Pyytäkäät ahtaasta portista mennä sisälle, sillä monta on, sanon minä teille, jotka pyytävät mennä sisälle, ja ei taida.","Pyytäkäät ahtaasta portista mennä sisälle, sillä monta on, sanon minä teille, jotka pyytävät mennä sisälle, ja ei taida."],[13,25,"Kuin perheenisäntä on noussut ja oven sulkenut, ja te rupeette ulkona seisomaan ja oven päälle kolkuttamaan ja sanomaan: Herra, Herra, avaa meille! ja hän vastaa ja sanoo teille: en minä teitä tunne, kusta te olette;","Kuin perheenisäntä on noussut ja oven sulkenut, ja te rupeette ulkona seisomaan ja oven päälle kolkuttamaan ja sanomaan: Herra, Herra, avaa meille! ja hän vastaa ja sanoo teille: en minä teitä tunne, kusta te olette;"],[13,26,"Niin te rupeette sanomaan: me olemme syöneet ja juoneet sinun edessäs, ja meidän kaduillamme sinä opetit.","Niin te rupeette sanomaan: me olemme syöneet ja juoneet sinun edessäs, ja meidän kaduillamme sinä opetit."],[13,27,"Ja hän on sanova: minä sanon teille: en minä teitä tunne, kusta te olette; menkäät pois minun tyköäni, kaikki te väärintekiät.","Ja hän on sanova: minä sanon teille: en minä teitä tunne, kusta te olette; menkäät pois minun tyköäni, kaikki te väärintekiät."],[13,28,"Siellä pitää oleman itku ja hammasten kiristys, kuin te näette Abrahamin ja Isaakin ja Jakobin ja kaikki prophetat Jumalan valtakunnassa, mutta itsenne ajettavan ulos.","Siellä pitää oleman itku ja hammasten kiristys, kuin te näette Abrahamin ja Isaakin ja Jakobin ja kaikki prophetat Jumalan valtakunnassa, mutta itsenne ajettavan ulos."],[13,29,"Ja heidän pitää tuleman idästä ja lännestä, pohjoisesta ja etelästä, ja Jumalan valtakunnassa istuman.","Ja heidän pitää tuleman idästä ja lännestä, pohjoisesta ja etelästä, ja Jumalan valtakunnassa istuman."],[13,30,"Ja katso, ne ovat viimeiset, jotka tulevat ensimäisiksi, ja ne ovat ensimäiset, jotka tulevat viimeisiksi.","Ja katso, ne ovat viimeiset, jotka tulevat ensimäisiksi, ja ne ovat ensimäiset, jotka tulevat viimeisiksi."],[13,31,"Sinä päivänä tulivat muutamat Pharisealaiset ja sanoivat hänelle: lähde ulos ja mene täältä pois; sillä Herodes tahtoo sinua tappaa.","Sinä päivänä tulivat muutamat Pharisealaiset ja sanoivat hänelle: lähde ulos ja mene täältä pois; sillä Herodes tahtoo sinua tappaa."],[13,32,"Ja hän sanoi heille: menkäät ja sanokaat sille ketulle: katso, minä ajan ulos perkeleitä, ja parannan tänäpänä ja huomenna, ja kolmantena päivänä minä lopetetaan.","Ja hän sanoi heille: menkäät ja sanokaat sille ketulle: katso, minä ajan ulos perkeleitä, ja parannan tänäpänä ja huomenna, ja kolmantena päivänä minä lopetetaan."],[13,33,"Kuitenkin pitää minun tänäpänä ja huomenna ja toisena huomenna vaeltaman; sillä ei tapahdu, että propheta muualla hukataan kuin Jerusalemissa.","Kuitenkin pitää minun tänäpänä ja huomenna ja toisena huomenna vaeltaman; sillä ei tapahdu, että propheta muualla hukataan kuin Jerusalemissa."],[13,34,"Jerusalem, Jerusalem, joka tapat prophetat ja kivität niitä, jotka sinun tykös lähetetään, kuinka usein minä tahdoin koota sinun lapses, niinkuin kana kokoo poikansa siipiensä alle, ja ette tahtoneet?","Jerusalem, Jerusalem, joka tapat prophetat ja kivität niitä, jotka sinun tykös lähetetään, kuinka usein minä tahdoin koota sinun lapses, niinkuin kana kokoo poikansa siipiensä alle, ja ette tahtoneet?"],[13,35,"Katso, teidän huoneenne jätetään teille kylmille. Totisesti sanon minä teille: ei teidän pidä minua näkemän, siihenasti kuin se aika tulee, jona te sanotte: siunattu olkoon se, joka tulee Herran nimeen!","Katso, teidän huoneenne jätetään teille kylmille. Totisesti sanon minä teille: ei teidän pidä minua näkemän, siihenasti kuin se aika tulee, jona te sanotte: siunattu olkoon se, joka tulee Herran nimeen!"],[14,1,"Ja tapahtui, että hän tuli yhden Pharisealaisten päämiehen huoneesen sabbatina rualle, ja he vartioitsivat häntä.","Ja tapahtui, että hän tuli yhden Pharisealaisten päämiehen huoneesen sabbatina rualle, ja he vartioitsivat häntä."],[14,2,"Ja katso, siinä oli vesitautinen ihminen hänen edessänsä.","Ja katso, siinä oli vesitautinen ihminen hänen edessänsä."],[14,3,"Niin Jesus vastaten sanoi lainoppineille ja Pharisealaisille: sopiiko sabbatina parantaa? Niin he vaikenivat.","Niin Jesus vastaten sanoi lainoppineille ja Pharisealaisille: sopiiko sabbatina parantaa? Niin he vaikenivat."],[14,4,"Mutta hän rupesi häneen, ja paransi hänen, ja pääsi menemään.","Mutta hän rupesi häneen, ja paransi hänen, ja pääsi menemään."],[14,5,"Ja hän vastaten sanoi heille: kenenkä teistä nauta eli aasi putoo kaivoon, eikö hän kohta sabbatin päivänä häntä ota ylös?","Ja hän vastaten sanoi heille: kenenkä teistä nauta eli aasi putoo kaivoon, eikö hän kohta sabbatin päivänä häntä ota ylös?"],[14,6,"Ja ei he taitaneet häntä tähän vastata.","Ja ei he taitaneet häntä tähän vastata."],[14,7,"Mutta hän sanoi vieraille vertauksen, koska hän ymmärsi, kuinka he valitsivat ylimmäisiä istuimia, sanoen heille:","Mutta hän sanoi vieraille vertauksen, koska hän ymmärsi, kuinka he valitsivat ylimmäisiä istuimia, sanoen heille:"],[14,8,"Kuinka joltakulta häihin kutsuttu olet, niin älä istu ylimmäiseen siaan, ettei joku kunniallisempi sinua ole häneltä kutsuttu,","Kuinka joltakulta häihin kutsuttu olet, niin älä istu ylimmäiseen siaan, ettei joku kunniallisempi sinua ole häneltä kutsuttu,"],[14,9,"Ja tulee se, joka sinun ja hänen on kutsunut, ja sanoo sinulle: anna tälle siaa! ja niin sinä häpiällä menet alemma istumaan.","Ja tulee se, joka sinun ja hänen on kutsunut, ja sanoo sinulle: anna tälle siaa! ja niin sinä häpiällä menet alemma istumaan."],[14,10,"Mutta kuin kutsuttu olet, niin mene ja istu alemmaiseen siaan, että se, joka sinun kutsunut on, tulis ja sanois sinulle: ystäväni, nouse ylemmä; silloin on sinulle kunnia niiden edessä, jotka ynnä kanssas atrioitsevat.","Mutta kuin kutsuttu olet, niin mene ja istu alemmaiseen siaan, että se, joka sinun kutsunut on, tulis ja sanois sinulle: ystäväni, nouse ylemmä; silloin on sinulle kunnia niiden edessä, jotka ynnä kanssas atrioitsevat."],[14,11,"Sillä jokainen, joka itsensä ylentää, se alennetaan, ja joka itsensä alentaa, se ylennetään.","Sillä jokainen, joka itsensä ylentää, se alennetaan, ja joka itsensä alentaa, se ylennetään."],[14,12,"Mutta hän sanoi myös sille, joka hänen kutsunut oli: kuin päivällistä tai ehtoollista teet, niin älä kutsu ystäviäs, eli veljiäs, ei lankojas, taikka rikkaita kylänmiehiäs: ettei he joskus sinua myös jälleen kutsu, ja sinulle maksa.","Mutta hän sanoi myös sille, joka hänen kutsunut oli: kuin päivällistä tai ehtoollista teet, niin älä kutsu ystäviäs, eli veljiäs, ei lankojas, taikka rikkaita kylänmiehiäs: ettei he joskus sinua myös jälleen kutsu, ja sinulle maksa."],[14,13,"Mutta kuin pidot teet, niin kutsut köyhiä, raajarikkoja, ontuvia, sokeita:","Mutta kuin pidot teet, niin kutsut köyhiä, raajarikkoja, ontuvia, sokeita:"],[14,14,"Niin sinä olet autua; sillä ei heillä ole varaa sinulle maksaa, sillä sinulle pitää maksettaman vanhurskasten ylösnousemisessa.","Niin sinä olet autua; sillä ei heillä ole varaa sinulle maksaa, sillä sinulle pitää maksettaman vanhurskasten ylösnousemisessa."],[14,15,"Mutta kuin yksi ynnä atrioitsevista nämät kuuli, sanoi hän hänelle: autuas on se, joka syö leipää Jumalan valtakunnassa.","Mutta kuin yksi ynnä atrioitsevista nämät kuuli, sanoi hän hänelle: autuas on se, joka syö leipää Jumalan valtakunnassa."],[14,16,"Niin hän sanoi hänelle: yksi ihminen teki suuren ehtoollisen ja kutsui monta,","Niin hän sanoi hänelle: yksi ihminen teki suuren ehtoollisen ja kutsui monta,"],[14,17,"Ja lähetti palveliansa ehtoollisen hetkellä sanomaan kutsutuille: tulkaat, sillä kaikki ovat valmistetut.","Ja lähetti palveliansa ehtoollisen hetkellä sanomaan kutsutuille: tulkaat, sillä kaikki ovat valmistetut."],[14,18,"Ja he rupesivat järjestänsä kaikki itseänsä estelemään: ensimäinen sanoi hänelle: minä ostin pellon, ja minun pitää menemän sitä katsomaan: minä rukoilen sinua, sano minun esteeni.","Ja he rupesivat järjestänsä kaikki itseänsä estelemään: ensimäinen sanoi hänelle: minä ostin pellon, ja minun pitää menemän sitä katsomaan: minä rukoilen sinua, sano minun esteeni."],[14,19,"Ja toinen sanoi: minä ostin viisi paria härkiä, ja menen niitä koettelemaan: minä rukoilen sinua, sano minun esteeni.","Ja toinen sanoi: minä ostin viisi paria härkiä, ja menen niitä koettelemaan: minä rukoilen sinua, sano minun esteeni."],[14,20,"Ja kolmas sanoi: minä olen emännän nainut, ja en taida sentähden tulla.","Ja kolmas sanoi: minä olen emännän nainut, ja en taida sentähden tulla."],[14,21,"Ja kuin se palvelia tuli, sanoi hän nämät herrallensa. Silloin perheenisäntä vihastui ja sanoi palveliallensa: mene nopiasti kaupungin kaduille ja kujille ja saata tänne vaivaiset ja raajarikot, ontuvat ja sokiat.","Ja kuin se palvelia tuli, sanoi hän nämät herrallensa. Silloin perheenisäntä vihastui ja sanoi palveliallensa: mene nopiasti kaupungin kaduille ja kujille ja saata tänne vaivaiset ja raajarikot, ontuvat ja sokiat."],[14,22,"Ja palvelia sanoi: herra, minä olen tehnyt niinkuin sinä käskit, ja vielä nyt siaa on.","Ja palvelia sanoi: herra, minä olen tehnyt niinkuin sinä käskit, ja vielä nyt siaa on."],[14,23,"Ja herra sanoi palvelialle: men maanteille ja aidoille, ja vaadi heitä sisälle tulemaan, että minun huoneeni täytettäisiin.","Ja herra sanoi palvelialle: men maanteille ja aidoille, ja vaadi heitä sisälle tulemaan, että minun huoneeni täytettäisiin."],[14,24,"Sillä minä sanon teille, ettei yksikään niistä miehistä, jotka kutsuttiin, pidä maistaman minun ehtoollistani.","Sillä minä sanon teille, ettei yksikään niistä miehistä, jotka kutsuttiin, pidä maistaman minun ehtoollistani."],[14,25,"Niin vaelsi paljo väkeä hänen kanssansa, ja hän kääntyi ja sanoi heille:","Niin vaelsi paljo väkeä hänen kanssansa, ja hän kääntyi ja sanoi heille:"],[14,26,"Jos joku tulee minun tyköni, ja ei vihaa isäänsä ja äitiänsä, ja emäntäänsä ja lapsiansa, ja veljiänsä ja sisariansa, ja päälliseksi omaa henkeänsä, ei se taida olla minun opetuslapseni.","Jos joku tulee minun tyköni, ja ei vihaa isäänsä ja äitiänsä, ja emäntäänsä ja lapsiansa, ja veljiänsä ja sisariansa, ja päälliseksi omaa henkeänsä, ei se taida olla minun opetuslapseni."],[14,27,"Ja joka ei kanna ristiänsä ja seuraa minua, ei se taida olla minun opetuslapseni.","Ja joka ei kanna ristiänsä ja seuraa minua, ei se taida olla minun opetuslapseni."],[14,28,"Sillä kuka teistä on, joka tahtoo tornia rakentaa; eikö hän ennen istu ja laske kulutusta, jos hänellä on varaa sitä täyttää?","Sillä kuka teistä on, joka tahtoo tornia rakentaa; eikö hän ennen istu ja laske kulutusta, jos hänellä on varaa sitä täyttää?"],[14,29,"Ettei, kuin hän perustuksen laskenut on, ja ei voi sitä täyttää, kaikki, jotka sen näkevät, rupee pilkkaamaan häntä,","Ettei, kuin hän perustuksen laskenut on, ja ei voi sitä täyttää, kaikki, jotka sen näkevät, rupee pilkkaamaan häntä,"],[14,30,"Sanoen: tämä ihminen rupesi rakentamaan, ja ei voinut täyttää.","Sanoen: tämä ihminen rupesi rakentamaan, ja ei voinut täyttää."],[14,31,"Taikka kuka kuningas tahtoo mennä sotimaan toista kuningasta vastaan; eikö hän ennen istu ja ajattele, jos hän voi kymmenellä tuhannella kohdata sen, joka häntä vastaan tulee kahdellakymmenellä tuhannella?","Taikka kuka kuningas tahtoo mennä sotimaan toista kuningasta vastaan; eikö hän ennen istu ja ajattele, jos hän voi kymmenellä tuhannella kohdata sen, joka häntä vastaan tulee kahdellakymmenellä tuhannella?"],[14,32,"Muutoin, kuin hän vielä kaukana on, niin hän lähettää hänelle sanan ja rukoilee rauhaa.","Muutoin, kuin hän vielä kaukana on, niin hän lähettää hänelle sanan ja rukoilee rauhaa."],[14,33,"Niin siis jokainen teistä, joka ei luovu kaikista mitä hänellä on, ei se taida olla minun opetuslapseni.","Niin siis jokainen teistä, joka ei luovu kaikista mitä hänellä on, ei se taida olla minun opetuslapseni."],[14,34,"Suola on hyvä; mutta jos suola tulee mauttomaksi, milläs sitte suolataan?","Suola on hyvä; mutta jos suola tulee mauttomaksi, milläs sitte suolataan?"],[14,35,"Ei se maahan eikä sontaan ole sovelias: he heittävät sen pois. Jolla on korvat kuulla, se kuulkaan.","Ei se maahan eikä sontaan ole sovelias: he heittävät sen pois. Jolla on korvat kuulla, se kuulkaan."],[15,1,"Mutta hänen tykönsä tulivat kaikki Publikanit ja syntiset, kuulemaan häntä.","Mutta hänen tykönsä tulivat kaikki Publikanit ja syntiset, kuulemaan häntä."],[15,2,"Ja Pharisealaiset ja kirjanoppineet napisivat ja sanoivat: tämä syntisiä vastaan ottaa ja syö heidän kanssansa.","Ja Pharisealaiset ja kirjanoppineet napisivat ja sanoivat: tämä syntisiä vastaan ottaa ja syö heidän kanssansa."],[15,3,"Niin hän sanoi heille tämän vertauksen, sanoen:","Niin hän sanoi heille tämän vertauksen, sanoen:"],[15,4,"Kuka on teistä se ihminen, jolla on sata lammasta, ja jos hän yhden niistä kadottaa, eikö hän jätä yhdeksänkymmentä ja yhdeksän korpeen, ja mene sen jälkeen, joka kadonnut on, siihenasti että hän sen löytää?","Kuka on teistä se ihminen, jolla on sata lammasta, ja jos hän yhden niistä kadottaa, eikö hän jätä yhdeksänkymmentä ja yhdeksän korpeen, ja mene sen jälkeen, joka kadonnut on, siihenasti että hän sen löytää?"],[15,5,"Ja kuin hän sen löytää, niin hän panee sen olallensa, iloiten.","Ja kuin hän sen löytää, niin hän panee sen olallensa, iloiten."],[15,6,"Ja kuin hän tulee kotiansa, niin hän kutsuu kokoon ystävänsä ja kylänsä miehet, ja sanoo heille: iloitkaat minun kanssani: sillä minä löysin lampaani, joka kadonnut oli.","Ja kuin hän tulee kotiansa, niin hän kutsuu kokoon ystävänsä ja kylänsä miehet, ja sanoo heille: iloitkaat minun kanssani: sillä minä löysin lampaani, joka kadonnut oli."],[15,7,"Minä sanon teille: niin pitää ilo oleman taivaassa yhdestä syntisestä, joka itsensä parantaa, enemmin kuin yhdeksästäkymmenestä ja yhdeksästä hurskaasta, jotka ei parannusta tarvitse.","Minä sanon teille: niin pitää ilo oleman taivaassa yhdestä syntisestä, joka itsensä parantaa, enemmin kuin yhdeksästäkymmenestä ja yhdeksästä hurskaasta, jotka ei parannusta tarvitse."],[15,8,"Taikka kuka vaimo on, jolla on kymmenen penninkiä, jos hän yhden niistä kadottaa, eikö hän sytytä kynttilää, ja lakaise huonetta, ja etsi visusti niinkauvan kuin hän sen löytää?","Taikka kuka vaimo on, jolla on kymmenen penninkiä, jos hän yhden niistä kadottaa, eikö hän sytytä kynttilää, ja lakaise huonetta, ja etsi visusti niinkauvan kuin hän sen löytää?"],[15,9,"Ja kuin hän sen löytänyt on, kutsuu hän kokoon ystävänsä ja kylänsä vaimot, ja sanoo: iloitkaat minun kanssani; sillä minä löysin penninkini, jonka minä kadotin.","Ja kuin hän sen löytänyt on, kutsuu hän kokoon ystävänsä ja kylänsä vaimot, ja sanoo: iloitkaat minun kanssani; sillä minä löysin penninkini, jonka minä kadotin."],[15,10,"Niin myös, sanon minä teille, pitää ilo oleman Jumalan enkeleillä yhdestä syntisestä, joka itsensä parantaa.","Niin myös, sanon minä teille, pitää ilo oleman Jumalan enkeleillä yhdestä syntisestä, joka itsensä parantaa."],[15,11,"Ja hän sanoi: yhdellä miehellä oli kaksi poikaa,","Ja hän sanoi: yhdellä miehellä oli kaksi poikaa,"],[15,12,"Ja nuorempi heistä sanoi isällensä: isä, anna minulle osa tavarasta, joka minulle tulee. Ja hän jakoi heille tavaran.","Ja nuorempi heistä sanoi isällensä: isä, anna minulle osa tavarasta, joka minulle tulee. Ja hän jakoi heille tavaran."],[15,13,"Ja ei kauvan sen jälkeen, kuin nuorempi poika oli kaikki koonnut, meni hän kaukaiselle maakunnalle, ja hukkasi siellä tavaransa irstaisuudessa.","Ja ei kauvan sen jälkeen, kuin nuorempi poika oli kaikki koonnut, meni hän kaukaiselle maakunnalle, ja hukkasi siellä tavaransa irstaisuudessa."],[15,14,"Mutta kuin hän kaikki oli tuhlannut, niin tuli suuri nälkä kaikkeen siihen maakuntaan; ja hän rupesi hätääntymään,","Mutta kuin hän kaikki oli tuhlannut, niin tuli suuri nälkä kaikkeen siihen maakuntaan; ja hän rupesi hätääntymään,"],[15,15,"Ja meni pois ja suostui yhteen sen maakunnan kauppamieheen, joka hänen lähetti maakyliinsä kaitsemaan sikojansa.","Ja meni pois ja suostui yhteen sen maakunnan kauppamieheen, joka hänen lähetti maakyliinsä kaitsemaan sikojansa."],[15,16,"Ja hän pyysi vatsaansa ravalla täyttää, jota siat söivät, ja ei kenkään hänelle sitäkään antanut.","Ja hän pyysi vatsaansa ravalla täyttää, jota siat söivät, ja ei kenkään hänelle sitäkään antanut."],[15,17,"Mutta kuin hän mielensä malttoi, sanoi hän: kuinka monella minun isäni palkollisella on kyllä leipää, ja minä kuolen nälkään!","Mutta kuin hän mielensä malttoi, sanoi hän: kuinka monella minun isäni palkollisella on kyllä leipää, ja minä kuolen nälkään!"],[15,18,"Minä nousen ja käyn minun isäni tykö ja sanon hänelle: isä, minä olen syntiä tehnyt taivasta vastaan ja sinun edessäs,","Minä nousen ja käyn minun isäni tykö ja sanon hänelle: isä, minä olen syntiä tehnyt taivasta vastaan ja sinun edessäs,"],[15,19,"Ja en ole silleen mahdollinen sinun pojakses kutsuttaa: tee minua niinkuin yhden palkollisistas.","Ja en ole silleen mahdollinen sinun pojakses kutsuttaa: tee minua niinkuin yhden palkollisistas."],[15,20,"Ja hän nousi ja tuli isänsä tykö. Mutta kuin hän vielä taampana oli, näki hänen isänsä hänen, ja armahti hänen päällensä, ja juosten lankesi hänen kaulaansa, ja suuta antoi hänen.","Ja hän nousi ja tuli isänsä tykö. Mutta kuin hän vielä taampana oli, näki hänen isänsä hänen, ja armahti hänen päällensä, ja juosten lankesi hänen kaulaansa, ja suuta antoi hänen."],[15,21,"Mutta poika sanoi hänelle: isä, minä olen syntiä tehnyt taivasta vastaan ja sinun edessäs, ja en ole mahdollinen tästedes sinun pojakses kutsuttaa.","Mutta poika sanoi hänelle: isä, minä olen syntiä tehnyt taivasta vastaan ja sinun edessäs, ja en ole mahdollinen tästedes sinun pojakses kutsuttaa."],[15,22,"Niin sanoi isä palvelioillensa: tuokaat tänne ne parhaat vaatteet, ja pukekaat hänen yllensä, ja antakaat sormus hänen käteensä, ja kengät hänen jalkoihinsa,","Niin sanoi isä palvelioillensa: tuokaat tänne ne parhaat vaatteet, ja pukekaat hänen yllensä, ja antakaat sormus hänen käteensä, ja kengät hänen jalkoihinsa,"],[15,23,"Ja tuokaat syötetty vasikka, ja tappakaat se, ja syökäämme ja riemuitkaamme;","Ja tuokaat syötetty vasikka, ja tappakaat se, ja syökäämme ja riemuitkaamme;"],[15,24,"Sillä tämä minun poikani oli kuollut, ja virkosi jälleen: hän oli kadonnut, ja on taas löydetty; ja rupesivat riemuitsemaan.","Sillä tämä minun poikani oli kuollut, ja virkosi jälleen: hän oli kadonnut, ja on taas löydetty; ja rupesivat riemuitsemaan."],[15,25,"Mutta hänen vanhempi poikansa oli pellolla, ja kuin hän tuli ja huonettä lähestyi, kuuli hän laulun ja hypyt.","Mutta hänen vanhempi poikansa oli pellolla, ja kuin hän tuli ja huonettä lähestyi, kuuli hän laulun ja hypyt."],[15,26,"Niin hän kutsui yhden palvelioistansa ja kysyi: mikä se on?","Niin hän kutsui yhden palvelioistansa ja kysyi: mikä se on?"],[15,27,"Niin se sanoi hänelle: sinun veljes tuli, ja isäs antoi tappaa syötetyn vasikan, että hän sai hänen terveenä jälleen.","Niin se sanoi hänelle: sinun veljes tuli, ja isäs antoi tappaa syötetyn vasikan, että hän sai hänen terveenä jälleen."],[15,28,"Niin hän vihastui eikä tahtonut mennä sisälle; hänen isänsä meni siis ulos, ja neuvoi häntä.","Niin hän vihastui eikä tahtonut mennä sisälle; hänen isänsä meni siis ulos, ja neuvoi häntä."],[15,29,"Mutta hän vastasi ja sanoi isällensä: katso, niin monta vuotta minä palvelen sinua, ja en ole koskaan sinun käskyäs käynyt ylitse, ja et sinä ole minulle vohlaakaan antanut, riemuitakseni ystäväini kanssa.","Mutta hän vastasi ja sanoi isällensä: katso, niin monta vuotta minä palvelen sinua, ja en ole koskaan sinun käskyäs käynyt ylitse, ja et sinä ole minulle vohlaakaan antanut, riemuitakseni ystäväini kanssa."],[15,30,"Mutta että tämä sinun poikas tuli, joka tavaransa on tuhlannut porttoin kanssa, tapoit sinä hänelle syötetyn vasikan.","Mutta että tämä sinun poikas tuli, joka tavaransa on tuhlannut porttoin kanssa, tapoit sinä hänelle syötetyn vasikan."],[15,31,"Mutta hän sanoi hänelle: poikani! sinä olet aina minun tykönäni, ja kaikki mitä minun on, se on sinun.","Mutta hän sanoi hänelle: poikani! sinä olet aina minun tykönäni, ja kaikki mitä minun on, se on sinun."],[15,32,"Niin piti sinunkin riemuitseman ja iloitseman; sillä tämä sinun veljes oli kuollut ja virkosi jälleen, hän oli kadonnut ja on taas löydetty.","Niin piti sinunkin riemuitseman ja iloitseman; sillä tämä sinun veljes oli kuollut ja virkosi jälleen, hän oli kadonnut ja on taas löydetty."],[16,1,"Mutta hän sanoi myöskin opetuslapsillensa: oli rikas mies, jolla oli huoneenhaltia, ja hänen edessänsä kannettiin hänen päällensä, että hän oli hukuttanut hänen hyvyytensä.","Mutta hän sanoi myöskin opetuslapsillensa: oli rikas mies, jolla oli huoneenhaltia, ja hänen edessänsä kannettiin hänen päällensä, että hän oli hukuttanut hänen hyvyytensä."],[16,2,"Ja hän kutsui hänen ja sanoi hänelle: miksi minä sinusta sen kuulen? tee luku hallituksestas; sillä et sinä saa tästedes hallita.","Ja hän kutsui hänen ja sanoi hänelle: miksi minä sinusta sen kuulen? tee luku hallituksestas; sillä et sinä saa tästedes hallita."],[16,3,"Niin huoneenhaltia sanoi itsellensä: mitä minä teen, sillä minun herrani ottaa minulta pois hallituksen? en minä voi kaivaa, häpeen minä kerjätä.","Niin huoneenhaltia sanoi itsellensä: mitä minä teen, sillä minun herrani ottaa minulta pois hallituksen? en minä voi kaivaa, häpeen minä kerjätä."],[16,4,"Minä tiedän, mitä minä teen, että kuin minä viralta pannaan pois, niin he korjaavat minun huoneesensa.","Minä tiedän, mitä minä teen, että kuin minä viralta pannaan pois, niin he korjaavat minun huoneesensa."],[16,5,"Ja hän kutsui tykönsä kaikki herransa velvolliset ja sanoi ensimäiselle: kuinka paljo sinä olet minun herralleni velkaa?","Ja hän kutsui tykönsä kaikki herransa velvolliset ja sanoi ensimäiselle: kuinka paljo sinä olet minun herralleni velkaa?"],[16,6,"Mutta se sanoi: sata tynnyriä öljyä. Ja hän sanoi hänelle: ota kirjas ja istu pian, ja kirjoita viisikymmentä.","Mutta se sanoi: sata tynnyriä öljyä. Ja hän sanoi hänelle: ota kirjas ja istu pian, ja kirjoita viisikymmentä."],[16,7,"Sitte hän sanoi toiselle: kuinka paljon sinä olet velkaa? ja se sanoi: sata puntaa nisuja. Hän sanoi hänelle: ota kirjas ja kirjoita kahdeksankymmentä.","Sitte hän sanoi toiselle: kuinka paljon sinä olet velkaa? ja se sanoi: sata puntaa nisuja. Hän sanoi hänelle: ota kirjas ja kirjoita kahdeksankymmentä."],[16,8,"Ja herra kiitti väärää huoneenhaltiata, että hän toimellisesti teki; sillä tämän maailman lapset ovat toimellisemmat kuin valkeuden lapset heidän sukukunnassansa.","Ja herra kiitti väärää huoneenhaltiata, että hän toimellisesti teki; sillä tämän maailman lapset ovat toimellisemmat kuin valkeuden lapset heidän sukukunnassansa."],[16,9,"Ja minä myös sanon teille: tehkäät teillenne ystäviä väärästä mammonasta, että kuin te tarvitsette, niin he korjaavat teitä ijankaikkisiin majoihin.","Ja minä myös sanon teille: tehkäät teillenne ystäviä väärästä mammonasta, että kuin te tarvitsette, niin he korjaavat teitä ijankaikkisiin majoihin."],[16,10,"Joka vähemmässä on uskollinen, se on myös paljossa uskollinen, ja joka vähemmässä on väärä, se on myös paljossa petollinen.","Joka vähemmässä on uskollinen, se on myös paljossa uskollinen, ja joka vähemmässä on väärä, se on myös paljossa petollinen."],[16,11,"Jollette siis ole olleet uskolliset väärässä mammonassa, kuka teille sitä uskoo, mikä oikia on?","Jollette siis ole olleet uskolliset väärässä mammonassa, kuka teille sitä uskoo, mikä oikia on?"],[16,12,"Ja ellette ole olleet toisen omassa uskolliset, kuka teille antaa sen, mikä teidän omanne on?","Ja ellette ole olleet toisen omassa uskolliset, kuka teille antaa sen, mikä teidän omanne on?"],[16,13,"Ei yksikään palvelia taida kahta herraa palvella; sillä taikka hän yhtä vihaa ja toista rakastaa, eli yhdessä hän kiinni riippuu ja toisen katsoo ylön. Ette taida palvella Jumalaa ja mammonaa.","Ei yksikään palvelia taida kahta herraa palvella; sillä taikka hän yhtä vihaa ja toista rakastaa, eli yhdessä hän kiinni riippuu ja toisen katsoo ylön. Ette taida palvella Jumalaa ja mammonaa."],[16,14,"Mutta kaikki nämät kuulivat nekin Pharisealaiset, jotka ahneet olivat, ja pilkkasivat häntä.","Mutta kaikki nämät kuulivat nekin Pharisealaiset, jotka ahneet olivat, ja pilkkasivat häntä."],[16,15,"Ja hän sanoi heille: te olette ne, jotka itsenne hurskaiksi teette ihmisten edessä; mutta Jumala tuntee teidän sydämenne; sillä se mikä ihmisille on korkia, se on Jumalan edessä kauhistus.","Ja hän sanoi heille: te olette ne, jotka itsenne hurskaiksi teette ihmisten edessä; mutta Jumala tuntee teidän sydämenne; sillä se mikä ihmisille on korkia, se on Jumalan edessä kauhistus."],[16,16,"Laki ja prophetat ovat Johannekseen asti, ja siitä ajasta ilmoitetaan Jumalan valtakunta, ja jokainen siihen itseänsä väellä tunkee.","Laki ja prophetat ovat Johannekseen asti, ja siitä ajasta ilmoitetaan Jumalan valtakunta, ja jokainen siihen itseänsä väellä tunkee."],[16,17,"Pikemmin taivas ja maa hukkuu, kuin rahtukaan laista putoo.","Pikemmin taivas ja maa hukkuu, kuin rahtukaan laista putoo."],[16,18,"Joka emäntänsä hylkää ja nai toisen, hän tekee huorin, ja joka sen mieheltä hyljätyn nai, hän tekee huorin.","Joka emäntänsä hylkää ja nai toisen, hän tekee huorin, ja joka sen mieheltä hyljätyn nai, hän tekee huorin."],[16,19,"Oli yksi rikas mies, joka vaatetti itsensä purpuralla ja kalliilla liinavaatteilla, ja eli joka päivä ilossa herkullisesti.","Oli yksi rikas mies, joka vaatetti itsensä purpuralla ja kalliilla liinavaatteilla, ja eli joka päivä ilossa herkullisesti."],[16,20,"Oli myös kerjääjä, nimeltä Latsarus, joka makasi hänen ovensa edessä täynnänsä paisumia,","Oli myös kerjääjä, nimeltä Latsarus, joka makasi hänen ovensa edessä täynnänsä paisumia,"],[16,21,"Ja pyysi ravittaa niistä muruista, jotka rikkaan pöydältä putosivat; mutta koirat myös tulivat ja nuolivat hänen paisumansa.","Ja pyysi ravittaa niistä muruista, jotka rikkaan pöydältä putosivat; mutta koirat myös tulivat ja nuolivat hänen paisumansa."],[16,22,"Niin tapahtui, että kerjääjä kuoli ja vietiin enkeleiltä Abrahamin helmaan: niin kuoli myös rikas ja haudattiin.","Niin tapahtui, että kerjääjä kuoli ja vietiin enkeleiltä Abrahamin helmaan: niin kuoli myös rikas ja haudattiin."],[16,23,"Ja kuin hän helvetissä vaivassa oli, nosti hän silmänsä ja näki Abrahamin taampana ja Latsaruksen hänen helmassansa.","Ja kuin hän helvetissä vaivassa oli, nosti hän silmänsä ja näki Abrahamin taampana ja Latsaruksen hänen helmassansa."],[16,24,"Ja hän huusi, sanoen: isä Abraham, armahda minun päälleni ja lähetä Latsarus kastamaan sormensa pää veteen, että hän jäähdyttäis minun kieleni; sillä minä kovin vaivataan tässä liekissä.","Ja hän huusi, sanoen: isä Abraham, armahda minun päälleni ja lähetä Latsarus kastamaan sormensa pää veteen, että hän jäähdyttäis minun kieleni; sillä minä kovin vaivataan tässä liekissä."],[16,25,"Niin sanoi Abraham: poikani, muista, että sinä sait sinun hyvääs elämässä, niin myös Latsarus pahaa. Mutta nyt hän lohdutetaan, ja sinä vaivataan.","Niin sanoi Abraham: poikani, muista, että sinä sait sinun hyvääs elämässä, niin myös Latsarus pahaa. Mutta nyt hän lohdutetaan, ja sinä vaivataan."],[16,26,"Ja paitsi kaikkia näitä on meidän ja teidän välillä suuri juopa kiinnitetty, että ne, jotka tahtovat, ei he voi, eikä sieltä tännekään tulla.","Ja paitsi kaikkia näitä on meidän ja teidän välillä suuri juopa kiinnitetty, että ne, jotka tahtovat, ei he voi, eikä sieltä tännekään tulla."],[16,27,"Niin hän sanoi: minä rukoilen siis sinua, isä, ettäs lähetät hänen minun isäni kotoon;","Niin hän sanoi: minä rukoilen siis sinua, isä, ettäs lähetät hänen minun isäni kotoon;"],[16,28,"Sillä minulla on viisi veljeä, todistamaan heille, ettei hekin tulisi tähän vaivan siaan.","Sillä minulla on viisi veljeä, todistamaan heille, ettei hekin tulisi tähän vaivan siaan."],[16,29,"Sanoi hänelle Abraham: heillä on Moses ja prophetat; kuulkoot niitä.","Sanoi hänelle Abraham: heillä on Moses ja prophetat; kuulkoot niitä."],[16,30,"Mutta hän sanoi: ei, isä Abraham: vaan jos joku kuolleista menis heidän tykönsä, niin he parannuksen tekisivät.","Mutta hän sanoi: ei, isä Abraham: vaan jos joku kuolleista menis heidän tykönsä, niin he parannuksen tekisivät."],[16,31,"Hän sanoi hänelle: ellei he Mosesta ja prophetaita kuule, niin ei he myös usko, jos joku kuolleista nousis ylös.","Hän sanoi hänelle: ellei he Mosesta ja prophetaita kuule, niin ei he myös usko, jos joku kuolleista nousis ylös."],[17,1,"Niin hän sanoi opetuslapsillensa: se on mahdotoin, ettei pahennukset tule. Mutta voi häntä, jonka kautta ne tulevat!","Niin hän sanoi opetuslapsillensa: se on mahdotoin, ettei pahennukset tule. Mutta voi häntä, jonka kautta ne tulevat!"],[17,2,"Se olis hänelle parempi, että myllyn kivi ripustettaisiin hänen kaulaansa, ja heitettäisiin mereen, kuin että hän jonkun näistä pienistä pahentais.","Se olis hänelle parempi, että myllyn kivi ripustettaisiin hänen kaulaansa, ja heitettäisiin mereen, kuin että hän jonkun näistä pienistä pahentais."],[17,3,"Kavahtakaat teitänne. Jos veljes rikkoo sinua vastaan, niin nuhtele häntä: ja jos hän itsensä parantaa, niin anna hänelle anteeksi.","Kavahtakaat teitänne. Jos veljes rikkoo sinua vastaan, niin nuhtele häntä: ja jos hän itsensä parantaa, niin anna hänelle anteeksi."],[17,4,"Ja jos hän seitsemän kertaa päivässä rikkoo sinua vastaan, ja seitsemän kertaa päivässä sinun tykös palajaa, sanoen: minä kadun; niin anna hänelle anteeksi.","Ja jos hän seitsemän kertaa päivässä rikkoo sinua vastaan, ja seitsemän kertaa päivässä sinun tykös palajaa, sanoen: minä kadun; niin anna hänelle anteeksi."],[17,5,"Ja apostolit sanoivat Herralle: lisää meille uskoa.","Ja apostolit sanoivat Herralle: lisää meille uskoa."],[17,6,"Mutta Herra sanoi: jos teillä olis usko niinkuin sinapin siemen, ja te sanoisitte tälle metsäfikunalle: nouse ylös juurines ja istuta sinus mereen, niin se kuulis teitä.","Mutta Herra sanoi: jos teillä olis usko niinkuin sinapin siemen, ja te sanoisitte tälle metsäfikunalle: nouse ylös juurines ja istuta sinus mereen, niin se kuulis teitä."],[17,7,"Mutta kenellä teistä on palvelia, joka kyntää taikka karjaa kaitsee, ja kuin hän metsästä kotia tulee, että hän sanoo kohta hänelle: mene rualle?","Mutta kenellä teistä on palvelia, joka kyntää taikka karjaa kaitsee, ja kuin hän metsästä kotia tulee, että hän sanoo kohta hänelle: mene rualle?"],[17,8,"Vaan eikö hän pikemmin sano hänelle: valmista minulle ehtoollista, sonnusta sinus, ja palvele minua, niinkauvan kuin minä syön ja juon; ja syö ja juo sinä sitte?","Vaan eikö hän pikemmin sano hänelle: valmista minulle ehtoollista, sonnusta sinus, ja palvele minua, niinkauvan kuin minä syön ja juon; ja syö ja juo sinä sitte?"],[17,9,"Vai kiittääkö hän palveliaansa, että hän teki, mitä hänelle käsketty oli? En luule.","Vai kiittääkö hän palveliaansa, että hän teki, mitä hänelle käsketty oli? En luule."],[17,10,"Niin myös te, kuin te olette kaikki tehneet, mitä teille käsketty on, niin sanokaat: me olemme kelvottomat palveliat: me teimme sen, minkä meidän piti tekemän.","Niin myös te, kuin te olette kaikki tehneet, mitä teille käsketty on, niin sanokaat: me olemme kelvottomat palveliat: me teimme sen, minkä meidän piti tekemän."],[17,11,"Ja tapahtui, kuin hän meni Jerusalemia päin, että hän matkusti keskeltä Samarian ja Galilean.","Ja tapahtui, kuin hän meni Jerusalemia päin, että hän matkusti keskeltä Samarian ja Galilean."],[17,12,"Ja kuin hän tuli yhteen kylään, kohtasivat häntä kymmenen spitalista miestä, jotka taampana seisoivat,","Ja kuin hän tuli yhteen kylään, kohtasivat häntä kymmenen spitalista miestä, jotka taampana seisoivat,"],[17,13,"Ja korottivat äänensä, sanoen: Jesus, rakas Mestari, armahda meidän päällemme!","Ja korottivat äänensä, sanoen: Jesus, rakas Mestari, armahda meidän päällemme!"],[17,14,"Ja kuin hän ne näki, sanoi hän heille: menkäät ja osoittakaat teitänne papeille. Ja tapahtui, että he mennessänsä tulivat puhtaiksi.","Ja kuin hän ne näki, sanoi hän heille: menkäät ja osoittakaat teitänne papeille. Ja tapahtui, että he mennessänsä tulivat puhtaiksi."],[17,15,"Niin yksi heistä, kuin hän näki, että hän parantunut oli, palasi jälleen ja kunnioitti Jumalaa suurella äänellä,","Niin yksi heistä, kuin hän näki, että hän parantunut oli, palasi jälleen ja kunnioitti Jumalaa suurella äänellä,"],[17,16,"Ja lankesi kasvoillensa hänen jalkainsa juureen ja kiitti häntä. Ja se oli Samarialainen.","Ja lankesi kasvoillensa hänen jalkainsa juureen ja kiitti häntä. Ja se oli Samarialainen."],[17,17,"Mutta Jesus vastaten sanoi: eikö kymmenen puhdistettu? kussa yhdeksän ovat?","Mutta Jesus vastaten sanoi: eikö kymmenen puhdistettu? kussa yhdeksän ovat?"],[17,18,"Ei ole muita löydetty, jotka palasivat Jumalaa kunnioittamaan, kuin tämä muukalainen.","Ei ole muita löydetty, jotka palasivat Jumalaa kunnioittamaan, kuin tämä muukalainen."],[17,19,"Ja hän sanoi hänelle: nouse ja mene! sinun uskos on sinun vapahtanut.","Ja hän sanoi hänelle: nouse ja mene! sinun uskos on sinun vapahtanut."],[17,20,"Ja Pharisealaiset kysyivät häneltä: koska Jumalan valtakunta olis tuleva? Vastasi hän heitä ja snaoi: ei Jumalan valtakunta tule niin, että se taidettaisiin nähdä.","Ja Pharisealaiset kysyivät häneltä: koska Jumalan valtakunta olis tuleva? Vastasi hän heitä ja snaoi: ei Jumalan valtakunta tule niin, että se taidettaisiin nähdä."],[17,21,"Ei myös heidän pidä sanoman: katso tässä, katso siellä; sillä katso, Jumalan valtakunta on teidän keskellänne.","Ei myös heidän pidä sanoman: katso tässä, katso siellä; sillä katso, Jumalan valtakunta on teidän keskellänne."],[17,22,"Niin hän sanoi opetuslapsille: se aika tulee, että te halajatte nähdä yhtäkin Ihmisen Pojan päivää, ja ette saa nähdä.","Niin hän sanoi opetuslapsille: se aika tulee, että te halajatte nähdä yhtäkin Ihmisen Pojan päivää, ja ette saa nähdä."],[17,23,"Ja he sanovat teille: katso tässä, katso siellä: älkäät menkö ulos, älkäät myös seuratko.","Ja he sanovat teille: katso tässä, katso siellä: älkäät menkö ulos, älkäät myös seuratko."],[17,24,"Sillä niinkuin pitkäisen tuli taivaan alla leimahtaa ja paistaa kaikkein päälle, mitkä taivaan alla ovat, niin on myös Ihmisen Pojan päivänänsä oleva.","Sillä niinkuin pitkäisen tuli taivaan alla leimahtaa ja paistaa kaikkein päälle, mitkä taivaan alla ovat, niin on myös Ihmisen Pojan päivänänsä oleva."],[17,25,"Mutta ennen tulee hänen paljo kärsiä ja hyljättää tältä sukukunnalta.","Mutta ennen tulee hänen paljo kärsiä ja hyljättää tältä sukukunnalta."],[17,26,"Ja niinkuin tapahtui Noan päivinä, niin myös tapahtuu Ihmisen Pojan päivinä.","Ja niinkuin tapahtui Noan päivinä, niin myös tapahtuu Ihmisen Pojan päivinä."],[17,27,"He söivät, joivat, naivat ja huolivat, hamaan siihen päivään asti, jona Noa arkkiin meni sisälle, ja vedenpaisumus tuli ja hukutti kaikki.","He söivät, joivat, naivat ja huolivat, hamaan siihen päivään asti, jona Noa arkkiin meni sisälle, ja vedenpaisumus tuli ja hukutti kaikki."],[17,28,"Niin myös tapahtui Lotin päivinä: he söivät, joivat, ostivat, myivät, istuttivat, rakensivat.","Niin myös tapahtui Lotin päivinä: he söivät, joivat, ostivat, myivät, istuttivat, rakensivat."],[17,29,"Mutta sinä päivänä, kuin Lot Sodomasta läksi, satoi tulta ja tulikiveä taivaasta, ja hukutti kaikki.","Mutta sinä päivänä, kuin Lot Sodomasta läksi, satoi tulta ja tulikiveä taivaasta, ja hukutti kaikki."],[17,30,"Niin pitää myös sinä päivänä oleman, jona Ihmisen Poika ilmoitetaan.","Niin pitää myös sinä päivänä oleman, jona Ihmisen Poika ilmoitetaan."],[17,31,"Joka sinä päivänä katon päällä on, ja hänen kalunsa ovat huoneessa, niin älköön astuko alas niitä ottamaan. Ja joka pellolla on, niin älköön myös palatko takaisin.","Joka sinä päivänä katon päällä on, ja hänen kalunsa ovat huoneessa, niin älköön astuko alas niitä ottamaan. Ja joka pellolla on, niin älköön myös palatko takaisin."],[17,32,"Muistakaa Lotin emäntää.","Muistakaa Lotin emäntää."],[17,33,"Jokainen joka pyytää henkensä vapahtaa, hän sen kadottaa, ja jokainen joka sen kadottaa, hän saattaa sen elämään.","Jokainen joka pyytää henkensä vapahtaa, hän sen kadottaa, ja jokainen joka sen kadottaa, hän saattaa sen elämään."],[17,34,"Minä sanon teille: sinä yönä ovat kaksi yhdellä vuoteella, yksi otetaan ylös, ja toinen jätetään.","Minä sanon teille: sinä yönä ovat kaksi yhdellä vuoteella, yksi otetaan ylös, ja toinen jätetään."],[17,35,"Kaksi ynnä jauhavat: yksi otetaan ylös, ja toinen jätetään.","Kaksi ynnä jauhavat: yksi otetaan ylös, ja toinen jätetään."],[17,36,"Kaksi ovat kedolla: yksi otetaan ylös, ja toinen jätetään.","Kaksi ovat kedolla: yksi otetaan ylös, ja toinen jätetään."],[17,37,"Ja he vastaten sanoivat hänelle: Herra, kussa siis? Niin sanoi hän heille: kussa raato on, sinne myös kotkat kokoontuvat.","Ja he vastaten sanoivat hänelle: Herra, kussa siis? Niin sanoi hän heille: kussa raato on, sinne myös kotkat kokoontuvat."],[18,1,"Niin hän sanoi myös heille vertauksen, että aina tulee rukoilla ja ei väsyä,","Niin hän sanoi myös heille vertauksen, että aina tulee rukoilla ja ei väsyä,"],[18,2,"Sanoen: yksi tuomari oli yhdessä kaupungissa, joka ei peljännyt Jumalaa eikä hävennyt ihmisiä.","Sanoen: yksi tuomari oli yhdessä kaupungissa, joka ei peljännyt Jumalaa eikä hävennyt ihmisiä."],[18,3,"Niin oli myös yksi leski siinä kaupungissa, joka tuli hänen tykönsä, sanoen: auta minua riitaveljeltäni.","Niin oli myös yksi leski siinä kaupungissa, joka tuli hänen tykönsä, sanoen: auta minua riitaveljeltäni."],[18,4,"Ja ei hän tahtonut kauvan aikaa. Mutta viimein sanoi hän itsellensä: vaikka en minä Jumalaa pelkää, enkä häpee ihmisiä,","Ja ei hän tahtonut kauvan aikaa. Mutta viimein sanoi hän itsellensä: vaikka en minä Jumalaa pelkää, enkä häpee ihmisiä,"],[18,5,"Kuitenkin, että tämä leski vaivaa minua, tahdon minä häntä auttaa, ettei hän viimein tulisi ja nurisisi minua.","Kuitenkin, että tämä leski vaivaa minua, tahdon minä häntä auttaa, ettei hän viimein tulisi ja nurisisi minua."],[18,6,"Niin Herra sanoi: kuulkaat, mitä tämä väärä tuomari sanoo:","Niin Herra sanoi: kuulkaat, mitä tämä väärä tuomari sanoo:"],[18,7,"Eikös Jumalan pitäisi valituita auttaman, jotka yötä ja päivää häntä huutavat, pitäiskö hänen sitä kärsimän?","Eikös Jumalan pitäisi valituita auttaman, jotka yötä ja päivää häntä huutavat, pitäiskö hänen sitä kärsimän?"],[18,8,"Minä sanon teille: hän auttaa heitä pian. Kuitenkin, kuin Ihmisen Poika on tuleva, löytäneekö hän uskoa maan päältä?","Minä sanon teille: hän auttaa heitä pian. Kuitenkin, kuin Ihmisen Poika on tuleva, löytäneekö hän uskoa maan päältä?"],[18,9,"Niin hän myös sanoi muutamille, jotka itse päällensä uskalsivat, että he olivat hurskaat, ja muita katsoivat ylön, tämän vertauksen:","Niin hän myös sanoi muutamille, jotka itse päällensä uskalsivat, että he olivat hurskaat, ja muita katsoivat ylön, tämän vertauksen:"],[18,10,"Kaksi ihmistä meni ylös templiin rukoilemaan, yksi Pharisealainen ja toinen Publikani.","Kaksi ihmistä meni ylös templiin rukoilemaan, yksi Pharisealainen ja toinen Publikani."],[18,11,"Pharisealainen seisoi ja rukoili näin itsellensä: minä kiitän sinua, Jumala, etten minä ole niinkuin muut ihmiset, ryöväri, väärä, huorintekiä, taikka myös niinkuin tämä Publikani.","Pharisealainen seisoi ja rukoili näin itsellensä: minä kiitän sinua, Jumala, etten minä ole niinkuin muut ihmiset, ryöväri, väärä, huorintekiä, taikka myös niinkuin tämä Publikani."],[18,12,"Kahdesti viikossa minä paastoon, ja annan kymmenykset kaikista mitä minulla on.","Kahdesti viikossa minä paastoon, ja annan kymmenykset kaikista mitä minulla on."],[18,13,"Ja Publikani seisoi taampana, eikä tahtonut silmiänsäkään nostaa ylös taivaasen päin, mutta löi rintoihinsa ja sanoi: Jumala, armahda minun syntisen päälleni!","Ja Publikani seisoi taampana, eikä tahtonut silmiänsäkään nostaa ylös taivaasen päin, mutta löi rintoihinsa ja sanoi: Jumala, armahda minun syntisen päälleni!"],[18,14,"Minä sanon teille: tämä meni kotiansa hurskaampana kuin toinen; sillä jokainen joka itsensä ylentää, se alennetaan, ja joka itsensä alentaa, se ylennetään.","Minä sanon teille: tämä meni kotiansa hurskaampana kuin toinen; sillä jokainen joka itsensä ylentää, se alennetaan, ja joka itsensä alentaa, se ylennetään."],[18,15,"Niin he toivat myös hänen tykönsä lapsia, että hän heihin rupeais. Mutta kuin opetuslapset sen näkivät, nuhtelivat he niitä.","Niin he toivat myös hänen tykönsä lapsia, että hän heihin rupeais. Mutta kuin opetuslapset sen näkivät, nuhtelivat he niitä."],[18,16,"Mutta kuin Jesus oli heitä kutsunut tykönsä, sanoi hän: sallikaat lasten tulla minun tyköni, ja älkäät heitä kieltäkö; sillä senkaltaisten on Jumalan valtakunta.","Mutta kuin Jesus oli heitä kutsunut tykönsä, sanoi hän: sallikaat lasten tulla minun tyköni, ja älkäät heitä kieltäkö; sillä senkaltaisten on Jumalan valtakunta."],[18,17,"Totisesti sanon minä teille: joka ei ota vastaan Jumalan valtakuntaa niinkuin lapsi, ei hän ikinä siihen tule siihen sisälle.","Totisesti sanon minä teille: joka ei ota vastaan Jumalan valtakuntaa niinkuin lapsi, ei hän ikinä siihen tule siihen sisälle."],[18,18,"Ja häneltä kysyi yksi päämiehistä ja sanoi: hyvä Mestari, mitä minun pitää tekemän, että minä ijankaikkisen elämän saisin? *","Ja häneltä kysyi yksi päämiehistä ja sanoi: hyvä Mestari, mitä minun pitää tekemän, että minä ijankaikkisen elämän saisin? *"],[18,19,"Niin Jesus sanoi hänelle: mitäs minua hyväksi kutsut? Ei ole kenenkään hyvä, vaan yksi, Jumala.","Niin Jesus sanoi hänelle: mitäs minua hyväksi kutsut? Ei ole kenenkään hyvä, vaan yksi, Jumala."],[18,20,"Käskysanat sinä tiedät: ei sinun pidä huorin tekemän: ei sinun pidä tappaman: ei sinun pidä varastaman: ei sinun pidä väärää todistusta sanoman: kunnioita isääs ja äitiäs.","Käskysanat sinä tiedät: ei sinun pidä huorin tekemän: ei sinun pidä tappaman: ei sinun pidä varastaman: ei sinun pidä väärää todistusta sanoman: kunnioita isääs ja äitiäs."],[18,21,"Niin hän sanoi: nämät kaikki olen minä minun nuoruudestani pitänyt.","Niin hän sanoi: nämät kaikki olen minä minun nuoruudestani pitänyt."],[18,22,"Kuin Jesus sen kuuli, sanoi hän hänelle: yksi sinulta vielä puuttuu: myy kaikki, mitä sinulla on ja vaivaisille, niin sinulla pitää oleman tavara taivaassa: ja tule, seuraa minua.","Kuin Jesus sen kuuli, sanoi hän hänelle: yksi sinulta vielä puuttuu: myy kaikki, mitä sinulla on ja vaivaisille, niin sinulla pitää oleman tavara taivaassa: ja tule, seuraa minua."],[18,23,"Vaan kuin hän sen kuuli, tuli hän murheelliseksi; sillä hän oli sangen rikas.","Vaan kuin hän sen kuuli, tuli hän murheelliseksi; sillä hän oli sangen rikas."],[18,24,"Mutta kuin Jesus näki hänen murheissansa olevan, sanoi hän: kuinka työläästi rikkaat tulevat Jumalan valtakuntaan;","Mutta kuin Jesus näki hänen murheissansa olevan, sanoi hän: kuinka työläästi rikkaat tulevat Jumalan valtakuntaan;"],[18,25,"Sillä huokiampi on kamelin käydä neulan silmän lävitse, kuin rikkaan tulla Jumalan valtakuntaan.","Sillä huokiampi on kamelin käydä neulan silmän lävitse, kuin rikkaan tulla Jumalan valtakuntaan."],[18,26,"Niin he sanoivat, jotka sen kuulivat: ja kuka taitaa autuaaksi tulla?","Niin he sanoivat, jotka sen kuulivat: ja kuka taitaa autuaaksi tulla?"],[18,27,"Mutta hän sanoi: ne mitkä ovat mahdottomat ihmisten tykönä, ne ovat mahdolliset Jumalan tykönä.","Mutta hän sanoi: ne mitkä ovat mahdottomat ihmisten tykönä, ne ovat mahdolliset Jumalan tykönä."],[18,28,"Niin Pietari sanoi: katso, me jätimme kaikki ja seurasimme sinua.","Niin Pietari sanoi: katso, me jätimme kaikki ja seurasimme sinua."],[18,29,"Vaan hän sanoi heille: totisesti sanon minä teille: ei ole kenkään, joka jätti huoneen taikka vanhemmat taikka veljet taikka emännän taikka lapset Jumalan valtakunnan tähden,","Vaan hän sanoi heille: totisesti sanon minä teille: ei ole kenkään, joka jätti huoneen taikka vanhemmat taikka veljet taikka emännän taikka lapset Jumalan valtakunnan tähden,"],[18,30,"Joka ei paljoa enempää saa tällä ajalla jällensä, ja tulevaisessa maailmassa ijankaikkisen elämän.","Joka ei paljoa enempää saa tällä ajalla jällensä, ja tulevaisessa maailmassa ijankaikkisen elämän."],[18,31,"Ja hän otti tykönsä ne kaksitoistakymmentä, ja sanoi heille: katso, me menemme Jerusalemiin, ja kaikki pitää täytettämän mitkä prophetailta Ihmisen Pojasta kirjoitetut ovat.","Ja hän otti tykönsä ne kaksitoistakymmentä, ja sanoi heille: katso, me menemme Jerusalemiin, ja kaikki pitää täytettämän mitkä prophetailta Ihmisen Pojasta kirjoitetut ovat."],[18,32,"Sillä hän annetaan ylön pakanoille, ja pilkataan, ja häväistään, ja syljetään.","Sillä hän annetaan ylön pakanoille, ja pilkataan, ja häväistään, ja syljetään."],[18,33,"Ja kuin he ovat hänen ruoskineet, tappavat he hänen, ja kolmantena päivänä on hän nouseva ylös.","Ja kuin he ovat hänen ruoskineet, tappavat he hänen, ja kolmantena päivänä on hän nouseva ylös."],[18,34,"Ja ei he mitään näistä ymmärtäneet. Ja tämä puhe oli heiltä niin peitetty, ettei he ymmärtäneet, mitä sanottiin.","Ja ei he mitään näistä ymmärtäneet. Ja tämä puhe oli heiltä niin peitetty, ettei he ymmärtäneet, mitä sanottiin."],[18,35,"Niin tapahtui, kuin hän Jerikoa lähestyi, että yksi sokia istui tien vieressä kerjäten,","Niin tapahtui, kuin hän Jerikoa lähestyi, että yksi sokia istui tien vieressä kerjäten,"],[18,36,"Ja kuin hän kuuli kansan käyvän ohitse, kysyi hän, mikä se olis?","Ja kuin hän kuuli kansan käyvän ohitse, kysyi hän, mikä se olis?"],[18,37,"He sanoivat hänelle: Jesus Natsarealainen tästä meni.","He sanoivat hänelle: Jesus Natsarealainen tästä meni."],[18,38,"Ja hän huusi ja sanoi: Jesus, Davidin Poika, armahda minua!","Ja hän huusi ja sanoi: Jesus, Davidin Poika, armahda minua!"],[18,39,"Niin ne, jotka menivät ohitse, toruivat häntä vaikenemaan. Mutta hän huusi sitä enemmin: Davidin Poika, armahda minua!","Niin ne, jotka menivät ohitse, toruivat häntä vaikenemaan. Mutta hän huusi sitä enemmin: Davidin Poika, armahda minua!"],[18,40,"Niin Jesus seisahti ja käski häntä taluttaa tykönsä. Ja kuin hän lähestyi, kysyi hän häneltä,","Niin Jesus seisahti ja käski häntä taluttaa tykönsä. Ja kuin hän lähestyi, kysyi hän häneltä,"],[18,41,"Sanoen: mitäs tahdot, että minun pitää sinulle tekemän? Hän sanoi: Herra, että minä näköni jälleen saisin.","Sanoen: mitäs tahdot, että minun pitää sinulle tekemän? Hän sanoi: Herra, että minä näköni jälleen saisin."],[18,42,"Ja Jesus sanoi hänelle: ole näkevä! sinun uskos autti sinua.","Ja Jesus sanoi hänelle: ole näkevä! sinun uskos autti sinua."],[18,43,"Ja hän sai kohta näkönsä, ja seurasi häntä, ja kunnioitti Jumalaa. Ja kaikki kansa, jotka sen näkivät, kiittivät Jumalaa.","Ja hän sai kohta näkönsä, ja seurasi häntä, ja kunnioitti Jumalaa. Ja kaikki kansa, jotka sen näkivät, kiittivät Jumalaa."],[19,1,"Ja hän meni sisälle ja vaelsi Jerikon lävitse.","Ja hän meni sisälle ja vaelsi Jerikon lävitse."],[19,2,"Ja katso, yksi mies oli nimeltä Zakeus, joka oli Publikanien päämies ja hän oli rikas,","Ja katso, yksi mies oli nimeltä Zakeus, joka oli Publikanien päämies ja hän oli rikas,"],[19,3,"Ja hän pyysi nähdä Jesusta, kuka hän olis, eikä saanut kansalta; sillä hän oli varttansa vähäinen.","Ja hän pyysi nähdä Jesusta, kuka hän olis, eikä saanut kansalta; sillä hän oli varttansa vähäinen."],[19,4,"Ja hän samosi edelle, meni ylös yhteen metsä-fikunapuuhun, että hän olis saanut hänen nähdä; sillä sen kautta oli hän vaeltava.","Ja hän samosi edelle, meni ylös yhteen metsä-fikunapuuhun, että hän olis saanut hänen nähdä; sillä sen kautta oli hän vaeltava."],[19,5,"Ja kuin hän tuli siihen paikkaan, katsoi Jesus ylös, ja näki hänen, ja sanoi hänelle: Zakeus, astu nopiasti alas! sillä minun pitää tänäpänä oleman sinun huoneessas.","Ja kuin hän tuli siihen paikkaan, katsoi Jesus ylös, ja näki hänen, ja sanoi hänelle: Zakeus, astu nopiasti alas! sillä minun pitää tänäpänä oleman sinun huoneessas."],[19,6,"Ja hän astui nopiasti alas ja otti hänen iloiten vastaan.","Ja hän astui nopiasti alas ja otti hänen iloiten vastaan."],[19,7,"Ja kuin he sen näkivät, napisivat he kaikki, että hän meni sisälle syntisen miehen tykö olemaan.","Ja kuin he sen näkivät, napisivat he kaikki, että hän meni sisälle syntisen miehen tykö olemaan."],[19,8,"Mutta Zakeus seisoi ja sanoi Herralle: katso, Herra, puolen minun tavaraani annan minä vaivaisille; ja jos minä jonkun pettänyt olen, sen minä neljäkertaisesti jälleen annan.","Mutta Zakeus seisoi ja sanoi Herralle: katso, Herra, puolen minun tavaraani annan minä vaivaisille; ja jos minä jonkun pettänyt olen, sen minä neljäkertaisesti jälleen annan."],[19,9,"Niin Jesus sanoi hänelle: tänäpänä on tälle huoneelle autuus tapahtunut, että hänkin on Abrahamin poika.","Niin Jesus sanoi hänelle: tänäpänä on tälle huoneelle autuus tapahtunut, että hänkin on Abrahamin poika."],[19,10,"Sillä Ihmisen Poika tuli etsimään ja vapahtamaan sitä, mikä kadonnut oli.","Sillä Ihmisen Poika tuli etsimään ja vapahtamaan sitä, mikä kadonnut oli."],[19,11,"Mutta kuin he nämät kuulleet olivat, sanoi hän vielä yhden vertauksen: että hän oli juuri läsnä Jerusalemia, ja että he luulivat Jumalan valtakunnan kohta ilmoitettavan.","Mutta kuin he nämät kuulleet olivat, sanoi hän vielä yhden vertauksen: että hän oli juuri läsnä Jerusalemia, ja että he luulivat Jumalan valtakunnan kohta ilmoitettavan."],[19,12,"Sanoi hän siis: yksi herrasmies matkusti kaukaiseen maakuntaan, itsellensä valtakuntaa ottamaan, ja aikoi jälleen palata:","Sanoi hän siis: yksi herrasmies matkusti kaukaiseen maakuntaan, itsellensä valtakuntaa ottamaan, ja aikoi jälleen palata:"],[19,13,"Niin hän kutsui tykönsä kymmenen palveliaansa ja antoi heille kymmenen leiviskää, ja sanoi heille: tehkäät kauppaa niinkauvan kuin minä tulen.","Niin hän kutsui tykönsä kymmenen palveliaansa ja antoi heille kymmenen leiviskää, ja sanoi heille: tehkäät kauppaa niinkauvan kuin minä tulen."],[19,14,"Mutta hänen kylänsä asujat vihasivat häntä, ja lähettivät sanansaattajat hänen jälkeensä, sanoen: emme tahdo, että tämä meitä vallitsee.","Mutta hänen kylänsä asujat vihasivat häntä, ja lähettivät sanansaattajat hänen jälkeensä, sanoen: emme tahdo, että tämä meitä vallitsee."],[19,15,"Ja tapahtui kuin hän palasi, sitte kuin hän sai valtakunnan, käski hän kutsua ne palveliat tykönsä, joille hän oli rahansa antanut, tietääksensä, mitä kukin kaupallansa toimittanut oli.","Ja tapahtui kuin hän palasi, sitte kuin hän sai valtakunnan, käski hän kutsua ne palveliat tykönsä, joille hän oli rahansa antanut, tietääksensä, mitä kukin kaupallansa toimittanut oli."],[19,16,"Niin tuli ensimäinen ja sanoi: herra, sinun leiviskäs on kymmenen leiviskää kasvattanut.","Niin tuli ensimäinen ja sanoi: herra, sinun leiviskäs on kymmenen leiviskää kasvattanut."],[19,17,"Ja hän sanoi hänelle: oikein, hyvä palvelia, ettäs vähässä olit uskollinen, sinulla pitää valta kymmenen kaupungin päälle oleman.","Ja hän sanoi hänelle: oikein, hyvä palvelia, ettäs vähässä olit uskollinen, sinulla pitää valta kymmenen kaupungin päälle oleman."],[19,18,"Toinen myös tuli ja sanoi: herra, sinun leiviskäs on viisi leiviskää kasvattanut.","Toinen myös tuli ja sanoi: herra, sinun leiviskäs on viisi leiviskää kasvattanut."],[19,19,"Niin hän myös sanoi hänelle: ole sinäkin viiden kaupungin haltia.","Niin hän myös sanoi hänelle: ole sinäkin viiden kaupungin haltia."],[19,20,"Ja kolmas tuli ja sanoi: herra, katso, tässä on sinun leiviskäs, joka minulla hikiliinassa kätketty oli;","Ja kolmas tuli ja sanoi: herra, katso, tässä on sinun leiviskäs, joka minulla hikiliinassa kätketty oli;"],[19,21,"Sillä minä pelkäsin sinua, ettäs kova mies olet; sinä otat, jota et tallelle pannut, ja niität, jota et kylvänyt.","Sillä minä pelkäsin sinua, ettäs kova mies olet; sinä otat, jota et tallelle pannut, ja niität, jota et kylvänyt."],[19,22,"Hän sanoi hänelle: sinun suustas minä sinun tuomitsen, sinä paha palvelia, sinä tiesit minun kovaksi mieheksi, joka otan, jota en minä tallelle pannut, ja leikkaan, jota en minä kylvänyt:","Hän sanoi hänelle: sinun suustas minä sinun tuomitsen, sinä paha palvelia, sinä tiesit minun kovaksi mieheksi, joka otan, jota en minä tallelle pannut, ja leikkaan, jota en minä kylvänyt:"],[19,23,"Ja miksi et sinä antanut minun rahaani vaihetuspöydälle? ja minä olisin tultuani sen kasvun kanssa jälleen saanut.","Ja miksi et sinä antanut minun rahaani vaihetuspöydälle? ja minä olisin tultuani sen kasvun kanssa jälleen saanut."],[19,24,"Niin hän sanoi tykönä seisoville: ottakaat pois leiviskä häneltä, ja antakaat sille, jolla kymmenen leiviskää on.","Niin hän sanoi tykönä seisoville: ottakaat pois leiviskä häneltä, ja antakaat sille, jolla kymmenen leiviskää on."],[19,25,"Niin he sanoivat hänelle: herra, hänellä on kymmenen leiviskää.","Niin he sanoivat hänelle: herra, hänellä on kymmenen leiviskää."],[19,26,"Sillä minä sanon teille, jolla on, hänelle pitää annettaman, ja häneltä, jolla ei ole, sekin, mikä hänellä on, pitää otettaman pois.","Sillä minä sanon teille, jolla on, hänelle pitää annettaman, ja häneltä, jolla ei ole, sekin, mikä hänellä on, pitää otettaman pois."],[19,27,"Kuitenkin ne minun viholliseni, jotka ei tahtoneet minun antaa vallita heitä, tuokaat tänne ja mestatkaa heitä minun edessäni.","Kuitenkin ne minun viholliseni, jotka ei tahtoneet minun antaa vallita heitä, tuokaat tänne ja mestatkaa heitä minun edessäni."],[19,28,"Ja kuin hän nämät puhunut oli, meni hän edellä ja vaelsi ylös Jerusalemia päin.","Ja kuin hän nämät puhunut oli, meni hän edellä ja vaelsi ylös Jerusalemia päin."],[19,29,"Ja tapahtui, kuin hän lähestyi Betphagea ja Betaniaa, ja tuli sen vuoren tykö, joka öljymäeksi kutsutaan kutsutaan, lähetti hän kaksi opetuslapsistansa,","Ja tapahtui, kuin hän lähestyi Betphagea ja Betaniaa, ja tuli sen vuoren tykö, joka öljymäeksi kutsutaan kutsutaan, lähetti hän kaksi opetuslapsistansa,"],[19,30,"Sanoen: menkäät kylään, joka on teidän edessänne, ja kuin te siihen tulette sisälle, niin te löydätte varsan sidottuna, jonka päällä ei yksikään ihminen koskaan istunut ole: päästäkäät se ja tuokaat tänne.","Sanoen: menkäät kylään, joka on teidän edessänne, ja kuin te siihen tulette sisälle, niin te löydätte varsan sidottuna, jonka päällä ei yksikään ihminen koskaan istunut ole: päästäkäät se ja tuokaat tänne."],[19,31,"Ja jos joku teiltä kysyy: miksi te sitä päästätte? niin sanokaat hänelle: Herra tätä tarvitsee.","Ja jos joku teiltä kysyy: miksi te sitä päästätte? niin sanokaat hänelle: Herra tätä tarvitsee."],[19,32,"Niin lähetetyt menivät ja löysivät niinkuin hän oli heille sanonut.","Niin lähetetyt menivät ja löysivät niinkuin hän oli heille sanonut."],[19,33,"Kuin he nyt päästivät varsaa, sanoi sen isäntä heille: miksi te päästätte varsaa?","Kuin he nyt päästivät varsaa, sanoi sen isäntä heille: miksi te päästätte varsaa?"],[19,34,"Vaan he sanoivat: Herra tätä tarvitsee.","Vaan he sanoivat: Herra tätä tarvitsee."],[19,35,"Ja he veivät sen Jesuksen tykö, ja panivat vaatteensa varsan päälle, ja istuttivat Jesuksen se päälle.","Ja he veivät sen Jesuksen tykö, ja panivat vaatteensa varsan päälle, ja istuttivat Jesuksen se päälle."],[19,36,"Ja kuin hän matkusti, levittivät he vaatteensa tielle.","Ja kuin hän matkusti, levittivät he vaatteensa tielle."],[19,37,"Ja kuin hän jo lähestyi menemään alas Öljymäeltä, rupesi koko opetuslasten joukko iloiten kiittämään Jumalaa suurella äänellä kaikistä niistä voimallisista töistä, jotka he nähneet olivat,","Ja kuin hän jo lähestyi menemään alas Öljymäeltä, rupesi koko opetuslasten joukko iloiten kiittämään Jumalaa suurella äänellä kaikistä niistä voimallisista töistä, jotka he nähneet olivat,"],[19,38,"Sanoen: siunattu olkoon se, joka tulee, kuningas Herran nimeen! rauha taivaassa ja kunnia korkeuksissa!","Sanoen: siunattu olkoon se, joka tulee, kuningas Herran nimeen! rauha taivaassa ja kunnia korkeuksissa!"],[19,39,"Ja muutamat Pharisealaisista kansan seasta sanoivat hänelle: Mestari, nuhtele opetuslapsias.","Ja muutamat Pharisealaisista kansan seasta sanoivat hänelle: Mestari, nuhtele opetuslapsias."],[19,40,"Ja hän vastaten sanoi heille: minä sanon teille: jos nämät vaikenevat, niin kivet pitää huutaman.","Ja hän vastaten sanoi heille: minä sanon teille: jos nämät vaikenevat, niin kivet pitää huutaman."],[19,41,"Ja kuin hän lähemmä tuli, katsoi hän kaupungin päälle, itki häntä,","Ja kuin hän lähemmä tuli, katsoi hän kaupungin päälle, itki häntä,"],[19,42,"Ja sanoi: jos sinäkin tietäisit, niin sinä ajattelisit tosin tällä sinun ajallas, mitä sinun rauhaas sopis. Mutta nyt ovat ne kätketyt sinun silmäis edestä.","Ja sanoi: jos sinäkin tietäisit, niin sinä ajattelisit tosin tällä sinun ajallas, mitä sinun rauhaas sopis. Mutta nyt ovat ne kätketyt sinun silmäis edestä."],[19,43,"Sillä ne päivät pitää tuleman sinun ylitses, että sinun vihollises skantsaavat * sinun, ja ympäri piirittävät sinun, ja ahdistavat sinun joka kulmalta,","Sillä ne päivät pitää tuleman sinun ylitses, että sinun vihollises skantsaavat * sinun, ja ympäri piirittävät sinun, ja ahdistavat sinun joka kulmalta,"],[19,44,"Ja maahan tasoittavat sinun ja sinun lapses, jotka sinussa ovat, ja ei jätä sinussa kiveä kiven päälle; ettet etsikkos aikaa tuntenut.","Ja maahan tasoittavat sinun ja sinun lapses, jotka sinussa ovat, ja ei jätä sinussa kiveä kiven päälle; ettet etsikkos aikaa tuntenut."],[19,45,"Ja hän meni sisälle templiin, rupesi ajamaan siitä ulos ostajia ja myyjiä,","Ja hän meni sisälle templiin, rupesi ajamaan siitä ulos ostajia ja myyjiä,"],[19,46,"Sanoen heille: kirjoitettu on: minun huoneeni on rukoushuone; mutta te olette sen tehneet ryövärien luolaksi.","Sanoen heille: kirjoitettu on: minun huoneeni on rukoushuone; mutta te olette sen tehneet ryövärien luolaksi."],[19,47,"Ja hän opetti joka päivä templissä, mutta pappein päämiehet ja kirjanoppineet ja kansan vanhimmat etsivät häntä surmataksensa,","Ja hän opetti joka päivä templissä, mutta pappein päämiehet ja kirjanoppineet ja kansan vanhimmat etsivät häntä surmataksensa,"],[19,48,"Ja ei tietäneet, mitä heidän piti tekemän; sillä kaikki kansa riippui hänessä, ja kuulivat häntä.","Ja ei tietäneet, mitä heidän piti tekemän; sillä kaikki kansa riippui hänessä, ja kuulivat häntä."],[20,1,"Ja tapahtui yhtenä niistä päivistä, kuin hän kansaa opetti templissä ja saarnasi evankeliumia, tulivat ylimmäiset papit ja kirjanoppineet ja vanhimmat,","Ja tapahtui yhtenä niistä päivistä, kuin hän kansaa opetti templissä ja saarnasi evankeliumia, tulivat ylimmäiset papit ja kirjanoppineet ja vanhimmat,"],[20,2,"Ja puhuivat hänelle, sanoen: sanos meille, millä vallalla sinä tätä teet? eli kuka sinulle tämän vallan on antanut?","Ja puhuivat hänelle, sanoen: sanos meille, millä vallalla sinä tätä teet? eli kuka sinulle tämän vallan on antanut?"],[20,3,"Niin Jesus vastaten sanoi heille: minä kysyn myös teiltä yhtä asiaa, vastatkaat minua.","Niin Jesus vastaten sanoi heille: minä kysyn myös teiltä yhtä asiaa, vastatkaat minua."],[20,4,"Oliko Johanneksen kaste taivaasta, vaiko ihmisiltä?","Oliko Johanneksen kaste taivaasta, vaiko ihmisiltä?"],[20,5,"Niin he ajattelivat itsellänsä, sanoen: jo me sanomme: taivaasta, niin hän sanoo: miksi ette siis uskoneet?","Niin he ajattelivat itsellänsä, sanoen: jo me sanomme: taivaasta, niin hän sanoo: miksi ette siis uskoneet?"],[20,6,"Mutta jos me sanomme: ihmisiltä, niin kaikki kansa kivittää meidät; sillä he uskoivat, että Johannes oli propheta.","Mutta jos me sanomme: ihmisiltä, niin kaikki kansa kivittää meidät; sillä he uskoivat, että Johannes oli propheta."],[20,7,"Ja he vastasivat, ettei he tietäneet, kusta se oli.","Ja he vastasivat, ettei he tietäneet, kusta se oli."],[20,8,"Niin sanoi Jesus heille: en minä myös sano teille, millä voimalla minä näitä teen.","Niin sanoi Jesus heille: en minä myös sano teille, millä voimalla minä näitä teen."],[20,9,"Niin hän rupesi sanomaan kansalle tämän vertauksen: yksi mies istutti viinamäen ja pani sen vuorolle peltomiehille, ja meni muille maille kauvaksi aikaa.","Niin hän rupesi sanomaan kansalle tämän vertauksen: yksi mies istutti viinamäen ja pani sen vuorolle peltomiehille, ja meni muille maille kauvaksi aikaa."],[20,10,"Ja ajallansa lähetti hän palvelian peltomiesten tykö, että he antaisivat hänelle viinamäen hedelmästä. Mutta ne peltomiehet pieksivät sen ja lähettivät pois tyhjänä.","Ja ajallansa lähetti hän palvelian peltomiesten tykö, että he antaisivat hänelle viinamäen hedelmästä. Mutta ne peltomiehet pieksivät sen ja lähettivät pois tyhjänä."],[20,11,"Ja hän lähetti vielä toisen palvelian; mutta he myös sen pieksivät, ja pilkkasivat, ja lähettivät pois tyhjänä.","Ja hän lähetti vielä toisen palvelian; mutta he myös sen pieksivät, ja pilkkasivat, ja lähettivät pois tyhjänä."],[20,12,"Ja hän lähetti vielä kolmannen. Mutta he myös sen haavoittivat ja syöksivät ulos.","Ja hän lähetti vielä kolmannen. Mutta he myös sen haavoittivat ja syöksivät ulos."],[20,13,"Niin viinamäen isäntä sanoi: mitä minä teen? minä lähetän minun rakkaan poikani: kuin he hänen näkevät, niin he karttavat häntä.","Niin viinamäen isäntä sanoi: mitä minä teen? minä lähetän minun rakkaan poikani: kuin he hänen näkevät, niin he karttavat häntä."],[20,14,"Mutta kuin peltomiehet sen näkivät, ajattelivat he itsellänsä, sanoen: tämä on perillinen: tulkaat, tappakaamme häntä, että perintö tulis meidän omaksemme.","Mutta kuin peltomiehet sen näkivät, ajattelivat he itsellänsä, sanoen: tämä on perillinen: tulkaat, tappakaamme häntä, että perintö tulis meidän omaksemme."],[20,15,"Ja he syöksivät ulos hänen viinamäestä ja tappoivat. Mitä viinamäen isäntä on tekevä heille?","Ja he syöksivät ulos hänen viinamäestä ja tappoivat. Mitä viinamäen isäntä on tekevä heille?"],[20,16,"Hän tulee ja hukkaa nämät peltomiehet, ja antaa viinamäen muille. Kuin he sen kuulivat, sanoivat he: pois se!","Hän tulee ja hukkaa nämät peltomiehet, ja antaa viinamäen muille. Kuin he sen kuulivat, sanoivat he: pois se!"],[20,17,"Mutta hän katsahti heidän päällensä ja sanoi: mitä se on, mikä kirjoitettu on: Se kivi, jonka rakentajat hylkäsivät, on tullut nurkkakiveksi?","Mutta hän katsahti heidän päällensä ja sanoi: mitä se on, mikä kirjoitettu on: Se kivi, jonka rakentajat hylkäsivät, on tullut nurkkakiveksi?"],[20,18,"Jokainen joka lankee sen kiven päälle, se runnellaan; mutta jonka päälle se lankee, sen hän musertaa.","Jokainen joka lankee sen kiven päälle, se runnellaan; mutta jonka päälle se lankee, sen hän musertaa."],[20,19,"Ja pappein päämiehet ja kirjanoppineet pyysivät häntä sillä hetkellä kiinni ottaa, vaan he pelkäsivät kansaa; sillä he ymmärsivät, että hän heille tämän vertauksen sanonut oli.","Ja pappein päämiehet ja kirjanoppineet pyysivät häntä sillä hetkellä kiinni ottaa, vaan he pelkäsivät kansaa; sillä he ymmärsivät, että hän heille tämän vertauksen sanonut oli."],[20,20,"Ja he vartioitsivat häntä ja lähettivät väijyjät, jotka piti itsensä hurskaiksi teettelemän, että he hänen puheessa saisivat kiinni, ja antaisivat ylön esivallalle ja maanvanhimman haltuun.","Ja he vartioitsivat häntä ja lähettivät väijyjät, jotka piti itsensä hurskaiksi teettelemän, että he hänen puheessa saisivat kiinni, ja antaisivat ylön esivallalle ja maanvanhimman haltuun."],[20,21,"Ja he kysyivät häneltä ja sanoivat: Mestari, me tiedämme, ettäs oikein sanot ja opetat, etkä katso ihmisen muotoa, vaan opetat Jumalan tien totuudessa.","Ja he kysyivät häneltä ja sanoivat: Mestari, me tiedämme, ettäs oikein sanot ja opetat, etkä katso ihmisen muotoa, vaan opetat Jumalan tien totuudessa."],[20,22,"Sopiiko meidän antaa keisarille veroa, taikka ei?","Sopiiko meidän antaa keisarille veroa, taikka ei?"],[20,23,"Mutta kuin hän ymmärsi heidän kavaluutensa, sanoi hän heille: mitä te minua kiusaatte?","Mutta kuin hän ymmärsi heidän kavaluutensa, sanoi hän heille: mitä te minua kiusaatte?"],[20,24,"Osoittakaat minulle veroraha, kenenkä kuva ja päällekirjoitus siinä on? He vastasivat ja sanoivat: keisarin.","Osoittakaat minulle veroraha, kenenkä kuva ja päällekirjoitus siinä on? He vastasivat ja sanoivat: keisarin."],[20,25,"Niin hän sanoi heille: antakaat keisarille, mitkä keisarin ovat, ja Jumalalle, mitkä Jumalan ovat.","Niin hän sanoi heille: antakaat keisarille, mitkä keisarin ovat, ja Jumalalle, mitkä Jumalan ovat."],[20,26,"Ja ei he taitaneet hänen puhettansa kansan edessä laittaa, vaan ihmettelivät hänen vastaustansa, ja vaikenivat.","Ja ei he taitaneet hänen puhettansa kansan edessä laittaa, vaan ihmettelivät hänen vastaustansa, ja vaikenivat."],[20,27,"Niin tulivat muutamat Saddukealaisista, (jotka kieltävät ylösnousemisen,) ja kysyivät häneltä,","Niin tulivat muutamat Saddukealaisista, (jotka kieltävät ylösnousemisen,) ja kysyivät häneltä,"],[20,28,"Sanoen: Mestari, Moses kirjoitti meille: jos jonkun veli kuolee, jolla emäntä oli, ja se kuolis lapsetonna, niin hänen veljensä pitää sen vaimon ottaman ja veljellensä siemenen herättämän.","Sanoen: Mestari, Moses kirjoitti meille: jos jonkun veli kuolee, jolla emäntä oli, ja se kuolis lapsetonna, niin hänen veljensä pitää sen vaimon ottaman ja veljellensä siemenen herättämän."],[20,29,"Niin oli seitsemän veljeä: ensimäinen otti emännän ja kuoli lapsetonna.","Niin oli seitsemän veljeä: ensimäinen otti emännän ja kuoli lapsetonna."],[20,30,"Ja toinen otti sen vaimon, ja se myös kuoli lapsetonna.","Ja toinen otti sen vaimon, ja se myös kuoli lapsetonna."],[20,31,"Ja kolmas otti myös sen: ja niin kaikki seitsemän, eikä jättäneet lapsia, ja kuolivat.","Ja kolmas otti myös sen: ja niin kaikki seitsemän, eikä jättäneet lapsia, ja kuolivat."],[20,32,"Kaikkein viimein kuoli myös vaimo.","Kaikkein viimein kuoli myös vaimo."],[20,33,"Sentähden ylösnousemisessa, kenenkä heistä vaimo pitää oleman? sillä kaikki seitsemän ovat sen vaimonansa pitäneet.","Sentähden ylösnousemisessa, kenenkä heistä vaimo pitää oleman? sillä kaikki seitsemän ovat sen vaimonansa pitäneet."],[20,34,"Ja Jesus vastaten sanoi heille: tämän maailman lapset naivat ja huolevat;","Ja Jesus vastaten sanoi heille: tämän maailman lapset naivat ja huolevat;"],[20,35,"Mutta ne, jotka otolliseksi tulevat sille maailmalle ja ylösnousemiselle kuolleista, ei he nai eikä huole;","Mutta ne, jotka otolliseksi tulevat sille maailmalle ja ylösnousemiselle kuolleista, ei he nai eikä huole;"],[20,36,"Sillä ei he enään kuolla taida; sillä he ovat enkelien kaltaiset, ja he ovat Jumalan lapset, että he ovat ylösnousemisen lapset.","Sillä ei he enään kuolla taida; sillä he ovat enkelien kaltaiset, ja he ovat Jumalan lapset, että he ovat ylösnousemisen lapset."],[20,37,"Mutta että kuolleet ylösnousevat, sen on myös Moses pensaan tykönä osoittanut, kuin hän sanoi Herran Abrahamin Jumalaksi ja Isaakin Jumalaksi ja Jakobin Jumalaksi.","Mutta että kuolleet ylösnousevat, sen on myös Moses pensaan tykönä osoittanut, kuin hän sanoi Herran Abrahamin Jumalaksi ja Isaakin Jumalaksi ja Jakobin Jumalaksi."],[20,38,"Mutta ei Jumala ole kuolleiden Jumala, vaan elävien; sillä kaikki hänelle elävät.","Mutta ei Jumala ole kuolleiden Jumala, vaan elävien; sillä kaikki hänelle elävät."],[20,39,"Niin vastasivat muutamat kirjanoppineista ja sanoivat: Mestari, oikein sinä sanoit.","Niin vastasivat muutamat kirjanoppineista ja sanoivat: Mestari, oikein sinä sanoit."],[20,40,"Ja ei he rohjenneet häneltä mitään enempää kysyä.","Ja ei he rohjenneet häneltä mitään enempää kysyä."],[20,41,"Niin hän sanoi heille: kuinka he sanovat Kristuksen Davidin pojaksi?","Niin hän sanoi heille: kuinka he sanovat Kristuksen Davidin pojaksi?"],[20,42,"Ja David itse sanoo Psalmiraamatussa: Herra sanoi minun Herralleni: istu minun oikialle kädelleni,","Ja David itse sanoo Psalmiraamatussa: Herra sanoi minun Herralleni: istu minun oikialle kädelleni,"],[20,43,"Siihenasti kuin minä panen sinun vihollises sinun jalkais astinlaudaksi.","Siihenasti kuin minä panen sinun vihollises sinun jalkais astinlaudaksi."],[20,44,"Koska siis David kutsuu hänen Herraksensa, kuin hän on hänen Poikansa?","Koska siis David kutsuu hänen Herraksensa, kuin hän on hänen Poikansa?"],[20,45,"Mutta kuin kaikki kansa sen kuuli, sanoi hän opetuslapsillensa:","Mutta kuin kaikki kansa sen kuuli, sanoi hän opetuslapsillensa:"],[20,46,"Kavahtakaat kirjanoppineita, jotka tahtovat käydä pitkissä vaatteissa ja ottavat hyväksi tervehdykset turulla, ja ylimmäiset istuimet synagogissa, ja ylimmäiset siat ehtoollisissa,","Kavahtakaat kirjanoppineita, jotka tahtovat käydä pitkissä vaatteissa ja ottavat hyväksi tervehdykset turulla, ja ylimmäiset istuimet synagogissa, ja ylimmäiset siat ehtoollisissa,"],[20,47,"Jotka syövä leskein huoneet, ja muodoksi pitävät pitkät rukoukset: heidän pitää saaman sitä raskaamman tuomion.","Jotka syövä leskein huoneet, ja muodoksi pitävät pitkät rukoukset: heidän pitää saaman sitä raskaamman tuomion."],[21,1,"Mutta kuin hän katsoi, näki hän rikkaat panevan lahjojansa uhri-arkkuun.","Mutta kuin hän katsoi, näki hän rikkaat panevan lahjojansa uhri-arkkuun."],[21,2,"Hän näki myös köyhän lesken panevan siihen kaksi ropoa.","Hän näki myös köyhän lesken panevan siihen kaksi ropoa."],[21,3,"Ja sanoi: totisesti sanon minä teille: tämä köyhä leski pani enemmän kuin nämät kaikki.","Ja sanoi: totisesti sanon minä teille: tämä köyhä leski pani enemmän kuin nämät kaikki."],[21,4,"Sillä kaikki nämät panivat siitä, mitä heillä liiaksi oli, Jumalan uhriksi, vaan tämä pani köyhyydestänsä kaiken tavaransa, mikä hänellä oli.","Sillä kaikki nämät panivat siitä, mitä heillä liiaksi oli, Jumalan uhriksi, vaan tämä pani köyhyydestänsä kaiken tavaransa, mikä hänellä oli."],[21,5,"Ja kuin muutamat sanoivat hänelle templistä, kuinka kauniilla kivillä ja kappaleilla se kaunistettu oli, niin hän sanoi:","Ja kuin muutamat sanoivat hänelle templistä, kuinka kauniilla kivillä ja kappaleilla se kaunistettu oli, niin hän sanoi:"],[21,6,"Näitäkö te katselette? Ne päivät pitää tuleman, joina ei pidä kiveä kiven päälle jätettämän, jota ei maahan jaoteta.","Näitäkö te katselette? Ne päivät pitää tuleman, joina ei pidä kiveä kiven päälle jätettämän, jota ei maahan jaoteta."],[21,7,"Niin he kysyivät häneltä ja sanoivat: Mestari, koskas nämät tapahtuvat? ja mikä merkki on, koska nämät tulevat?","Niin he kysyivät häneltä ja sanoivat: Mestari, koskas nämät tapahtuvat? ja mikä merkki on, koska nämät tulevat?"],[21,8,"Hän sanoi: katsokaat, ettei teitä petetä; sillä moni tulee minun nimeeni ja sanoo: minä se olen! aika on kyllä läsnä, älkäät kuitenkaan heitä seuratko.","Hän sanoi: katsokaat, ettei teitä petetä; sillä moni tulee minun nimeeni ja sanoo: minä se olen! aika on kyllä läsnä, älkäät kuitenkaan heitä seuratko."],[21,9,"Mutta kuin te kuulette sotia ja kapinoita, niin älkäät peljästykö; sillä nämät pitää ensin tapahtuman, vaan ei kohta loppu ole.","Mutta kuin te kuulette sotia ja kapinoita, niin älkäät peljästykö; sillä nämät pitää ensin tapahtuman, vaan ei kohta loppu ole."],[21,10,"Niin hän sanoi heille: kansa nousee kansaa vastaan, ja valtakunta valtakuntaa vastaan.","Niin hän sanoi heille: kansa nousee kansaa vastaan, ja valtakunta valtakuntaa vastaan."],[21,11,"Ja suuret maan vapistukset pitä joka paikassa tuleman, nälkä ja rutto, kauhistukset ja suuret ihmeet taivaasta tapahtuvat.","Ja suuret maan vapistukset pitä joka paikassa tuleman, nälkä ja rutto, kauhistukset ja suuret ihmeet taivaasta tapahtuvat."],[21,12,"Mutta ennen näitä kaikkia heittävät he kätensä teidän päällenne, vainoovat ja antavat ylön teitä synagogiin ja vankiuteen, ja vetävät teitä kuningasten ja esimiesten eteen, minun nimeni tähden.","Mutta ennen näitä kaikkia heittävät he kätensä teidän päällenne, vainoovat ja antavat ylön teitä synagogiin ja vankiuteen, ja vetävät teitä kuningasten ja esimiesten eteen, minun nimeni tähden."],[21,13,"Mutta se tapahtuu teille todistukseksi.","Mutta se tapahtuu teille todistukseksi."],[21,14,"Niin pankaat nyt se teidän sydämeenne, ettette ennen ajattelisi, kuinka teidän pitää edestänne vastaaman:","Niin pankaat nyt se teidän sydämeenne, ettette ennen ajattelisi, kuinka teidän pitää edestänne vastaaman:"],[21,15,"Sillä minä annan teille suun ja viisauden, jota ei he voi puhua vastaan eikä seisoa vastaan, kaikki jotka teitä vastaan ovat.","Sillä minä annan teille suun ja viisauden, jota ei he voi puhua vastaan eikä seisoa vastaan, kaikki jotka teitä vastaan ovat."],[21,16,"Niin te myös annetaan ylön vanhimmilta, veljiltä, langoilta ja ystäviltä, ja muutamat teistä he tappavat,","Niin te myös annetaan ylön vanhimmilta, veljiltä, langoilta ja ystäviltä, ja muutamat teistä he tappavat,"],[21,17,"Ja te tulette vihattaviksi kaikilta, minun nimeni tähden.","Ja te tulette vihattaviksi kaikilta, minun nimeni tähden."],[21,18,"Vaan ei hiuskarvakaan pidä teidän päästänne hukkuman.","Vaan ei hiuskarvakaan pidä teidän päästänne hukkuman."],[21,19,"Pitäkäät teidän sielunne kärsivällisyydessä.","Pitäkäät teidän sielunne kärsivällisyydessä."],[21,20,"Mutta kuin te näette Jerusalemin sotaväeltä piiritettävän, niin tietäkäät, että hänen perikatonsa on lähestynyt.","Mutta kuin te näette Jerusalemin sotaväeltä piiritettävän, niin tietäkäät, että hänen perikatonsa on lähestynyt."],[21,21,"Silloin ne, jotka Juudeassa ovat, paetkaan vuorille, ja jotka hänen keskellänsä ovat, ne lähtekään sieltä ulos, ja jotka maalla ovat, älkään häneen menkö sisälle.","Silloin ne, jotka Juudeassa ovat, paetkaan vuorille, ja jotka hänen keskellänsä ovat, ne lähtekään sieltä ulos, ja jotka maalla ovat, älkään häneen menkö sisälle."],[21,22,"Sillä ne ovat kostopäivät, että kaikki täytettäisiin, mitkä kirjoitetut ovat.","Sillä ne ovat kostopäivät, että kaikki täytettäisiin, mitkä kirjoitetut ovat."],[21,23,"Mutta voi raskaita ja imettäväisiä niinä päivinä! Sillä suuri vaiva pitää maan päällä oleman ja viha tämän kansan päällä.","Mutta voi raskaita ja imettäväisiä niinä päivinä! Sillä suuri vaiva pitää maan päällä oleman ja viha tämän kansan päällä."],[21,24,"Ja heidän pitää lankeeman miekan terään, ja he viedään vangiksi kaikkinaisen kansan sekaan. Ja Jerusalem pitää tallattaman pakanoilta, siihen asti kuin pakanain aika täytetään.","Ja heidän pitää lankeeman miekan terään, ja he viedään vangiksi kaikkinaisen kansan sekaan. Ja Jerusalem pitää tallattaman pakanoilta, siihen asti kuin pakanain aika täytetään."],[21,25,"Ja merkit pitää oleman auringossa ja kuussa ja tähdissä, ja maassa kansalla ahdistus epäilyksen tähden. Ja meri ja aallot pitää pauhaaman.","Ja merkit pitää oleman auringossa ja kuussa ja tähdissä, ja maassa kansalla ahdistus epäilyksen tähden. Ja meri ja aallot pitää pauhaaman."],[21,26,"Ja ihmiset maassa pitää nääntymän pelvon ja odottamisen tähden niitä, mitkä maan piirin päälle tulevat; sillä taivaan voimat pitää liikutettaman.","Ja ihmiset maassa pitää nääntymän pelvon ja odottamisen tähden niitä, mitkä maan piirin päälle tulevat; sillä taivaan voimat pitää liikutettaman."],[21,27,"Ja silloin heidän pitää näkemän Ihmisen Pojan tulevan pilvissä suurella voimalla ja kunnialla.","Ja silloin heidän pitää näkemän Ihmisen Pojan tulevan pilvissä suurella voimalla ja kunnialla."],[21,28,"Mutta kuin nämät rupeevat tapahtumaan, niin katsokaat, ja nostakaat päänne ylös; sillä teidän lunastuksenne silloin lähestyy.","Mutta kuin nämät rupeevat tapahtumaan, niin katsokaat, ja nostakaat päänne ylös; sillä teidän lunastuksenne silloin lähestyy."],[21,29,"Ja hän sanoi heille vertauksen: katsokaat fikunapuuta ja kaikkia puita.","Ja hän sanoi heille vertauksen: katsokaat fikunapuuta ja kaikkia puita."],[21,30,"Kuin ne jo puhkeevat, niin te näette ja itse teistänne ymmärrätte, että suvi on jo läsnä.","Kuin ne jo puhkeevat, niin te näette ja itse teistänne ymmärrätte, että suvi on jo läsnä."],[21,31,"Niin myös te, kuin te näette nämät tapahtuvan, tietäkäät, että Jumalan valtakunta on läsnä.","Niin myös te, kuin te näette nämät tapahtuvan, tietäkäät, että Jumalan valtakunta on läsnä."],[21,32,"Totisesti minä sanon teille: ei tämän sukukunnan pidä suinkaan hukkuman, siihenasti kuin nämät kaikki tapahtuvat.","Totisesti minä sanon teille: ei tämän sukukunnan pidä suinkaan hukkuman, siihenasti kuin nämät kaikki tapahtuvat."],[21,33,"Taivas ja maa on hukkuva, vaan minun sanani ei pidä ikänä hukkaantuman.","Taivas ja maa on hukkuva, vaan minun sanani ei pidä ikänä hukkaantuman."],[21,34,"Mutta kavahtakaat, ettei teidän sydämenne koskaan raskauteta ylönsyömisestä ja juopumisesta ja elatuksen murheesta, ja se päivä tulee äkisti teidän päällenne.","Mutta kavahtakaat, ettei teidän sydämenne koskaan raskauteta ylönsyömisestä ja juopumisesta ja elatuksen murheesta, ja se päivä tulee äkisti teidän päällenne."],[21,35,"Sillä se tulee niinkuin paula kaikkein ylitse, jotka koko maan päällä asuvat.","Sillä se tulee niinkuin paula kaikkein ylitse, jotka koko maan päällä asuvat."],[21,36,"Sentähden valvokaat ja aina rukoilkaat, että te mahdolliset olisitte kaikkia näit välttämään, jotka pitää tapahtuman, ja seisomaan Ihmisen Pojan edessä.","Sentähden valvokaat ja aina rukoilkaat, että te mahdolliset olisitte kaikkia näit välttämään, jotka pitää tapahtuman, ja seisomaan Ihmisen Pojan edessä."],[21,37,"Ja hän opetti päivällä templissä, mutta yöllä meni hän ulos ja oli yötä vuorella, joka kutsutaan Öljymäeksi.","Ja hän opetti päivällä templissä, mutta yöllä meni hän ulos ja oli yötä vuorella, joka kutsutaan Öljymäeksi."],[21,38,"Ja kaikki kansa tuli varhain hänen tykönsä templiin, häntä kuulemaan.","Ja kaikki kansa tuli varhain hänen tykönsä templiin, häntä kuulemaan."],[22,1,"Niin lähestyi makian leivän juhlapäivä, joka pääsiäiseksi kutsutaan.","Niin lähestyi makian leivän juhlapäivä, joka pääsiäiseksi kutsutaan."],[22,2,"Ja ylimmäiset papit ja kirjanoppineet etsivät, kuinka he olisivat hänen saaneet tappaa. Mutta he pelkäsivät kansaa.","Ja ylimmäiset papit ja kirjanoppineet etsivät, kuinka he olisivat hänen saaneet tappaa. Mutta he pelkäsivät kansaa."],[22,3,"Niin saatana oli mennyt Juudaan sisälle, jonka liikanimi oli Iskariot, joka oli kahdentoistakymmenen luvusta.","Niin saatana oli mennyt Juudaan sisälle, jonka liikanimi oli Iskariot, joka oli kahdentoistakymmenen luvusta."],[22,4,"Ja hän meni pois ja puhutteli ylimmäisiä pappeja ja päämiehiä, kuin hän oli hänen heille pettävä.","Ja hän meni pois ja puhutteli ylimmäisiä pappeja ja päämiehiä, kuin hän oli hänen heille pettävä."],[22,5,"Ja he ihastuivat ja lupasivat hänelle rahaa.","Ja he ihastuivat ja lupasivat hänelle rahaa."],[22,6,"Ja hän lupasi sen heille, ja etsi soveliasta aikaa, saadaksensa häntä pettää ilman hasuta.","Ja hän lupasi sen heille, ja etsi soveliasta aikaa, saadaksensa häntä pettää ilman hasuta."],[22,7,"Niin makian leivän päivä tuli, jona pääsiäislammas piti teurastettaman,","Niin makian leivän päivä tuli, jona pääsiäislammas piti teurastettaman,"],[22,8,"Ja hän lähetti Pietarin ja Johanneksen, sanoen: menkäät valmistamaan meille pääsiäislammas syödäksemme.","Ja hän lähetti Pietarin ja Johanneksen, sanoen: menkäät valmistamaan meille pääsiäislammas syödäksemme."],[22,9,"Niin he sanoivat hänelle: kussas tahdot meitä valmistamaan?","Niin he sanoivat hänelle: kussas tahdot meitä valmistamaan?"],[22,10,"Hän sanoi heille: katso, kuin te kaupunkiin tulette sisälle, kohtaa teitä ihminen, kantain vesiastiaa: seuratkaat häntä siihen huoneesen, johonka hän menee.","Hän sanoi heille: katso, kuin te kaupunkiin tulette sisälle, kohtaa teitä ihminen, kantain vesiastiaa: seuratkaat häntä siihen huoneesen, johonka hän menee."],[22,11,"Ja sanokaat sen huoneen perheenisännälle: Mestari sanoo sinulle: kussa on maja, jossa minä syön pääsiäislampaan opetuslasteni kanssa?","Ja sanokaat sen huoneen perheenisännälle: Mestari sanoo sinulle: kussa on maja, jossa minä syön pääsiäislampaan opetuslasteni kanssa?"],[22,12,"Ja hän osoittaa teille suuren salin rakennetun; valmistakaat siellä.","Ja hän osoittaa teille suuren salin rakennetun; valmistakaat siellä."],[22,13,"Niin he menivät ja löysivät niinkuin hän heille sanonut oli, ja valmistivat pääsiäislampaan.","Niin he menivät ja löysivät niinkuin hän heille sanonut oli, ja valmistivat pääsiäislampaan."],[22,14,"Ja kuin jo aika tullut oli, istui hän pöydän tykönä ja kaksitoistakymmentä apostolia hänen kanssansa.","Ja kuin jo aika tullut oli, istui hän pöydän tykönä ja kaksitoistakymmentä apostolia hänen kanssansa."],[22,15,"Ja hän sanoi heille: minä olen halulla halainnut syödä tätä pääsiäislammasta teidän kanssanne, ennekuin minä kärsin.","Ja hän sanoi heille: minä olen halulla halainnut syödä tätä pääsiäislammasta teidän kanssanne, ennekuin minä kärsin."],[22,16,"Sillä minä sanon teille, etten minä suinkaan silleen siitä syö, siihenasti kuin se täytetään Jumalan valtakunnassa.","Sillä minä sanon teille, etten minä suinkaan silleen siitä syö, siihenasti kuin se täytetään Jumalan valtakunnassa."],[22,17,"Ja hän otti kalkin, kiitti, ja sanoi: ottakaat ja jakakaat keskenänne.","Ja hän otti kalkin, kiitti, ja sanoi: ottakaat ja jakakaat keskenänne."],[22,18,"Sillä minä sanon teille, etten minä suinkaan juo viinapuun hedelmää, siihenasti kuin Jumalan valtakunta tulee.","Sillä minä sanon teille, etten minä suinkaan juo viinapuun hedelmää, siihenasti kuin Jumalan valtakunta tulee."],[22,19,"Ja hän otti leivän, kiitti ja mursi, ja antoi heille, sanoen: tämä on minun ruumiini, joka teidän edestänne annetaan: se tehkäät minun muistokseni;","Ja hän otti leivän, kiitti ja mursi, ja antoi heille, sanoen: tämä on minun ruumiini, joka teidän edestänne annetaan: se tehkäät minun muistokseni;"],[22,20,"Niin myös kalkin ehtoollisen jälkeen, sanoen: tämä kalkki on uusi Testamentti, minun veressäni, joka teidän edestänne vuodatetaan.","Niin myös kalkin ehtoollisen jälkeen, sanoen: tämä kalkki on uusi Testamentti, minun veressäni, joka teidän edestänne vuodatetaan."],[22,21,"Kuitenkin, katso, minun pettäjäni käsi on minun kanssani pöydällä.","Kuitenkin, katso, minun pettäjäni käsi on minun kanssani pöydällä."],[22,22,"Ja tosin Ihmisen Poika menee niinkuin päätetty on: kuitenkin voi sitä ihmistä, jolta hän petetään!","Ja tosin Ihmisen Poika menee niinkuin päätetty on: kuitenkin voi sitä ihmistä, jolta hän petetään!"],[22,23,"Ja he rupesivat kyselemään keskenänsä: kuka olis se heistä, joka sen tekevä olis?","Ja he rupesivat kyselemään keskenänsä: kuka olis se heistä, joka sen tekevä olis?"],[22,24,"Mutta heidän välillänsä tuli myös riita, kuka heistä näkyis suurin olevan.","Mutta heidän välillänsä tuli myös riita, kuka heistä näkyis suurin olevan."],[22,25,"Niin hän sanoi heille: kansain kuninkaat vallitsevat heitä, ja joilla valta on heidän ylitsensä, ne kutsutaan armollisiksi herroiksi.","Niin hän sanoi heille: kansain kuninkaat vallitsevat heitä, ja joilla valta on heidän ylitsensä, ne kutsutaan armollisiksi herroiksi."],[22,26,"Mutta ette te niin: vaan joka teistä suurin on, se olkoon niinkuin nuorin, ja joka ylimmäinen on, se olkoon niinkuin se, joka palvelee.","Mutta ette te niin: vaan joka teistä suurin on, se olkoon niinkuin nuorin, ja joka ylimmäinen on, se olkoon niinkuin se, joka palvelee."],[22,27,"Sillä kumpi suurempi on: se joka atrioitsee, taikka se joka palvelee? eikö se joka atrioitsee? mutta minä olen teidän keskellänne niinkuin se, joka palvelee.","Sillä kumpi suurempi on: se joka atrioitsee, taikka se joka palvelee? eikö se joka atrioitsee? mutta minä olen teidän keskellänne niinkuin se, joka palvelee."],[22,28,"Mutta te olette ne, jotka minun kiusauksissani minun kanssani pysyitte.","Mutta te olette ne, jotka minun kiusauksissani minun kanssani pysyitte."],[22,29,"Ja minä säädin teille, niinkuin minun Isäni sääsi minulle, valtakunnan:","Ja minä säädin teille, niinkuin minun Isäni sääsi minulle, valtakunnan:"],[22,30,"Että teidän pitää syömän ja juoman minun pöydälläni minun valtakunnassani, ja istuman istuimilla, ja tuomitseman kaksitoistakymmentä Israelin sukukuntaa.","Että teidän pitää syömän ja juoman minun pöydälläni minun valtakunnassani, ja istuman istuimilla, ja tuomitseman kaksitoistakymmentä Israelin sukukuntaa."],[22,31,"Niin sanoi myös Herra: Simon, Simon, katso, saatana on teitä pyytänyt seuloaksensa niinkuin nisuja.","Niin sanoi myös Herra: Simon, Simon, katso, saatana on teitä pyytänyt seuloaksensa niinkuin nisuja."],[22,32,"Vaan minä rukoilin sinun edestäs, ettei sinun uskos puuttuman pidä. Ja kuin sinä kerran palajat, niin vahvista veljiäs.","Vaan minä rukoilin sinun edestäs, ettei sinun uskos puuttuman pidä. Ja kuin sinä kerran palajat, niin vahvista veljiäs."],[22,33,"Niin hän sanoi hänelle: Herra, minä olen valmis sinun kanssas sekä vankiuteen että kuolemaan menemään.","Niin hän sanoi hänelle: Herra, minä olen valmis sinun kanssas sekä vankiuteen että kuolemaan menemään."],[22,34,"Mutta hän sanoi: Pietari, minä sanon sinulle, ei laula tänäpänä kukko ennen kuin sinä kolmasti kiellät tuntevas minua.","Mutta hän sanoi: Pietari, minä sanon sinulle, ei laula tänäpänä kukko ennen kuin sinä kolmasti kiellät tuntevas minua."],[22,35,"Ja hän sanoi heille: kuin minä lähetin teidät ilman säkkiä ja kukkaroa ja kenkiä, puuttuiko teiltä mitään? He sanoivat: ei mitään.","Ja hän sanoi heille: kuin minä lähetin teidät ilman säkkiä ja kukkaroa ja kenkiä, puuttuiko teiltä mitään? He sanoivat: ei mitään."],[22,36,"Niin hän sanoi heille: vaan nyt, jolla säkki on, ottakoon sen, niin myös kukkaron; ja jolla ei ole, se myykään hameensa ja ostakaan miekan.","Niin hän sanoi heille: vaan nyt, jolla säkki on, ottakoon sen, niin myös kukkaron; ja jolla ei ole, se myykään hameensa ja ostakaan miekan."],[22,37,"Sillä minä sanon teille: vielä sekin mikä kirjoitettu on, pitää minussa täytettämän: hän on pahantekiäin sekaan luettu; sillä ne, mitkä minusta kirjoitetut ovat, pitää loppuman.","Sillä minä sanon teille: vielä sekin mikä kirjoitettu on, pitää minussa täytettämän: hän on pahantekiäin sekaan luettu; sillä ne, mitkä minusta kirjoitetut ovat, pitää loppuman."],[22,38,"Niin he sanoivat: Herra, katso, tässä on kaksi miekkaa. Hän sanoi heille: kyllä siinä on.","Niin he sanoivat: Herra, katso, tässä on kaksi miekkaa. Hän sanoi heille: kyllä siinä on."],[22,39,"Ja hän läksi ulos ja meni, niinkuin hänen tapansa oli, Öljymäelle; niin seurasivat myös häntä hänen opetuslapsensa.","Ja hän läksi ulos ja meni, niinkuin hänen tapansa oli, Öljymäelle; niin seurasivat myös häntä hänen opetuslapsensa."],[22,40,"Ja kuin hän siihen paikkaan tuli, sanoi hän heille: rukoilkaat, ettette tulisi kiusaukseen.","Ja kuin hän siihen paikkaan tuli, sanoi hän heille: rukoilkaat, ettette tulisi kiusaukseen."],[22,41,"Ja hän erkani heistä lähes kivellä heittää ja laski polvillensa, rukoili,","Ja hän erkani heistä lähes kivellä heittää ja laski polvillensa, rukoili,"],[22,42,"Sanoen: Isä, jos sinä tahdot, niin ota pois minulta tämä kalkki, kuitenkin ei minun tahtoni, mutta sinun olkoon.","Sanoen: Isä, jos sinä tahdot, niin ota pois minulta tämä kalkki, kuitenkin ei minun tahtoni, mutta sinun olkoon."],[22,43,"Niin enkeli taivaasta ilmestyi hänelle ja vahvisti häntä.","Niin enkeli taivaasta ilmestyi hänelle ja vahvisti häntä."],[22,44,"Ja kuin hän sangen suuressa ahdistuksessa oli, rukoili hän hartaammin. Ja oli hänen hikensä niinkuin verenpisarat, jotka maan päälle putosivat.","Ja kuin hän sangen suuressa ahdistuksessa oli, rukoili hän hartaammin. Ja oli hänen hikensä niinkuin verenpisarat, jotka maan päälle putosivat."],[22,45,"Ja kuin hän nousi rukoilemasta ja tuli opetuslastensa tykö, löysi hän ne murheen tähden makaamasta,","Ja kuin hän nousi rukoilemasta ja tuli opetuslastensa tykö, löysi hän ne murheen tähden makaamasta,"],[22,46,"Ja hän sanoi heille: mitä te makaatte? nouskaat ja rukoilkaat, ettette kiusaukseen lankeaisi.","Ja hän sanoi heille: mitä te makaatte? nouskaat ja rukoilkaat, ettette kiusaukseen lankeaisi."],[22,47,"Vielä hänen puhuissansa, katso, joukko ja se, joka kutsuttiin Juudas, yksi kahdestatoistakymmenestä, kävi heidän edellänsä, ja lähestyi Jesusta suuta antamaan hänen.","Vielä hänen puhuissansa, katso, joukko ja se, joka kutsuttiin Juudas, yksi kahdestatoistakymmenestä, kävi heidän edellänsä, ja lähestyi Jesusta suuta antamaan hänen."],[22,48,"Niin Jesus sanoi hänelle: Juudas, suun antamisellako sinä Ihmisen Pojan petät?","Niin Jesus sanoi hänelle: Juudas, suun antamisellako sinä Ihmisen Pojan petät?"],[22,49,"Kuin ne, jotka hänen ympärillänsä olivat, näkivät, mitä tuleva oli, sanoivat he hänelle: Herra, emmekö me lyö miekalla?","Kuin ne, jotka hänen ympärillänsä olivat, näkivät, mitä tuleva oli, sanoivat he hänelle: Herra, emmekö me lyö miekalla?"],[22,50,"Ja yksi heistä löi pappein päämiehen palveliaa ja hakkasi pois hänen oikian korvansa.","Ja yksi heistä löi pappein päämiehen palveliaa ja hakkasi pois hänen oikian korvansa."],[22,51,"Mutta Jesus vastaten sanoi: sallikaat tähän asti tulla. Ja kuin hän rupesi hänen korvaansa, paransi hän sen.","Mutta Jesus vastaten sanoi: sallikaat tähän asti tulla. Ja kuin hän rupesi hänen korvaansa, paransi hän sen."],[22,52,"Mutta Jesus sanoi niille, jotka häntä vastaan olivat tulleet, ylimmäisille papeille ja templin haltioille ja vanhimmille: niinkuin ryövärin tykö te läksitte miekoilla ja seipäillä.","Mutta Jesus sanoi niille, jotka häntä vastaan olivat tulleet, ylimmäisille papeille ja templin haltioille ja vanhimmille: niinkuin ryövärin tykö te läksitte miekoilla ja seipäillä."],[22,53,"Minä olin joka päivä teidän kanssanne templissä, ja ette ojentaneet kättä minun päälleni; mutta tämä on teidän hetkenne ja pimeyden valta.","Minä olin joka päivä teidän kanssanne templissä, ja ette ojentaneet kättä minun päälleni; mutta tämä on teidän hetkenne ja pimeyden valta."],[22,54,"Niin he kiinni ottivat hänen ja taluttivat, ja veivät hänen sisälle ylimmäisen papin huoneesen. Mutta Pietari seurasi taampana.","Niin he kiinni ottivat hänen ja taluttivat, ja veivät hänen sisälle ylimmäisen papin huoneesen. Mutta Pietari seurasi taampana."],[22,55,"Ja niin he virittivät valkian keskelle kartanoa, ja ynnä yhdessä istuivat, istui myös Pietari heidän seassansa.","Ja niin he virittivät valkian keskelle kartanoa, ja ynnä yhdessä istuivat, istui myös Pietari heidän seassansa."],[22,56,"Mutta kuin yksi piika näki hänen valkian tykönä istuvan, katsoi hän hänen päällensä, ja sanoi: tämä oli myös hänen kanssansa.","Mutta kuin yksi piika näki hänen valkian tykönä istuvan, katsoi hän hänen päällensä, ja sanoi: tämä oli myös hänen kanssansa."],[22,57,"Vaan hän kielsi hänen ja sanoi: vaimo, en minä tunne häntä.","Vaan hän kielsi hänen ja sanoi: vaimo, en minä tunne häntä."],[22,58,"Ja vähän hetken perästä näki toinen hänen, ja sanoi: sinä myös olet yksi heistä. Pietari sanoi: ihminen, en ole.","Ja vähän hetken perästä näki toinen hänen, ja sanoi: sinä myös olet yksi heistä. Pietari sanoi: ihminen, en ole."],[22,59,"Ja lähes yhden hetken perästä todisti myös toinen, sanoen: totisesti tämä oli myös hänen kanssansa; sillä hän on Galileasta.","Ja lähes yhden hetken perästä todisti myös toinen, sanoen: totisesti tämä oli myös hänen kanssansa; sillä hän on Galileasta."],[22,60,"Niin Pietari sanoi: ihminen, en minä tiedä, mitäs sanot. Ja kohta, vielä hänen puhuissansa, lauloi kukko.","Niin Pietari sanoi: ihminen, en minä tiedä, mitäs sanot. Ja kohta, vielä hänen puhuissansa, lauloi kukko."],[22,61,"Ja Herra käänsi itsensä ja katsoi Pietarin päälle, ja Pietari muisti Herran puheen, kuin hän hänelle sanoi: ennenkuin kukko laulaa, kolmasti sinä minun kiellät.","Ja Herra käänsi itsensä ja katsoi Pietarin päälle, ja Pietari muisti Herran puheen, kuin hän hänelle sanoi: ennenkuin kukko laulaa, kolmasti sinä minun kiellät."],[22,62,"Ja Pietari meni ulos ja itki katkerasti.","Ja Pietari meni ulos ja itki katkerasti."],[22,63,"Mutta miehet, jotka Jesusta kiinni pitivät, pilkkasivat häntä ja löivät häntä,","Mutta miehet, jotka Jesusta kiinni pitivät, pilkkasivat häntä ja löivät häntä,"],[22,64,"Peittivät hänen silmänsä, ja löivät häntä poskelle, ja kysyivät häneltä, sanoen: arvaa, kuka se on, joka sinua löi.","Peittivät hänen silmänsä, ja löivät häntä poskelle, ja kysyivät häneltä, sanoen: arvaa, kuka se on, joka sinua löi."],[22,65,"Ja paljon muuta pilkkaa sanoivat he häntä vastaan.","Ja paljon muuta pilkkaa sanoivat he häntä vastaan."],[22,66,"Ja kuin päivä tuli, kokoontuivat kansan vanhimmat ja ylimmäiset papit ja kirjanoppineet ja veivät hänen oikeutensa eteen,","Ja kuin päivä tuli, kokoontuivat kansan vanhimmat ja ylimmäiset papit ja kirjanoppineet ja veivät hänen oikeutensa eteen,"],[22,67,"Sanoen: oletkos Kristus? sano meille. Niin hän sanoi heille: jos minä sanon teille, ette usko,","Sanoen: oletkos Kristus? sano meille. Niin hän sanoi heille: jos minä sanon teille, ette usko,"],[22,68,"Ja jos minä myös kysyn, niin ette vastaa minua, ette myös päästä minua.","Ja jos minä myös kysyn, niin ette vastaa minua, ette myös päästä minua."],[22,69,"Tästedes istuu Ihmisen Poika Jumalan voiman oikialla kädellä.","Tästedes istuu Ihmisen Poika Jumalan voiman oikialla kädellä."],[22,70,"Niin he sanoivat kaikki: sinä olet siis Jumalan Poika? sanoi hän heille: tepä sen sanotte, että minä olen.","Niin he sanoivat kaikki: sinä olet siis Jumalan Poika? sanoi hän heille: tepä sen sanotte, että minä olen."],[22,71,"Niin he sanoivat: mitä me silleen todistusta tarvitsemme, sillä me olemme sen kuulleet hänen omasta suustansa.","Niin he sanoivat: mitä me silleen todistusta tarvitsemme, sillä me olemme sen kuulleet hänen omasta suustansa."],[23,1,"Ja kaikki heidän joukkonsa nousi ylös, ja he veivät hänen Pilatuksen tykö.","Ja kaikki heidän joukkonsa nousi ylös, ja he veivät hänen Pilatuksen tykö."],[23,2,"Ja he rupesivat kantamaan hänen päällensä, sanoen: tämän me löysimme kansaa viettelevän ja kieltävän keisarille veroa antamasta ja sanovan itsensä olevan kuninkaan Kristuksen.","Ja he rupesivat kantamaan hänen päällensä, sanoen: tämän me löysimme kansaa viettelevän ja kieltävän keisarille veroa antamasta ja sanovan itsensä olevan kuninkaan Kristuksen."],[23,3,"Niin Pilatus kysyi häneltä, sanoen: oletkos Juudalaisten kuningas? Hän vastasi häntä ja sanoi: sinäpä sen sanot.","Niin Pilatus kysyi häneltä, sanoen: oletkos Juudalaisten kuningas? Hän vastasi häntä ja sanoi: sinäpä sen sanot."],[23,4,"Mutta Pilatus sanoi pappein päämiehille ja kansalle: en minä löydä yhtään vikaa tässä ihmisessä.","Mutta Pilatus sanoi pappein päämiehille ja kansalle: en minä löydä yhtään vikaa tässä ihmisessä."],[23,5,"Mutta he kävivät päälle, sanoen: hän kehoittaa kansan, opettain koko Juudeassa, ja on ruvennut Galileasta hamaan tähän asti.","Mutta he kävivät päälle, sanoen: hän kehoittaa kansan, opettain koko Juudeassa, ja on ruvennut Galileasta hamaan tähän asti."],[23,6,"Mutta kuin Pilatus kuuli Galileaa mainittavan, kysyi hän, josko hän Galileasta oli.","Mutta kuin Pilatus kuuli Galileaa mainittavan, kysyi hän, josko hän Galileasta oli."],[23,7,"Ja kuin hän ymmärsi, että hän Herodeksen läänistä oli, lähetti hän hänen Herodeksen tykö, joka myös silloin oli Jerusalemissa.","Ja kuin hän ymmärsi, että hän Herodeksen läänistä oli, lähetti hän hänen Herodeksen tykö, joka myös silloin oli Jerusalemissa."],[23,8,"Kuin Herodes näki Jesuksen, ihastui hän sangen suuresti; sillä hän oli jo kauvan aikaa häntä halainnut nähdäksensä, että hän oli paljon hänestä kuullut, ja toivoi häneltä jonkun ihmeen näkevänsä,","Kuin Herodes näki Jesuksen, ihastui hän sangen suuresti; sillä hän oli jo kauvan aikaa häntä halainnut nähdäksensä, että hän oli paljon hänestä kuullut, ja toivoi häneltä jonkun ihmeen näkevänsä,"],[23,9,"Ja kysyi häneltä moninaisista; mutta ei hän mitään häntä vastannut.","Ja kysyi häneltä moninaisista; mutta ei hän mitään häntä vastannut."],[23,10,"Niin ylimmäiset papit ja kirjanoppineet seisoivat ja kantoivat kovin hänen päällensä.","Niin ylimmäiset papit ja kirjanoppineet seisoivat ja kantoivat kovin hänen päällensä."],[23,11,"Mutta Herodes huovinensa katsoi hänen ylön, ja pilkkasi häntä, pani hänen päällensä valkian vaatteen, ja lähetti jälleen Pilatuksen tykö.","Mutta Herodes huovinensa katsoi hänen ylön, ja pilkkasi häntä, pani hänen päällensä valkian vaatteen, ja lähetti jälleen Pilatuksen tykö."],[23,12,"Sinä päivänä tuli Pilatus ja Herodes ystäviksi keskenänsä; sillä he olivat ennen vihamiehet olleet keskenänsä.","Sinä päivänä tuli Pilatus ja Herodes ystäviksi keskenänsä; sillä he olivat ennen vihamiehet olleet keskenänsä."],[23,13,"Niin Pilatus kutsui kokoon ylimmäiset papit ja valtamiehet ja kansan.","Niin Pilatus kutsui kokoon ylimmäiset papit ja valtamiehet ja kansan."],[23,14,"Ja sanoi heille: te olette tämän ihmisen minulle tuoneet niinkuin kansan häiritsiän, ja katso, minä olen häntä tutkinut teidän edessänne ja en löydä yhtään vikaa tässä ihmisessä, joista te kannatte hänen päällensä,","Ja sanoi heille: te olette tämän ihmisen minulle tuoneet niinkuin kansan häiritsiän, ja katso, minä olen häntä tutkinut teidän edessänne ja en löydä yhtään vikaa tässä ihmisessä, joista te kannatte hänen päällensä,"],[23,15,"Eikä Herodeskaan; sillä minä lähetin teidät hänen tykönsä, ja katso, ei häneltä yhtään hengen rikosta ole tehty.","Eikä Herodeskaan; sillä minä lähetin teidät hänen tykönsä, ja katso, ei häneltä yhtään hengen rikosta ole tehty."],[23,16,"Sentähden tahdon minä hänen rangaistuna päästää.","Sentähden tahdon minä hänen rangaistuna päästää."],[23,17,"Mutta hänen piti joka juhlana päästämän heille yhden vallallensa.","Mutta hänen piti joka juhlana päästämän heille yhden vallallensa."],[23,18,"Niin koko joukko huusi ja sanoi: ota tämä pois, ja päästä meille Barabbas,","Niin koko joukko huusi ja sanoi: ota tämä pois, ja päästä meille Barabbas,"],[23,19,"Joka oli kapinan ja miestapoin tähden, kuin kaupungissa tapahtunut oli, vankiuteen heitetty.","Joka oli kapinan ja miestapoin tähden, kuin kaupungissa tapahtunut oli, vankiuteen heitetty."],[23,20,"Niin Pilatus taas puhui heille ja tahtoi Jesuksen päästää.","Niin Pilatus taas puhui heille ja tahtoi Jesuksen päästää."],[23,21,"Mutta he huusivat sitä vastaan, sanoen: ristiinnaulitse, ristiinnaulitse häntä!","Mutta he huusivat sitä vastaan, sanoen: ristiinnaulitse, ristiinnaulitse häntä!"],[23,22,"Mutta hän sanoi kolmannen kerran heille: mitäs hän pahaa teki? en minä löydä yhtään hengenrikosta hänessä: sentähden tahdon minä hänen rangaistuna päästää.","Mutta hän sanoi kolmannen kerran heille: mitäs hän pahaa teki? en minä löydä yhtään hengenrikosta hänessä: sentähden tahdon minä hänen rangaistuna päästää."],[23,23,"Mutta he kävivät päälle suurella äänellä, pyytäin häntä ristiinnaulittaa. Ja heidän ja ylimmäisten pappein ääni sai vallan.","Mutta he kävivät päälle suurella äänellä, pyytäin häntä ristiinnaulittaa. Ja heidän ja ylimmäisten pappein ääni sai vallan."],[23,24,"Ja Pilatus tuomitsi heidän anomisensa jälkeen,","Ja Pilatus tuomitsi heidän anomisensa jälkeen,"],[23,25,"Ja päästi sen heille, joka kapinan ja miestapon tähden oli vankiuteen heitetty, jota he anoivat; mutta Jesuksen antoi hän heidän haltuunsa.","Ja päästi sen heille, joka kapinan ja miestapon tähden oli vankiuteen heitetty, jota he anoivat; mutta Jesuksen antoi hän heidän haltuunsa."],[23,26,"Ja kuin he hänen veivät ulos, käsittivät he yhden, Simonin Kyrenistä, joka maalta tuli, ja panivat hänen päällensä ristin, sitä Jesuksen jäljessä kantamaan.","Ja kuin he hänen veivät ulos, käsittivät he yhden, Simonin Kyrenistä, joka maalta tuli, ja panivat hänen päällensä ristin, sitä Jesuksen jäljessä kantamaan."],[23,27,"Mutta häntä seurasi suuri joukko kansaa ja vaimoja, jotka häntä itkivät ja parkuivat.","Mutta häntä seurasi suuri joukko kansaa ja vaimoja, jotka häntä itkivät ja parkuivat."],[23,28,"Niin Jesus käänsi itsensä heidän puoleensa, ja sanoi: Jerusalemin tyttäret, älkäät minua itkekö, vaan itkekäät itse teitänne ja teidän lapsianne;","Niin Jesus käänsi itsensä heidän puoleensa, ja sanoi: Jerusalemin tyttäret, älkäät minua itkekö, vaan itkekäät itse teitänne ja teidän lapsianne;"],[23,29,"Sillä katso, päivät tulevat, joina he sanovat: autuaat ovat hedelmättömät, ja ne kohdat, jotka ei synnyttäneet, ja ne nisät, jotka ei imettäneet.","Sillä katso, päivät tulevat, joina he sanovat: autuaat ovat hedelmättömät, ja ne kohdat, jotka ei synnyttäneet, ja ne nisät, jotka ei imettäneet."],[23,30,"Silloin he rupeevat sanomaan vuorille: langetkaat meidän päällemme, ja kukkuloille: peittäkäät meitä.","Silloin he rupeevat sanomaan vuorille: langetkaat meidän päällemme, ja kukkuloille: peittäkäät meitä."],[23,31,"Sillä jos he nämät tekevät tuoreessa puussa, mitä sitte kuivassa tapahtuu?","Sillä jos he nämät tekevät tuoreessa puussa, mitä sitte kuivassa tapahtuu?"],[23,32,"Niin vietiin myös hänen kanssansa kaksi muuta pahantekiää surmattaa.","Niin vietiin myös hänen kanssansa kaksi muuta pahantekiää surmattaa."],[23,33,"Ja kuin he siihen siaan tulivat, joka Pääkallon paikaksi kutsutaan, siinä he hänen ristiinnaulitsivat ja ne pahantekiät, yhden oikialle ja toisen vasemmalle puolelle.","Ja kuin he siihen siaan tulivat, joka Pääkallon paikaksi kutsutaan, siinä he hänen ristiinnaulitsivat ja ne pahantekiät, yhden oikialle ja toisen vasemmalle puolelle."],[23,34,"Niin sanoi Jesus: Isä, anna heille anteeksi, sillä ei he tiedä, mitä he tekevät. Ja he jakoivat hänen vaatteensa ja heittivät niistä arpaa.","Niin sanoi Jesus: Isä, anna heille anteeksi, sillä ei he tiedä, mitä he tekevät. Ja he jakoivat hänen vaatteensa ja heittivät niistä arpaa."],[23,35,"Ja kansa seisoi ja katseli, mutta päämiehet pilkkasivat häntä heidän kanssansa ja sanoivat: muita hän vapahti, vapahtakaan itsensä, jos hän on Kristus, Jumalan valittu.","Ja kansa seisoi ja katseli, mutta päämiehet pilkkasivat häntä heidän kanssansa ja sanoivat: muita hän vapahti, vapahtakaan itsensä, jos hän on Kristus, Jumalan valittu."],[23,36,"Ja huovit myös pilkkasivat häntä, menivät ja kokottivat hänelle etikkaa,","Ja huovit myös pilkkasivat häntä, menivät ja kokottivat hänelle etikkaa,"],[23,37,"Ja sanoivat: jos olet Juudalaisten kuningas, niin vapahda itse sinus.","Ja sanoivat: jos olet Juudalaisten kuningas, niin vapahda itse sinus."],[23,38,"Oli myös hänestä päällekirjoitus Grekan, Latinan ja Hebrean puustaveilla kirjoitettu: Tämä on Juudalaisten kuningas.","Oli myös hänestä päällekirjoitus Grekan, Latinan ja Hebrean puustaveilla kirjoitettu: Tämä on Juudalaisten kuningas."],[23,39,"Niin yksi pahantekiöistä, jotka ripustetut olivat, pilkkasi häntä ja sanoi: jos sinä olet Kristus, niin vapahda sinus ja meitä.","Niin yksi pahantekiöistä, jotka ripustetut olivat, pilkkasi häntä ja sanoi: jos sinä olet Kristus, niin vapahda sinus ja meitä."],[23,40,"Mutta toinen vastasi ja nuhteli häntä sanoen: etkö sinäkään Jumalaa pelkää, ettäs olet yhdessä kadotuksessa?","Mutta toinen vastasi ja nuhteli häntä sanoen: etkö sinäkään Jumalaa pelkää, ettäs olet yhdessä kadotuksessa?"],[23,41,"Ja tosin me olemme oikein siinä, sillä me saamme meidän töidemme ansion jälkeen; mutta ei tämä mitään pahaa tehnyt.","Ja tosin me olemme oikein siinä, sillä me saamme meidän töidemme ansion jälkeen; mutta ei tämä mitään pahaa tehnyt."],[23,42,"Ja sanoi Jesukselle: Herra, muista minua, kuin tulet valtakuntaas.","Ja sanoi Jesukselle: Herra, muista minua, kuin tulet valtakuntaas."],[23,43,"Niin Jesus sanoi hänelle: totisesti sanon minä sinulle: tänäpänä pitää sinun oleman minun kanssani paradisissa.","Niin Jesus sanoi hänelle: totisesti sanon minä sinulle: tänäpänä pitää sinun oleman minun kanssani paradisissa."],[23,44,"Ja se oli lähes kuudes hetki, ja pimeys tuli kaiken maan päälle, hamaan yhdeksänteen hetkeen asti.","Ja se oli lähes kuudes hetki, ja pimeys tuli kaiken maan päälle, hamaan yhdeksänteen hetkeen asti."],[23,45,"Ja aurinko pimeni, ja templin esivaate repesi kahtia,","Ja aurinko pimeni, ja templin esivaate repesi kahtia,"],[23,46,"Ja Jesus huusi suurella äänellä ja sanoi: Isä, sinun käsiis minä annan henkeni. Ja kuin hän sen oli sanonut, antoi hän henkensä.","Ja Jesus huusi suurella äänellä ja sanoi: Isä, sinun käsiis minä annan henkeni. Ja kuin hän sen oli sanonut, antoi hän henkensä."],[23,47,"Mutta kuin sadanpäämies näki, mitä tapahtui, kunnioitti hän Jumalaa ja sanoi: tosin oli tämä ihminen hurskas.","Mutta kuin sadanpäämies näki, mitä tapahtui, kunnioitti hän Jumalaa ja sanoi: tosin oli tämä ihminen hurskas."],[23,48,"Ja kaikki kansa, joka sinne katselemaan meni, kuin he näkivät, mitä siellä tapahtui, löivät rintoihinsa ja palasivat kotiansa.","Ja kaikki kansa, joka sinne katselemaan meni, kuin he näkivät, mitä siellä tapahtui, löivät rintoihinsa ja palasivat kotiansa."],[23,49,"Mutta kaikki hänen tuttavansa seisoivat taampana ja vaimot, jotka häntä Galileasta seuranneet olivat, näkivät nämät.","Mutta kaikki hänen tuttavansa seisoivat taampana ja vaimot, jotka häntä Galileasta seuranneet olivat, näkivät nämät."],[23,50,"Ja katso, raatimies, nimeltä Joseph, joka oli jalo ja hurskas mies,","Ja katso, raatimies, nimeltä Joseph, joka oli jalo ja hurskas mies,"],[23,51,"Joka ei ollut mieltynyt heidän neuvoonsa ja tekoonsa, syntynyt Arimatiassa, Juudalaisten kaupungissa, joka myös itse odotti Jumalan valtakuntaa:","Joka ei ollut mieltynyt heidän neuvoonsa ja tekoonsa, syntynyt Arimatiassa, Juudalaisten kaupungissa, joka myös itse odotti Jumalan valtakuntaa:"],[23,52,"Tämä meni Pilatuksen tykö ja anoi Jesuksen ruumista,","Tämä meni Pilatuksen tykö ja anoi Jesuksen ruumista,"],[23,53,"Ja otti sen alas ja kääri liinavaatteesen ja pani sen hautaan, joka kallioon hakattu oli, johonka ei yksikään ennen pantu ollut.","Ja otti sen alas ja kääri liinavaatteesen ja pani sen hautaan, joka kallioon hakattu oli, johonka ei yksikään ennen pantu ollut."],[23,54,"Ja se oli valmistuspäivä, ja sabbati lähestyi.","Ja se oli valmistuspäivä, ja sabbati lähestyi."],[23,55,"Niin vaimot seurasivat jäljestä, jotka hänen kanssansa tulleet olivat Galileasta, ja katselivat hautaa, ja kuinka hänen ruumiinsa pantu oli.","Niin vaimot seurasivat jäljestä, jotka hänen kanssansa tulleet olivat Galileasta, ja katselivat hautaa, ja kuinka hänen ruumiinsa pantu oli."],[23,56,"Mutta he palasivat ja valmistivat hyvänhajuisia yrttejä ja voiteita; vaan sabbatina he lepäsivät lain käskyn jälkeen.","Mutta he palasivat ja valmistivat hyvänhajuisia yrttejä ja voiteita; vaan sabbatina he lepäsivät lain käskyn jälkeen."],[24,1,"Mutta ensimäisenä sabbatin päivänä, sangen varhain, tulivat he haudalle ja kantoivat hyvänhajuisia yrttejä, jotka he olivat valmistaneet, ja muutamat heidän kanssansa,","Mutta ensimäisenä sabbatin päivänä, sangen varhain, tulivat he haudalle ja kantoivat hyvänhajuisia yrttejä, jotka he olivat valmistaneet, ja muutamat heidän kanssansa,"],[24,2,"Niin he löysivät kiven haudalta vieritetyksi pois,","Niin he löysivät kiven haudalta vieritetyksi pois,"],[24,3,"Ja menivät siihen sisälle eikä löytäneet Herran Jesuksen ruumista.","Ja menivät siihen sisälle eikä löytäneet Herran Jesuksen ruumista."],[24,4,"Ja tapahtui, kuin he siitä epäilivät, katso, kaksi miestä seisoi heidän tykönänsä kiiltävissä vaatteissa.","Ja tapahtui, kuin he siitä epäilivät, katso, kaksi miestä seisoi heidän tykönänsä kiiltävissä vaatteissa."],[24,5,"Niin he peljästyivät ja löivät kasvonsa maata päin. He sanoivat heille: miksi te elävää kuolleiden seassa etsitte?","Niin he peljästyivät ja löivät kasvonsa maata päin. He sanoivat heille: miksi te elävää kuolleiden seassa etsitte?"],[24,6,"Ei hän ole täällä, mutta nousi ylös; muistakaat, kuinka hän teille sanoi, kuin hän vielä Galileassa oli,","Ei hän ole täällä, mutta nousi ylös; muistakaat, kuinka hän teille sanoi, kuin hän vielä Galileassa oli,"],[24,7,"Sanoen: Ihmisen Poika pitää annettaman ylön syntisten ihmisten käsiin, ja ristiinnaulittaman, ja kolmantena päivänä nouseman ylös.","Sanoen: Ihmisen Poika pitää annettaman ylön syntisten ihmisten käsiin, ja ristiinnaulittaman, ja kolmantena päivänä nouseman ylös."],[24,8,"Ja he muistivat hänen sanansa,","Ja he muistivat hänen sanansa,"],[24,9,"Ja palasivat jälleen haudalta ja ilmoittivat kaikki nämät yhdelletoistakymmenelle ja kaikille muille.","Ja palasivat jälleen haudalta ja ilmoittivat kaikki nämät yhdelletoistakymmenelle ja kaikille muille."],[24,10,"Ja ne olivat Maria Magdalena ja Johanna ja Maria, Jakobin äiti,ja muita heidän kanssansa, jotka näitä apostoleille ilmoittivat.","Ja ne olivat Maria Magdalena ja Johanna ja Maria, Jakobin äiti,ja muita heidän kanssansa, jotka näitä apostoleille ilmoittivat."],[24,11,"Ja heidän puheensa näkyi heille houraukseksi, eikä he uskoneet heitä.","Ja heidän puheensa näkyi heille houraukseksi, eikä he uskoneet heitä."],[24,12,"Mutta Pietari nousi ja juoksi haudalle, ja kuin hän kurkisti sisälle, näki hän ainoasti liinavaatteet pantuna, ja meni pois ihmetellen itsellänsä sitä, mikä tapahtunut oli.","Mutta Pietari nousi ja juoksi haudalle, ja kuin hän kurkisti sisälle, näki hän ainoasti liinavaatteet pantuna, ja meni pois ihmetellen itsellänsä sitä, mikä tapahtunut oli."],[24,13,"Ja katso, kaksi heistä meni sinä päivänä yhteen kylään, joka oli Jerusalemista kuudenkymmenen vakomitan päässä, Emaus nimeltä,","Ja katso, kaksi heistä meni sinä päivänä yhteen kylään, joka oli Jerusalemista kuudenkymmenen vakomitan päässä, Emaus nimeltä,"],[24,14,"Ja puhuivat keskenänsä kaikista niistä, mitkä tapahtunut oli.","Ja puhuivat keskenänsä kaikista niistä, mitkä tapahtunut oli."],[24,15,"Ja tapahtui heidän puhuissansa ja tutkistellessansa keskenänsä, että Jesus itse heitä lähestyi ja matkusti heidän kanssansa.","Ja tapahtui heidän puhuissansa ja tutkistellessansa keskenänsä, että Jesus itse heitä lähestyi ja matkusti heidän kanssansa."],[24,16,"Mutta heidän silmänsä pidettiin, ettei he häntä tunteneet.","Mutta heidän silmänsä pidettiin, ettei he häntä tunteneet."],[24,17,"Niin hän sanoi heille: mitkä puheet ne ovat, joita te pidätte keskenänne käydessänne, ja olette murheelliset?","Niin hän sanoi heille: mitkä puheet ne ovat, joita te pidätte keskenänne käydessänne, ja olette murheelliset?"],[24,18,"Niin vastasi yksi, Kleopas nimeltä, ja sanoi hänelle: oletkos ainoa muukalainen Jerusalemissa, joka et tiedä, mitä siellä näinä päivinä tapahtui?","Niin vastasi yksi, Kleopas nimeltä, ja sanoi hänelle: oletkos ainoa muukalainen Jerusalemissa, joka et tiedä, mitä siellä näinä päivinä tapahtui?"],[24,19,"Ja hän sanoi heille: mitä? He sanoivat hänelle: Jesuksesta Natsarealaisesta, joka oli väkevä propheta töissä ja sanoissa, Jumalan ja kaiken kansan edessä.","Ja hän sanoi heille: mitä? He sanoivat hänelle: Jesuksesta Natsarealaisesta, joka oli väkevä propheta töissä ja sanoissa, Jumalan ja kaiken kansan edessä."],[24,20,"Kuinka meidän ylimmäiset papit ja päämiehet antoivat ylön hänen kuoleman kadotukseen, ja ristiinnaulitsivat hänen.","Kuinka meidän ylimmäiset papit ja päämiehet antoivat ylön hänen kuoleman kadotukseen, ja ristiinnaulitsivat hänen."],[24,21,"Mutta me luulimme hänen siksi, joka Israelin piti lunastaman. Ja paitsi kaikkia näitä on jo kolmas päivä tänäpänä, kuin nämät tapahtuivat.","Mutta me luulimme hänen siksi, joka Israelin piti lunastaman. Ja paitsi kaikkia näitä on jo kolmas päivä tänäpänä, kuin nämät tapahtuivat."],[24,22,"Mutta myös muutamat vaimot meistä ovat meitä peljättäneet, jotka varhain aamulla tulivat haudalle,","Mutta myös muutamat vaimot meistä ovat meitä peljättäneet, jotka varhain aamulla tulivat haudalle,"],[24,23,"Ja kuin ei löytäneet hänen ruumistansa, tulivat he ja sanoivat, että he enkeleinkin näyn nähneet olivat, jotka sanoivat hänen elävän.","Ja kuin ei löytäneet hänen ruumistansa, tulivat he ja sanoivat, että he enkeleinkin näyn nähneet olivat, jotka sanoivat hänen elävän."],[24,24,"Ja muutamat niistä, jotka meidän kanssamme olivat, menivät haudalle ja löysivät niinkuin vaimot olivat sanoneet; mutta ei he häntä nähneet.","Ja muutamat niistä, jotka meidän kanssamme olivat, menivät haudalle ja löysivät niinkuin vaimot olivat sanoneet; mutta ei he häntä nähneet."],[24,25,"Ja hän sanoi heille: oi te tomppelit ja hitaan sydämestä uskomaan niitä kaikkia, mitä prophetat puhuneet ovat!","Ja hän sanoi heille: oi te tomppelit ja hitaan sydämestä uskomaan niitä kaikkia, mitä prophetat puhuneet ovat!"],[24,26,"Eikö Kristuksen pitänyt näitä kärsimän ja kunniaansa käymän sisälle?","Eikö Kristuksen pitänyt näitä kärsimän ja kunniaansa käymän sisälle?"],[24,27,"Ja hän rupesi Moseksesta ja kaikista prophetaista, ja selitti heille kirjoitukset, jotka hänestä olivat.","Ja hän rupesi Moseksesta ja kaikista prophetaista, ja selitti heille kirjoitukset, jotka hänestä olivat."],[24,28,"Ja he lähestyivät kylää, johonka he menivät, ja hän teetteli itsensä edemmä käymään.","Ja he lähestyivät kylää, johonka he menivät, ja hän teetteli itsensä edemmä käymään."],[24,29,"Ja he vaativat häntä, sanoen: ole meidän kanssamme, sillä ehtoo joutuu ja päivä on laskenut; ja hän meni olemaan heidän kanssansa.","Ja he vaativat häntä, sanoen: ole meidän kanssamme, sillä ehtoo joutuu ja päivä on laskenut; ja hän meni olemaan heidän kanssansa."],[24,30,"Ja tapahtui, kuin hän atrioitsi heidän kanssansa, otti hän leivän, kiitti, mursi ja antoi heille.","Ja tapahtui, kuin hän atrioitsi heidän kanssansa, otti hän leivän, kiitti, mursi ja antoi heille."],[24,31,"Niin heidän silmänsä aukenivat ja he tunsivat hänen. Ja hän katosi heidän edestänsä.","Niin heidän silmänsä aukenivat ja he tunsivat hänen. Ja hän katosi heidän edestänsä."],[24,32,"Ja he sanoivat keskenänsä: eikö meidän sydämemme meissä palanut, kuin hän tiellä meitä puhutteli ja selitti meille kirjoitukset?","Ja he sanoivat keskenänsä: eikö meidän sydämemme meissä palanut, kuin hän tiellä meitä puhutteli ja selitti meille kirjoitukset?"],[24,33,"Ja he nousivat sillä hetkellä ja palasivat Jerusalemiin, ja löysivät ne yksitoistakymmentä koossa ja ne, jotka niiden kanssa olivat,","Ja he nousivat sillä hetkellä ja palasivat Jerusalemiin, ja löysivät ne yksitoistakymmentä koossa ja ne, jotka niiden kanssa olivat,"],[24,34,"Jotka sanoivat: Herra on totisesti noussut ylös ja ilmaantui Simonille.","Jotka sanoivat: Herra on totisesti noussut ylös ja ilmaantui Simonille."],[24,35,"Ja he juttelivat heille, mitä tiellä tapahtunut oli, ja kuinka hän heiltä oli tuttu leivän murtamisessa.","Ja he juttelivat heille, mitä tiellä tapahtunut oli, ja kuinka hän heiltä oli tuttu leivän murtamisessa."],[24,36,"Mutta kuin he näitä puhuivat, seisoi itse Jesus heidän keskellänsä ja sanoi heille: rauha olkoon teille!","Mutta kuin he näitä puhuivat, seisoi itse Jesus heidän keskellänsä ja sanoi heille: rauha olkoon teille!"],[24,37,"Niin he hämmästyivät ja peljästyivät, ja luulivat näkevänsä hengen.","Niin he hämmästyivät ja peljästyivät, ja luulivat näkevänsä hengen."],[24,38,"Ja hän sanoi heille: mitä te pelkäätte? ja miksi senkaltaiset ajatukset tulevat sydämeenne?","Ja hän sanoi heille: mitä te pelkäätte? ja miksi senkaltaiset ajatukset tulevat sydämeenne?"],[24,39,"Katsokaat käsiäni ja jalkojani, että minä itse olen: ruvetkaat minuun ja katsokaat; sillä ei hengellä ole lihaa eikä luita, niinkuin näette minulla olevan.","Katsokaat käsiäni ja jalkojani, että minä itse olen: ruvetkaat minuun ja katsokaat; sillä ei hengellä ole lihaa eikä luita, niinkuin näette minulla olevan."],[24,40,"Ja kuin hän nämät sanonut oli, osoitti hän heille kätensä ja jalkansa.","Ja kuin hän nämät sanonut oli, osoitti hän heille kätensä ja jalkansa."],[24,41,"Mutta koska ei he vielä uskoneet ilon tähden, vaan ihmettelivät, sanoi hän heille: onko teillä tässä mitään syötävää?","Mutta koska ei he vielä uskoneet ilon tähden, vaan ihmettelivät, sanoi hän heille: onko teillä tässä mitään syötävää?"],[24,42,"Niin he panivat hänen eteensä kappaleen paistettua kalaa ja vähän kimalaisen hunajaa.","Niin he panivat hänen eteensä kappaleen paistettua kalaa ja vähän kimalaisen hunajaa."],[24,43,"Ja hän otti sen ja söi heidän nähtensä.","Ja hän otti sen ja söi heidän nähtensä."],[24,44,"Niin hän sanoi heille: nämät ovat ne sanat, jotka minä puhuin teille, kuin minä vielä tiedän kanssanne olin; sillä kaikki pitää täytettämän, mitä kirjoitettu on Moseksen laissa ja prophetaissa ja psalmeissa minusta.","Niin hän sanoi heille: nämät ovat ne sanat, jotka minä puhuin teille, kuin minä vielä tiedän kanssanne olin; sillä kaikki pitää täytettämän, mitä kirjoitettu on Moseksen laissa ja prophetaissa ja psalmeissa minusta."],[24,45,"Silloin hän avasi heidän ymmärryksensä, kirjoituksia ymmärtämään,","Silloin hän avasi heidän ymmärryksensä, kirjoituksia ymmärtämään,"],[24,46,"Ja sanoi heille: niin on kirjoitettu, ja niin tuli Kristuksen kärsiä ja nousta kuolleista kolmantena päivänä,","Ja sanoi heille: niin on kirjoitettu, ja niin tuli Kristuksen kärsiä ja nousta kuolleista kolmantena päivänä,"],[24,47,"Ja saarnattaman hänen nimeensä parannusta ja syntein anteeksi antamusta kaikissa kansoissa, ruveten Jerusalemista.","Ja saarnattaman hänen nimeensä parannusta ja syntein anteeksi antamusta kaikissa kansoissa, ruveten Jerusalemista."],[24,48,"Mutta te olette näiden todistajat.","Mutta te olette näiden todistajat."],[24,49,"Ja katso, minä lähetän minun Isäni lupauksen teidän päällenne. Mutta te olkaat Jerusalemissa siihenasti kuin te puetetaan voimalla korkeudesta.","Ja katso, minä lähetän minun Isäni lupauksen teidän päällenne. Mutta te olkaat Jerusalemissa siihenasti kuin te puetetaan voimalla korkeudesta."],[24,50,"Niin hän vei heidät ulos hamaan Betaniaan, ja nosti kätensä ja siunasi heitä.","Niin hän vei heidät ulos hamaan Betaniaan, ja nosti kätensä ja siunasi heitä."],[24,51,"Ja tapahtui, kuin hän heitä siunannut oli, erkani hän heistä ja meni ylös taivaasen.","Ja tapahtui, kuin hän heitä siunannut oli, erkani hän heistä ja meni ylös taivaasen."],[24,52,"Mutta kuin he häntä kumartaneet ja rukoilleet olivat, palasivat he Jerusalemiin suurella ilolla,","Mutta kuin he häntä kumartaneet ja rukoilleet olivat, palasivat he Jerusalemiin suurella ilolla,"],[24,53,"Ja olivat aina templissä, kiittivät ja kunnioittivat Jumalaa. Amen!","Ja olivat aina templissä, kiittivät ja kunnioittivat Jumalaa. Amen!"]]}};